insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tartiflette', 'Tartiflette', array['en:tartiflette savoyarde']::text[], 'dish', $r$[{"title":"Tartiflette with reblochon","intro":"The great Savoyard classic: soft potatoes, bacon lardons and a reblochon that melts and browns.","minutes":60,"calories":750,"difficulty":"Facile","imageSearch":"tartiflette potato gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the whole potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Preheat the oven to 200 °C. Cut the potatoes into slices.","timer":null},{"text":"Fry the sliced onions and the lardons in a pan for 8 min, then pour in the white wine.","timer":{"label":"Pan","min":8}},{"text":"In a dish, layer potatoes, lardons and cream. Place the reblochon on top, cut in half, rind up.","timer":null},{"text":"Bake for 25 min, until nicely golden.","timer":{"label":"Oven","min":25}}],"kids":true,"variant":"The classic","change":""},{"title":"Lighter tartiflette","intro":"All the indulgence of tartiflette, but lighter for a weekday.","minutes":55,"calories":520,"difficulty":"Facile","imageSearch":"light tartiflette potato","veg":false,"oven":true,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"diced ham","plural":"diced ham","qty":150,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":200,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Preheat the oven to 200 °C. Cut the potatoes into slices.","timer":null},{"text":"Fry the sliced onions with the ham in a pan for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Mix the fromage blanc with salt and pepper, then stir in the potatoes, onion and ham.","timer":null},{"text":"Pour into a dish, add half a reblochon in slices and bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"Lighter","change":"The cream is replaced with fromage blanc and the reblochon is halved."},{"title":"Mushroom tartiflette","intro":"Golden mushrooms instead of lardons: the reblochon does the rest.","minutes":60,"calories":680,"difficulty":"Facile","imageSearch":"mushroom tartiflette gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"Savoyard speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"reblochon","plural":"reblochons","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Preheat the oven to 200 °C. Cut the potatoes into slices.","timer":null},{"text":"Brown the sliced mushrooms and the onions in a pan for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Layer potatoes, mushrooms and cream in a dish, then place the reblochon on top, cut in half.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"Vegetarian","change":"The lardons are replaced with well-browned mushrooms."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gratin dauphinoi', 'Gratin dauphinois', array['en:potato gratin', 'en:homemade gratin dauphinoi']::text[], 'dish', $r$[{"title":"Gratin dauphinois","intro":"Soft potatoes cooked slowly in milk and cream, flavoured with garlic.","minutes":80,"calories":420,"difficulty":"Facile","imageSearch":"potato gratin dauphinois","veg":true,"oven":true,"cold":false,"missing":"","origin":"Dauphiné speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"single cream","plural":"single cream","qty":30,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Peel the potatoes and cut them into thin slices, without washing them.","timer":null},{"text":"Heat the milk, cream and crushed garlic with salt, pepper and nutmeg. Add the potatoes and simmer for 10 min, stirring.","timer":{"label":"Simmer","min":10}},{"text":"Butter a gratin dish and pour everything in.","timer":null},{"text":"Bake for 1 h, until the top is golden and a knife slides in easily.","timer":{"label":"Oven","min":60}}],"kids":true,"variant":"The classic","change":""},{"title":"Lighter gratin dauphinois","intro":"The same melt-in-the-mouth texture with just milk: lighter and still delicious.","minutes":80,"calories":300,"difficulty":"Facile","imageSearch":"light potato gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"Dauphiné speciality","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"semi-skimmed milk","plural":"semi-skimmed milk","qty":80,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Cut the peeled potatoes into thin slices.","timer":null},{"text":"Simmer the milk with the crushed garlic, salt, pepper and nutmeg, add the potatoes and cook for 15 min.","timer":{"label":"Simmer","min":15}},{"text":"Pour into a gratin dish.","timer":null},{"text":"Bake for 1 h, until golden.","timer":{"label":"Oven","min":60}}],"variant":"Lighter","change":"The cream is replaced with extra milk, and the butter is left out."},{"title":"Cheesy gratin dauphinois","intro":"The classic, with a golden, stretchy comté topping.","minutes":80,"calories":520,"difficulty":"Facile","imageSearch":"cheese potato gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1200,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"single cream","plural":"single cream","qty":30,"unit":"cl","have":false},{"name":"grated comté","plural":"grated comté","qty":100,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 160 °C. Cut the peeled potatoes into thin slices.","timer":null},{"text":"Simmer the milk, cream and garlic with salt, pepper and nutmeg. Add the potatoes and cook for 10 min.","timer":{"label":"Simmer","min":10}},{"text":"Pour into a dish and cover with grated comté.","timer":null},{"text":"Bake for 1 h, until the cheese is nicely browned.","timer":{"label":"Oven","min":60}}],"kids":true,"variant":"Cheesy","change":"A layer of grated comté browns on top."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:blanquette de veau', 'Blanquette de veau', array['en:blanquette', 'en:veal blanquette']::text[], 'dish', $r$[{"title":"Veal blanquette","intro":"Grandma's blanquette: tender veal in a creamy lemon sauce, with mushrooms and carrots.","minutes":120,"calories":560,"difficulty":"Moyen","imageSearch":"veal blanquette stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"veal shoulder","plural":"veal shoulders","qty":1000,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"egg yolk","plural":"egg yolks","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":40,"unit":"g","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the meat into large cubes and put it in a casserole dish with the sliced carrots, the onion and the bouquet garni. Cover with cold salted water.","timer":null},{"text":"Bring to the boil, skim, then cover and simmer for 1 h 30.","timer":{"label":"Simmer","min":90}},{"text":"Fry the sliced mushrooms in a little butter for 5 min.","timer":{"label":"Pan","min":5}},{"text":"In a saucepan, melt the rest of the butter, add the flour, then 50 cl of the cooking stock, whisking until thickened.","timer":null},{"text":"Off the heat, add the cream, the egg yolk and the lemon juice.","timer":null},{"text":"Drain the meat and carrots, stir them into the sauce with the mushrooms and serve with rice.","timer":null}],"variant":"The classic","change":""},{"title":"Lighter veal blanquette","intro":"All the gentleness of blanquette, with a lighter fromage blanc sauce.","minutes":110,"calories":400,"difficulty":"Moyen","imageSearch":"light veal stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"veal shoulder","plural":"veal shoulders","qty":1000,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":200,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the cubed meat, sliced carrots, onion and bouquet garni in a casserole dish. Cover with cold salted water.","timer":null},{"text":"Bring to the boil, skim and simmer for 1 h 30.","timer":{"label":"Simmer","min":90}},{"text":"Add the sliced mushrooms 15 min before the end.","timer":null},{"text":"Mix the cornflour with a little cold water, add it to 50 cl of stock and thicken for 2 min, stirring.","timer":null},{"text":"Off the heat, add the fromage blanc and lemon juice, then mix with the meat and vegetables.","timer":null}],"variant":"Lighter","change":"The cream is replaced with fromage blanc and there is no roux."},{"title":"Chicken blanquette","intro":"A quicker, cheaper blanquette made with chicken thighs.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"chicken blanquette creamy","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":8,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":30,"unit":"g","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the chicken, sliced carrots, onion and stock cube in a casserole dish. Cover with water.","timer":null},{"text":"Cover and simmer for 40 min.","timer":{"label":"Simmer","min":40}},{"text":"Fry the sliced mushrooms in a little butter for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Make a roux with the butter and flour, then add 40 cl of stock, whisking.","timer":null},{"text":"Add the cream and lemon juice, then the chicken, carrots and mushrooms. Serve with rice.","timer":null}],"kids":true,"variant":"With chicken","change":"The veal is replaced with chicken, which cooks twice as fast."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:boeuf bourguignon', 'Bœuf bourguignon', array['en:bourguignon', 'en:beef burgundy']::text[], 'dish', $r$[{"title":"Beef bourguignon","intro":"The ultimate slow-cooked dish: tender beef in red wine, with lardons, mushrooms and baby onions.","minutes":210,"calories":650,"difficulty":"Moyen","imageSearch":"beef bourguignon stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"Burgundy speciality","serves":4,"items":[{"name":"braising beef","plural":"braising beef","qty":1200,"unit":"g","have":false},{"name":"red wine","plural":"red wine","qty":75,"unit":"cl","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"plain flour","plural":"plain flour","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the beef into large cubes and brown them in batches in the oil in a casserole dish. Set aside.","timer":null},{"text":"Fry the lardons, the sliced onions and the sliced carrots for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Put the meat back, sprinkle with flour and stir for 1 min.","timer":null},{"text":"Pour in the wine, add the garlic, bouquet garni, salt and pepper. Top up with water to cover.","timer":null},{"text":"Cover and simmer on a low heat for 3 h.","timer":{"label":"Simmer","min":180}},{"text":"Add the mushrooms 30 min before the end. Serve with potatoes or pasta.","timer":null}],"variant":"The classic","change":""},{"title":"Quick beef bourguignon","intro":"The taste of bourguignon for a weeknight, thanks to the pressure cooker.","minutes":75,"calories":620,"difficulty":"Facile","imageSearch":"quick beef stew red wine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Burgundy speciality","serves":4,"items":[{"name":"braising beef","plural":"braising beef","qty":1000,"unit":"g","have":false},{"name":"red wine","plural":"red wine","qty":50,"unit":"cl","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the cubed beef in the oil, straight in the pressure cooker, then the lardons and onions.","timer":null},{"text":"Sprinkle with flour, stir, then add the wine, sliced carrots, bouquet garni, salt and pepper.","timer":null},{"text":"Close the lid and cook for 45 min once the valve starts to hiss.","timer":{"label":"Pressure cooker","min":45}},{"text":"Open, add the sliced mushrooms and simmer uncovered for 10 min.","timer":{"label":"Cooking","min":10}}],"variant":"Quick","change":"Cooked in a pressure cooker: 1 h instead of 3 h."},{"title":"Vegetable bourguignon","intro":"A rich, fragrant red wine sauce full of mushrooms and tender vegetables.","minutes":75,"calories":380,"difficulty":"Facile","imageSearch":"vegetable bourguignon mushrooms","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"button mushroom","plural":"button mushrooms","qty":500,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":4,"unit":"","have":false},{"name":"parsnip","plural":"parsnips","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red wine","plural":"red wine","qty":50,"unit":"cl","have":false},{"name":"tomato purée","plural":"tomato purée","qty":1,"unit":"tbsp","have":false},{"name":"plain flour","plural":"plain flour","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the sliced onions in the oil for 5 min in a casserole dish.","timer":{"label":"Cooking","min":5}},{"text":"Add the carrots and parsnips in big chunks, then the mushrooms, halved. Brown for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Sprinkle with flour, add the tomato purée, then the wine and 20 cl of water.","timer":null},{"text":"Add the thyme, salt and pepper, cover and simmer for 45 min.","timer":{"label":"Simmer","min":45}}],"variant":"Vegetarian","change":"Mushrooms and root vegetables replace the meat."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pot au feu', 'Pot-au-feu', array['en:french beef stew']::text[], 'dish', $r$[{"title":"Pot-au-feu","intro":"The Sunday family dish: beef cooked for hours in a fragrant broth, with its vegetables.","minutes":240,"calories":580,"difficulty":"Facile","imageSearch":"pot au feu beef vegetables","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef short rib","plural":"beef short ribs","qty":800,"unit":"g","have":false},{"name":"beef chuck","plural":"beef chuck","qty":800,"unit":"g","have":false},{"name":"marrow bone","plural":"marrow bones","qty":4,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":6,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":3,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":8,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"clove","plural":"cloves","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"coarse salt","plural":"coarse salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the meat in a large pot, cover with cold water and bring to the boil. Skim.","timer":null},{"text":"Add the onion studded with the cloves, the bouquet garni and the coarse salt. Simmer for 2 h.","timer":{"label":"Simmer","min":120}},{"text":"Add the carrots, leeks and turnips cut into chunks, and the marrow bones. Cook for 45 min.","timer":{"label":"Cooking","min":45}},{"text":"Cook the potatoes separately in a little stock for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Serve the meat and vegetables with coarse salt, mustard and gherkins, and the broth on the side.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Chicken pot-au-feu","intro":"A lighter, quicker version with a whole chicken and its vegetables.","minutes":120,"calories":480,"difficulty":"Facile","imageSearch":"chicken pot au feu","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"whole chicken","plural":"whole chickens","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":6,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":3,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":8,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"clove","plural":"cloves","qty":2,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"coarse salt","plural":"coarse salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the chicken in a pot, cover with cold water and bring to the boil. Skim.","timer":null},{"text":"Add the onion studded with the cloves, the bouquet garni and the salt. Simmer for 45 min.","timer":{"label":"Simmer","min":45}},{"text":"Add the carrots, leeks, turnips and potatoes. Cook for another 40 min.","timer":{"label":"Cooking","min":40}},{"text":"Carve the chicken and serve it with the vegetables and a little broth.","timer":null}],"kids":true,"variant":"With chicken","change":"A hen or chicken replaces the beef: it is the poule au pot."},{"title":"Pressure cooker pot-au-feu","intro":"The real pot-au-feu, even on a weekday.","minutes":80,"calories":560,"difficulty":"Facile","imageSearch":"pressure cooker pot au feu","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"beef short rib","plural":"beef short ribs","qty":700,"unit":"g","have":false},{"name":"beef chuck","plural":"beef chuck","qty":700,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":5,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":2,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"coarse salt","plural":"coarse salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the meat in the pressure cooker with the onion, bouquet garni and salt. Cover with water and skim as it comes to the boil.","timer":null},{"text":"Close the lid and cook for 40 min once the valve starts to hiss.","timer":{"label":"Pressure cooker","min":40}},{"text":"Open, add all the vegetables in big chunks, close and cook for 15 min.","timer":{"label":"Pressure cooker","min":15}},{"text":"Serve with mustard and gherkins.","timer":null}],"kids":true,"variant":"Quick","change":"In a pressure cooker, the meat is ready in 1 h instead of 3."}]$r$::jsonb, 'claude')
