insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:hachi parmentier', 'Hachis parmentier', array['en:parmentier', 'en:shepherd s pie', 'en:cottage pie']::text[], 'dish', $r$[{"title":"Hachis parmentier","intro":"Golden homemade mash on top of seasoned minced meat: pure comfort.","minutes":60,"calories":620,"difficulty":"Facile","imageSearch":"shepherds pie beef mash","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":60,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the peeled potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Fry the sliced onions and the garlic, then the meat for 8 min. Add salt, pepper and parsley.","timer":{"label":"Pan","min":8}},{"text":"Mash the potatoes with the butter and hot milk.","timer":null},{"text":"Preheat the oven to 200 °C. Put the meat in a dish, cover with mash and sprinkle with emmental.","timer":null},{"text":"Bake for 20 min, until the top is golden.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"The classic","change":""},{"title":"Sweet potato hachis parmentier","intro":"An orange, slightly sweet mash on minced meat: kids love it.","minutes":60,"calories":560,"difficulty":"Facile","imageSearch":"sweet potato shepherds pie","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":600,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":400,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":50,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the peeled sweet potatoes and potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Fry the onions, then the meat for 8 min, with salt and pepper.","timer":{"label":"Pan","min":8}},{"text":"Mash the vegetables with the butter and milk.","timer":null},{"text":"Preheat the oven to 200 °C. Put the meat in a dish, cover with mash and emmental.","timer":null},{"text":"Bake for 20 min.","timer":{"label":"Oven","min":20}}],"kids":true,"variant":"Sweet potato","change":"The mash is made with half sweet potato, which is sweeter and more colourful."},{"title":"Vegetarian lentil hachis parmentier","intro":"Lentils simmered with carrots and tomato, under a golden mash.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"lentil shepherds pie vegetarian","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":1000,"unit":"g","have":false},{"name":"green lentil","plural":"green lentils","qty":250,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tomato purée","plural":"tomato purée","qty":2,"unit":"tbsp","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"grated emmental","plural":"grated emmental","qty":50,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the lentils in unsalted water for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Boil the peeled potatoes in salted water for 20 min, then mash them with the butter and milk.","timer":{"label":"Cooking","min":20}},{"text":"Fry the diced onion and carrots for 10 min, then add the drained lentils and the tomato purée.","timer":{"label":"Pan","min":10}},{"text":"Preheat the oven to 200 °C. Put the lentils in a dish, cover with mash and emmental.","timer":null},{"text":"Bake for 20 min.","timer":{"label":"Oven","min":20}}],"variant":"Vegetarian","change":"Lentils and carrots replace the minced meat."}]$r$::jsonb, 'claude')
