insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:quiche lorraine', 'Quiche lorraine', array['en:quiche']::text[], 'dish', $r$[{"title":"Quiche lorraine","intro":"The real quiche lorraine: crisp pastry, lardons and a creamy egg filling.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"quiche lorraine","veg":false,"oven":true,"cold":false,"missing":"","origin":"Lorraine speciality","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry into a tin and prick the base.","timer":null},{"text":"Fry the lardons in a pan for 5 min with no added fat, and spread them over the pastry.","timer":{"label":"Pan","min":5}},{"text":"Beat the eggs with the cream, milk, a little salt, pepper and the nutmeg.","timer":null},{"text":"Pour over the lardons and bake for 35 min, until golden.","timer":{"label":"Oven","min":35}}],"kids":true,"variant":"The classic","change":""},{"title":"Lighter quiche lorraine","intro":"All the flavour of quiche, with a lighter filling.","minutes":50,"calories":420,"difficulty":"Facile","imageSearch":"light ham quiche","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"diced ham","plural":"diced ham","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"semi-skimmed milk","plural":"semi-skimmed milk","qty":40,"unit":"cl","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry into a tin and prick the base.","timer":null},{"text":"Spread the diced ham over the pastry.","timer":null},{"text":"Beat the eggs with the milk, nutmeg, salt and pepper.","timer":null},{"text":"Pour in and bake for 35 min.","timer":{"label":"Oven","min":35}}],"variant":"Lighter","change":"The cream is replaced with milk and the lardons with ham."},{"title":"Leek and goat's cheese quiche","intro":"A mild, fragrant quiche with soft leeks and goat's cheese.","minutes":55,"calories":500,"difficulty":"Facile","imageSearch":"leek goat cheese quiche","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":2,"unit":"","have":false},{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry into a tin.","timer":null},{"text":"Slice the leeks and soften them in the butter for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Beat the eggs with the cream, milk, salt and pepper.","timer":null},{"text":"Spread the leeks over the pastry, pour in the filling and add the goat's cheese in slices.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"variant":"Vegetarian","change":"The lardons are replaced with softened leeks and goat's cheese."}]$r$::jsonb, 'claude')
