insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:croque monsieur', 'Croque-monsieur', array['en:croque']::text[], 'dish', $r$[{"title":"Croque-monsieur","intro":"The golden, melting croque, with ham, emmental and a touch of béchamel.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"croque monsieur ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sandwich bread","plural":"sandwich breads","qty":8,"unit":"slices","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"plain flour","plural":"plain flour","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Make a small béchamel: melt 15 g of butter, add the flour, then the milk, whisking for 3 min.","timer":{"label":"Béchamel","min":3}},{"text":"Preheat the oven to 220 °C. Lightly butter the outside of the bread slices.","timer":null},{"text":"Top 4 slices with béchamel, ham and emmental, then cover with the other slices.","timer":null},{"text":"Add a little béchamel and emmental on top.","timer":null},{"text":"Bake for 10 min, until nicely golden.","timer":{"label":"Oven","min":10}}],"kids":true,"makes":{"n":4,"one":"toastie","many":"toasties"},"variant":"The classic","change":""},{"title":"Croque-madame","intro":"The croque-monsieur, topped with a runny fried egg.","minutes":25,"calories":540,"difficulty":"Facile","imageSearch":"croque madame egg","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sandwich bread","plural":"sandwich breads","qty":8,"unit":"slices","have":false},{"name":"cooked ham","plural":"cooked ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C. Butter the outside of the bread slices.","timer":null},{"text":"Top 4 slices with ham and emmental, cover with the other slices and sprinkle with emmental.","timer":null},{"text":"Bake for 10 min.","timer":{"label":"Oven","min":10}},{"text":"Meanwhile, fry the eggs for 3 min.","timer":{"label":"Pan","min":3}},{"text":"Put an egg on each croque and serve.","timer":null}],"kids":true,"makes":{"n":4,"one":"toastie","many":"toasties"},"variant":"With an egg","change":"A fried egg is placed on top of the croque."},{"title":"Vegetarian croque-monsieur","intro":"A tasty croque with mushrooms, tomato and emmental.","minutes":20,"calories":400,"difficulty":"Facile","imageSearch":"vegetarian toasted sandwich mushroom","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sandwich bread","plural":"sandwich breads","qty":8,"unit":"slices","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":150,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"grated emmental","plural":"grated emmental","qty":120,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the sliced mushrooms in a little butter for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Preheat the oven to 220 °C. Butter the outside of the bread slices.","timer":null},{"text":"Top 4 slices with mushrooms, tomato slices and emmental, then cover.","timer":null},{"text":"Sprinkle with emmental and bake for 10 min.","timer":{"label":"Oven","min":10}}],"kids":true,"makes":{"n":4,"one":"toastie","many":"toasties"},"variant":"Vegetarian","change":"The ham is replaced with tomato and mushrooms."}]$r$::jsonb, 'claude')
