insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:coq au vin', 'Coq au vin', array['en:chicken in red wine']::text[], 'dish', $r$[{"title":"Coq au vin","intro":"The great slow-cooked classic: tender chicken in a red wine sauce, with lardons and mushrooms.","minutes":120,"calories":620,"difficulty":"Moyen","imageSearch":"coq au vin chicken red wine","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken pieces","plural":"chicken pieces","qty":1,"unit":"","have":false},{"name":"red wine","plural":"red wine","qty":75,"unit":"cl","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"plain flour","plural":"plain flour","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken pieces in the oil in a casserole dish. Set aside.","timer":null},{"text":"Fry the lardons, onions and carrots for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Put the chicken back, sprinkle with flour and stir.","timer":null},{"text":"Pour in the wine, add the garlic, bouquet garni, salt and pepper. Cover and simmer for 1 h 15.","timer":{"label":"Simmer","min":75}},{"text":"Add the mushrooms and cook for another 20 min.","timer":{"label":"Cooking","min":20}}],"variant":"The classic","change":""},{"title":"Coq au vin blanc","intro":"A milder version made with white wine, in a creamy sauce.","minutes":90,"calories":580,"difficulty":"Moyen","imageSearch":"chicken white wine cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken pieces","plural":"chicken pieces","qty":1,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":50,"unit":"cl","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":150,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in the oil in a casserole dish, then the lardons and onions.","timer":null},{"text":"Pour in the white wine, add the thyme, salt and pepper. Cover and simmer for 50 min.","timer":{"label":"Simmer","min":50}},{"text":"Add the sliced mushrooms and cook for 15 min.","timer":{"label":"Cooking","min":15}},{"text":"Add the cream and let it reduce for 5 min.","timer":{"label":"Cooking","min":5}}],"variant":"White wine","change":"The red wine is replaced with white wine and a little cream."},{"title":"Quick chicken in red wine","intro":"The taste of the classic, on a weeknight.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"quick chicken red wine stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":8,"unit":"","have":false},{"name":"red wine","plural":"red wine","qty":40,"unit":"cl","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":100,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"plain flour","plural":"plain flour","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in the oil for 8 min, then the lardons and the sliced onion.","timer":{"label":"Cooking","min":8}},{"text":"Sprinkle with flour, pour in the wine, add salt and pepper.","timer":null},{"text":"Add the mushrooms, cover and simmer for 30 min.","timer":{"label":"Simmer","min":30}}],"variant":"Quick","change":"With boneless thighs, it is ready in under an hour."}]$r$::jsonb, 'claude')
