insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet basquaise', 'Poulet basquaise', array['en:basquaise', 'en:basque chicken']::text[], 'dish', $r$[{"title":"Chicken basquaise","intro":"Chicken simmered with peppers, tomatoes and Espelette pepper: the sunshine of the Basque Country.","minutes":70,"calories":480,"difficulty":"Facile","imageSearch":"basque chicken peppers","veg":false,"oven":false,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"chicken pieces","plural":"chicken pieces","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken pieces in the oil in a casserole dish. Set aside.","timer":null},{"text":"Fry the onions, garlic and sliced peppers for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the chopped tomatoes, the wine, the Espelette pepper, salt and pepper.","timer":null},{"text":"Put the chicken back, cover and simmer for 45 min.","timer":{"label":"Simmer","min":45}}],"kids":true,"variant":"The classic","change":""},{"title":"Quick chicken basquaise","intro":"The flavours of basquaise, for a busy evening.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"quick chicken peppers tomato","veg":false,"oven":false,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and brown it in the oil for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Add the onion, garlic and sliced peppers, and cook for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Pour in the tomatoes, add the Espelette pepper, salt and pepper, and simmer for 15 min.","timer":{"label":"Simmer","min":15}}],"kids":true,"variant":"Quick","change":"Chicken breasts and tinned tomatoes: ready in 30 minutes."},{"title":"Vegetable and chickpea basquaise","intro":"Slow-cooked piperade and tender chickpeas, for a sunny veggie dish.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"basque peppers chickpeas stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"Basque speciality","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"espelette pepper","plural":"espelette pepper","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, garlic and sliced peppers in the oil for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the chopped tomatoes, the Espelette pepper, salt and pepper, and simmer for 15 min.","timer":{"label":"Simmer","min":15}},{"text":"Add the drained chickpeas and cook for another 5 min.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"The chicken is replaced with chickpeas."}]$r$::jsonb, 'claude')
