insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet roti', 'Poulet rôti', array['en:roast chicken', 'en:sunday roast chicken']::text[], 'dish', $r$[{"title":"Roast chicken","intro":"A golden, crispy chicken with homemade gravy and roast potatoes.","minutes":90,"calories":620,"difficulty":"Facile","imageSearch":"roast chicken potatoes","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"whole chicken","plural":"whole chickens","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 210 °C. Take the chicken out of the fridge 30 min beforehand.","timer":null},{"text":"Rub the chicken with the soft butter, salt, pepper and thyme. Put the garlic inside.","timer":null},{"text":"Place it in a dish, surrounded by the potatoes cut into chunks and tossed in oil.","timer":null},{"text":"Pour a glass of water into the dish and bake for 1 h 15, basting every 20 min.","timer":{"label":"Oven","min":75}},{"text":"Rest for 10 min under a sheet of foil before carving.","timer":{"label":"Rest","min":10}}],"kids":true,"variant":"The classic","change":""},{"title":"Lemon and herb roast chicken","intro":"A fresh roast chicken with lemon and rosemary.","minutes":90,"calories":580,"difficulty":"Facile","imageSearch":"lemon herb roast chicken","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"whole chicken","plural":"whole chickens","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"rosemary","plural":"rosemary","qty":null,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 210 °C.","timer":null},{"text":"Put a lemon cut into quarters, the garlic and the rosemary inside the chicken. Rub it with oil, salt and pepper.","timer":null},{"text":"Surround it with the potatoes and the other lemon in wedges.","timer":null},{"text":"Bake for 1 h 15, basting regularly.","timer":{"label":"Oven","min":75}},{"text":"Rest for 10 min before serving.","timer":{"label":"Rest","min":10}}],"variant":"Lemon and herbs","change":"The chicken is flavoured with lemon, garlic and rosemary."},{"title":"Roast chicken legs","intro":"The taste of Sunday chicken, in 45 minutes.","minutes":45,"calories":560,"difficulty":"Facile","imageSearch":"roasted chicken legs","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken leg","plural":"chicken legs","qty":4,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 220 °C.","timer":null},{"text":"Mix the oil, paprika, thyme, salt and pepper, and brush over the legs.","timer":null},{"text":"Put them in a dish with the potatoes in wedges and the garlic.","timer":null},{"text":"Bake for 40 min, until the skin is really crispy.","timer":{"label":"Oven","min":40}}],"kids":true,"variant":"Quick","change":"Legs instead of a whole chicken: half the cooking time."}]$r$::jsonb, 'claude')
