insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:ratatouille', 'Ratatouille', array['en:ratatouille nicoise']::text[], 'dish', $r$[{"title":"Ratatouille","intro":"Sun-ripened vegetables slowly simmered in olive oil and herbes de Provence.","minutes":75,"calories":220,"difficulty":"Facile","imageSearch":"ratatouille provencal vegetables","veg":true,"oven":false,"cold":false,"missing":"","origin":"Niçoise speciality","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"yellow pepper","plural":"yellow peppers","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"herbes de provence","plural":"herbes de provence","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut all the vegetables into dice of the same size.","timer":null},{"text":"Fry the onions and garlic in the oil for 5 min in a casserole dish.","timer":{"label":"Cooking","min":5}},{"text":"Add the peppers and aubergines and cook for 10 min, stirring.","timer":{"label":"Cooking","min":10}},{"text":"Add the courgettes, tomatoes, herbs, salt and pepper.","timer":null},{"text":"Simmer covered for 45 min, then uncovered for 10 min to reduce.","timer":{"label":"Simmer","min":55}}],"variant":"The classic","change":""},{"title":"Oven-baked ratatouille","intro":"Roasted, caramelised vegetables with almost nothing to do.","minutes":60,"calories":230,"difficulty":"Facile","imageSearch":"roasted ratatouille vegetables tray","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":250,"unit":"g","have":false},{"name":"red onion","plural":"red onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"herbes de provence","plural":"herbes de provence","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Cut the vegetables into big chunks and put them on a tray with the garlic and cherry tomatoes.","timer":null},{"text":"Drizzle with oil, add the herbs, salt and pepper, and mix.","timer":null},{"text":"Bake for 45 min, stirring halfway.","timer":{"label":"Oven","min":45}}],"variant":"Oven-baked","change":"The vegetables roast in the oven instead of simmering."},{"title":"Tian provençal","intro":"Ratatouille made elegant: slices of vegetables slowly cooked in the oven.","minutes":75,"calories":210,"difficulty":"Facile","imageSearch":"tian provencal vegetables","veg":true,"oven":true,"cold":false,"missing":"","origin":"Provençal speciality","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Soften the sliced onions for 10 min in 1 tbsp of oil and spread them over the bottom of a dish.","timer":{"label":"Pan","min":10}},{"text":"Cut the aubergine, courgettes and tomatoes into thin slices.","timer":null},{"text":"Arrange them upright in the dish, alternating the vegetables.","timer":null},{"text":"Drizzle with oil, add the chopped garlic, thyme, salt and pepper.","timer":null},{"text":"Bake for 1 h, covered with foil for the first 30 min.","timer":{"label":"Oven","min":60}}],"variant":"Tian","change":"The vegetables are sliced and arranged in a spiral before going in the oven."}]$r$::jsonb, 'claude')
