insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gratin de courgette', 'Gratin de courgettes', array['en:courgette gratin', 'en:zucchini gratin']::text[], 'dish', $r$[{"title":"Courgette gratin","intro":"Soft courgettes in a creamy mixture, browned with emmental.","minutes":40,"calories":320,"difficulty":"Facile","imageSearch":"zucchini gratin cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the courgettes into slices.","timer":null},{"text":"Fry them in a pan with the oil and garlic for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Beat the eggs with the cream, half the emmental, salt and pepper.","timer":null},{"text":"Put the courgettes in a dish, pour over the mixture and sprinkle with the rest of the emmental.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"kids":true,"variant":"The classic","change":""},{"title":"Lighter courgette gratin","intro":"The courgette gratin made lighter, and still nicely golden.","minutes":40,"calories":220,"difficulty":"Facile","imageSearch":"light zucchini bake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":150,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":10,"unit":"cl","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the courgettes into slices and fry them for 8 min with no added fat.","timer":{"label":"Pan","min":8}},{"text":"Beat the eggs with the fromage blanc, milk, salt and pepper.","timer":null},{"text":"Put the courgettes in a dish, pour over the mixture and sprinkle with parmesan.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"Lighter","change":"The cream is replaced with milk and fromage blanc."},{"title":"Courgette and goat's cheese gratin","intro":"A fragrant gratin with melted goat's cheese and thyme.","minutes":40,"calories":360,"difficulty":"Facile","imageSearch":"zucchini goat cheese gratin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"courgette","plural":"courgettes","qty":4,"unit":"","have":false},{"name":"goat's cheese log","plural":"goat's cheese logs","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Cut the courgettes into slices and fry them in the oil for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Beat the eggs with the cream, thyme, salt and pepper.","timer":null},{"text":"Put the courgettes in a dish, pour over the mixture and lay the goat's cheese slices on top.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"With goat's cheese","change":"Goat's cheese replaces the emmental, with thyme."}]$r$::jsonb, 'claude')
