insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:soupe a l oignon', 'Soupe à l''oignon', array['en:french onion soup', 'en:onion soup']::text[], 'dish', $r$[{"title":"French onion soup","intro":"Slowly caramelised onions in a broth, under a cheesy toasted croûton.","minutes":70,"calories":420,"difficulty":"Facile","imageSearch":"french onion soup","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"onion","plural":"onions","qty":6,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":1,"unit":"tbsp","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":0.5,"unit":"","have":false},{"name":"grated gruyère","plural":"grated gruyère","qty":100,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the onions finely and soften them in the butter over a low heat for 30 min, until nicely golden.","timer":{"label":"Cooking","min":30}},{"text":"Sprinkle with flour, stir, then pour in the white wine and 1.2 l of water with the stock cube.","timer":null},{"text":"Simmer for 20 min, then add salt and pepper.","timer":{"label":"Simmer","min":20}},{"text":"Pour into bowls, add slices of toasted bread and cover with gruyère.","timer":null},{"text":"Put under the oven grill for 5 min.","timer":{"label":"Grill","min":5}}],"variant":"The classic","change":""},{"title":"Lighter onion soup","intro":"All the sweetness of caramelised onions, as a light soup.","minutes":60,"calories":180,"difficulty":"Facile","imageSearch":"light onion soup bowl","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"onion","plural":"onions","qty":6,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the onions and brown them in the oil over a low heat for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Add 1.2 l of water, the stock cube and the thyme.","timer":null},{"text":"Simmer for 20 min, then add salt and pepper.","timer":{"label":"Simmer","min":20}}],"variant":"Lighter","change":"No cheesy croûton, and less butter."},{"title":"Cider onion soup","intro":"A mild, fruity onion soup, topped with melted camembert.","minutes":70,"calories":440,"difficulty":"Facile","imageSearch":"onion soup cider","veg":true,"oven":true,"cold":false,"missing":"","origin":"Norman speciality","serves":4,"items":[{"name":"onion","plural":"onions","qty":6,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"dry cider","plural":"dry cider","qty":25,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"baguette","plural":"baguettes","qty":0.5,"unit":"","have":false},{"name":"camembert","plural":"camemberts","qty":0.5,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Soften the sliced onions in the butter over a low heat for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Pour in the cider, let it reduce for 5 min, then add 1 l of water and the stock cube.","timer":{"label":"Cooking","min":5}},{"text":"Simmer for 20 min.","timer":{"label":"Simmer","min":20}},{"text":"Pour into bowls, add toasted bread and slices of camembert, and put under the grill for 5 min.","timer":{"label":"Grill","min":5}}],"variant":"With cider","change":"The white wine is replaced with cider, Normandy style."}]$r$::jsonb, 'claude')
