insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:veloute de potiron', 'Velouté de potiron', array['en:pumpkin soup', 'en:squash soup']::text[], 'dish', $r$[{"title":"Creamy pumpkin soup","intro":"A smooth, velvety orange soup, very mellow, with a touch of cream.","minutes":40,"calories":200,"difficulty":"Facile","imageSearch":"pumpkin soup bowl","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pumpkin","plural":"pumpkins","qty":1000,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the pumpkin and the potato and cut them into cubes.","timer":null},{"text":"Fry the onion in the butter for 3 min in a saucepan.","timer":{"label":"Cooking","min":3}},{"text":"Add the vegetables, cover with water, add the stock cube and cook for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Blend, adding the cream, nutmeg, salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Coconut pumpkin soup","intro":"A mild, exotic soup with coconut milk and curry.","minutes":40,"calories":240,"difficulty":"Facile","imageSearch":"pumpkin coconut curry soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pumpkin","plural":"pumpkins","qty":1000,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"curry powder","plural":"curry powder","qty":1,"unit":"tsp","have":false},{"name":"ginger","plural":"ginger","qty":null,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion in the oil with the curry powder and a little grated ginger for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Add the cubed pumpkin, cover with water, add the stock cube and cook for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Blend with the coconut milk and add salt.","timer":null}],"variant":"With coconut milk","change":"Coconut milk and a little curry replace the cream."},{"title":"Pumpkin and chestnut soup","intro":"The autumn soup, with chestnuts for extra sweetness.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"pumpkin chestnut soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pumpkin","plural":"pumpkins","qty":800,"unit":"g","have":false},{"name":"cooked chestnut","plural":"cooked chestnuts","qty":200,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion in the butter for 3 min.","timer":{"label":"Cooking","min":3}},{"text":"Add the cubed pumpkin and the chestnuts, cover with water, add the stock cube and cook for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Blend with the cream, then add salt and pepper.","timer":null}],"variant":"With chestnuts","change":"Cooked chestnuts add a festive taste and a richer texture."}]$r$::jsonb, 'claude')
