insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cassoulet', 'Cassoulet', array['en:homemade cassoulet']::text[], 'dish', $r$[{"title":"Cassoulet","intro":"Tender white beans, Toulouse sausage and duck confit, browned in the oven.","minutes":180,"calories":850,"difficulty":"Moyen","imageSearch":"cassoulet beans sausage duck","veg":false,"oven":true,"cold":false,"missing":"","origin":"South-West speciality","serves":4,"items":[{"name":"dried white bean","plural":"dried white beans","qty":500,"unit":"g","have":false},{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"duck confit leg","plural":"duck confit legs","qty":2,"unit":"","have":false},{"name":"smoked belly pork","plural":"smoked belly pork","qty":150,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":4,"unit":"clove","have":false},{"name":"bouquet garni","plural":"bouquets garnis","qty":1,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"The day before, soak the beans in cold water.","timer":null},{"text":"Boil the beans for 1 h in water with the carrot, onion and bouquet garni.","timer":{"label":"Cooking","min":60}},{"text":"Brown the diced belly pork, the sausages and the duck in a pan.","timer":null},{"text":"Preheat the oven to 160 °C. In a dish, mix the drained beans, the tomatoes, the garlic and the meats, and add a little cooking water.","timer":null},{"text":"Sprinkle with breadcrumbs and bake for 1 h 30, breaking the crust twice.","timer":{"label":"Oven","min":90}}],"variant":"The classic","change":""},{"title":"Quick cassoulet","intro":"The taste of cassoulet without spending the whole day on it.","minutes":45,"calories":780,"difficulty":"Facile","imageSearch":"quick cassoulet beans","veg":false,"oven":true,"cold":false,"missing":"","origin":"South-West speciality","serves":4,"items":[{"name":"white bean","plural":"white beans","qty":800,"unit":"g","have":false},{"name":"toulouse sausage","plural":"toulouse sausages","qty":4,"unit":"","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":100,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Brown the sausages cut into chunks, the lardons and the onion for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Add the drained beans, the tomatoes and the garlic, then add salt and pepper.","timer":null},{"text":"Pour into a dish, sprinkle with breadcrumbs and bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"Quick","change":"With tinned beans, it is ready in 45 minutes."},{"title":"Vegetarian cassoulet","intro":"Beans simmered with tomato and smoked paprika, browned just like the real thing.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"vegetarian bean cassoulet","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"white bean","plural":"white beans","qty":800,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"smoked paprika","plural":"smoked paprika","qty":1,"unit":"tsp","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":3,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Fry the onion, leek and diced carrots in the oil for 10 min.","timer":{"label":"Pan","min":10}},{"text":"Add the beans, tomatoes, garlic, paprika, salt and pepper, and simmer for 10 min.","timer":{"label":"Simmer","min":10}},{"text":"Pour into a dish, cover with breadcrumbs and bake for 30 min.","timer":{"label":"Oven","min":30}}],"variant":"Vegetarian","change":"The meat is replaced with vegetables and smoked paprika."}]$r$::jsonb, 'claude')
