insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:choucroute', 'Choucroute', array['en:sauerkraut with sausage', 'en:choucroute garnie']::text[], 'dish', $r$[{"title":"Choucroute garnie","intro":"Fermented cabbage simmered in white wine, with sausages, bacon and potatoes.","minutes":120,"calories":780,"difficulty":"Facile","imageSearch":"choucroute sauerkraut sausages","veg":false,"oven":false,"cold":false,"missing":"","origin":"Alsatian speciality","serves":4,"items":[{"name":"raw sauerkraut","plural":"raw sauerkraut","qty":1200,"unit":"g","have":false},{"name":"strasbourg sausage","plural":"strasbourg sausages","qty":4,"unit":"","have":false},{"name":"montbéliard sausage","plural":"montbéliard sausages","qty":2,"unit":"","have":false},{"name":"smoked bacon","plural":"smoked bacon","qty":300,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":8,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":25,"unit":"cl","have":false},{"name":"juniper berry","plural":"juniper berries","qty":6,"unit":"","have":false},{"name":"lard","plural":"lard","qty":1,"unit":"tbsp","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Rinse the sauerkraut and drain it well.","timer":null},{"text":"Fry the onion in the lard, add the sauerkraut, the juniper, the wine and 25 cl of water.","timer":null},{"text":"Add the bacon and simmer covered for 1 h.","timer":{"label":"Simmer","min":60}},{"text":"Add the Montbéliard sausages and the peeled potatoes, and cook for 30 min.","timer":{"label":"Cooking","min":30}},{"text":"Add the Strasbourg sausages 10 min before the end.","timer":{"label":"Cooking","min":10}}],"variant":"The classic","change":""},{"title":"Seafood choucroute","intro":"A light choucroute with salmon, cod and prawns.","minutes":60,"calories":480,"difficulty":"Moyen","imageSearch":"fish sauerkraut","veg":false,"oven":false,"cold":false,"missing":"","origin":"Alsatian speciality","serves":4,"items":[{"name":"cooked sauerkraut","plural":"cooked sauerkraut","qty":1000,"unit":"g","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":2,"unit":"","have":false},{"name":"cod fillet","plural":"cod fillets","qty":2,"unit":"","have":false},{"name":"prawn","plural":"prawns","qty":8,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Heat the sauerkraut with the white wine for 20 min, covered.","timer":{"label":"Cooking","min":20}},{"text":"Steam the potatoes for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Lay the fish and prawns on the sauerkraut and cook for 10 min, covered.","timer":{"label":"Cooking","min":10}},{"text":"Heat the cream with the butter and a little cooking juice, and pour over the fish.","timer":null}],"variant":"Seafood","change":"The cured meats are replaced with fish."},{"title":"Quick choucroute","intro":"Choucroute for a weeknight.","minutes":35,"calories":700,"difficulty":"Facile","imageSearch":"quick sauerkraut sausage","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cooked sauerkraut","plural":"cooked sauerkraut","qty":1000,"unit":"g","have":false},{"name":"strasbourg sausage","plural":"strasbourg sausages","qty":4,"unit":"","have":false},{"name":"smoked sausage","plural":"smoked sausages","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":6,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":15,"unit":"cl","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes in salted water for 20 min.","timer":{"label":"Cooking","min":20}},{"text":"Heat the sauerkraut with the white wine and the smoked sausages for 20 min, covered.","timer":{"label":"Cooking","min":20}},{"text":"Add the Strasbourg sausages 8 min before the end and serve with the potatoes.","timer":{"label":"Cooking","min":8}}],"variant":"Quick","change":"With ready-cooked sauerkraut, it is ready in 35 minutes."}]$r$::jsonb, 'claude')
