insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:roti de porc', 'Rôti de porc', array['en:roast pork', 'en:pork roast with mustard']::text[], 'dish', $r$[{"title":"Roast pork","intro":"A tender, golden roast with its juices and soft potatoes.","minutes":80,"calories":520,"difficulty":"Facile","imageSearch":"roast pork loin","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork roast","plural":"pork roasts","qty":1000,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Rub the roast with oil, salt, pepper and thyme, and brown it on all sides in a casserole dish.","timer":null},{"text":"Add the onions in wedges, the garlic, the potatoes in chunks and a glass of water.","timer":null},{"text":"Bake for 1 h, basting with the juices twice.","timer":{"label":"Oven","min":60}},{"text":"Rest for 10 min before slicing.","timer":{"label":"Rest","min":10}}],"kids":true,"variant":"The classic","change":""},{"title":"Mustard roast pork","intro":"A very tender roast with a creamy mustard sauce.","minutes":80,"calories":580,"difficulty":"Facile","imageSearch":"pork roast mustard sauce","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork roast","plural":"pork roasts","qty":1000,"unit":"g","have":false},{"name":"mustard","plural":"mustard","qty":3,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Brush the roast with 2 tbsp of mustard, then add salt and pepper.","timer":null},{"text":"Put it in a dish with the sliced onion, the wine and a drizzle of oil. Bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Pour the juices into a saucepan with the cream and the rest of the mustard, and thicken for 3 min.","timer":{"label":"Sauce","min":3}}],"kids":true,"variant":"With mustard","change":"The roast is coated in mustard and served with a creamy sauce."},{"title":"Honey and spice roast pork","intro":"A glazed roast, sweet and savoury and full of flavour.","minutes":80,"calories":560,"difficulty":"Facile","imageSearch":"honey glazed pork roast","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pork roast","plural":"pork roasts","qty":1000,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"allspice","plural":"allspice","qty":1,"unit":"tsp","have":false},{"name":"potato","plural":"potatoes","qty":800,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Mix the honey, soy sauce, chopped garlic and spices.","timer":null},{"text":"Put the roast in a dish with the potatoes in chunks and brush it with the sauce.","timer":null},{"text":"Bake for 1 h, basting every 20 min.","timer":{"label":"Oven","min":60}}],"variant":"Honey and spice","change":"A glaze of honey, soy and spices caramelises the roast."}]$r$::jsonb, 'claude')
