insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:lapin a la moutarde', 'Lapin à la moutarde', array['en:rabbit with mustard', 'en:rabbit']::text[], 'dish', $r$[{"title":"Rabbit with mustard","intro":"Tender rabbit simmered in a creamy mustard sauce.","minutes":75,"calories":520,"difficulty":"Moyen","imageSearch":"rabbit mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rabbit pieces","plural":"rabbit pieces","qty":1,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":4,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"white wine","plural":"white wine","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":3,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brush the rabbit pieces with the mustard.","timer":null},{"text":"Brown them in the butter in a casserole dish, with the sliced shallots.","timer":null},{"text":"Pour in the white wine, add the thyme, salt and pepper, then cover and simmer for 50 min.","timer":{"label":"Simmer","min":50}},{"text":"Add the cream and let it reduce for 5 min.","timer":{"label":"Cooking","min":5}}],"variant":"The classic","change":""},{"title":"Rabbit with prunes","intro":"Flemish-style rabbit, tender and gently sweet.","minutes":80,"calories":540,"difficulty":"Moyen","imageSearch":"rabbit prunes stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"rabbit pieces","plural":"rabbit pieces","qty":1,"unit":"","have":false},{"name":"prune","plural":"prunes","qty":16,"unit":"","have":false},{"name":"blonde beer","plural":"blonde beer","qty":33,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the rabbit in the butter with the sliced onions.","timer":null},{"text":"Sprinkle with flour, add the beer and mustard, then add salt and pepper.","timer":null},{"text":"Simmer for 40 min, add the prunes and cook for another 20 min.","timer":{"label":"Simmer","min":60}}],"variant":"With prunes","change":"Prunes and a little beer give a sweet and savoury sauce."},{"title":"Chicken with mustard","intro":"All the sauce of rabbit with mustard, made with chicken.","minutes":45,"calories":500,"difficulty":"Facile","imageSearch":"chicken mustard cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":8,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":3,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in the butter for 10 min with the shallots.","timer":{"label":"Cooking","min":10}},{"text":"Pour in the wine, cover and cook for 25 min.","timer":{"label":"Cooking","min":25}},{"text":"Add the cream and mustard and thicken for 5 min.","timer":{"label":"Cooking","min":5}}],"kids":true,"variant":"With chicken","change":"The rabbit is replaced with chicken thighs."}]$r$::jsonb, 'claude')
