insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet a la creme', 'Poulet à la crème', array['en:creamy chicken and mushroom', 'en:creamy chicken', 'en:chicken in cream sauce']::text[], 'dish', $r$[{"title":"Creamy chicken and mushrooms","intro":"Tender pieces of chicken in a creamy mushroom sauce.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"chicken mushroom cream sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and brown it in the butter for 6 min. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Fry the shallots and the sliced mushrooms for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Put the chicken back, add the cream, salt and pepper, and simmer for 5 min.","timer":{"label":"Simmer","min":5}},{"text":"Sprinkle with parsley and serve with rice or pasta.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Lighter creamy chicken","intro":"The same mild sauce, but lighter.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"light creamy chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"light cream","plural":"light cream","qty":20,"unit":"cl","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken pieces in the oil for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the shallots and mushrooms and cook for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Pour in 10 cl of water with the crumbled stock cube and the cream, and thicken for 5 min.","timer":{"label":"Simmer","min":5}}],"kids":true,"variant":"Lighter","change":"The cream is replaced with light cream and a little stock."},{"title":"Creamy mustard chicken","intro":"Creamy chicken, lifted with wholegrain mustard.","minutes":25,"calories":540,"difficulty":"Facile","imageSearch":"chicken creamy mustard sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"wholegrain mustard","plural":"wholegrain mustard","qty":2,"unit":"tbsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken pieces in the butter for 6 min with the sliced onion.","timer":{"label":"Pan","min":6}},{"text":"Add the cream and mustard, then salt and pepper.","timer":null},{"text":"Simmer for 8 min.","timer":{"label":"Simmer","min":8}}],"kids":true,"variant":"With mustard","change":"Wholegrain mustard lifts the sauce."}]$r$::jsonb, 'claude')
