insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:endive au jambon', 'Endives au jambon', array['en:endive gratin', 'en:endive with ham']::text[], 'dish', $r$[{"title":"Endives with ham","intro":"Soft endives rolled in ham, baked under a béchamel.","minutes":60,"calories":480,"difficulty":"Facile","imageSearch":"endives ham gratin bechamel","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality of the North","serves":4,"items":[{"name":"chicory","plural":"chicories","qty":8,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":8,"unit":"slices","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Steam or boil the chicory for 20 min, then press them well to drain.","timer":{"label":"Cooking","min":20}},{"text":"Make a béchamel: melt the butter, add the flour, then the milk, whisking for 5 min. Add nutmeg, salt and pepper.","timer":{"label":"Béchamel","min":5}},{"text":"Preheat the oven to 200 °C. Roll each chicory in a slice of ham and arrange them in a dish.","timer":null},{"text":"Cover with béchamel and sprinkle with emmental.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"kids":true,"variant":"The classic","change":""},{"title":"Lighter endives with ham","intro":"The comforting gratin, in a lighter version.","minutes":55,"calories":330,"difficulty":"Facile","imageSearch":"light endive ham gratin","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality of the North","serves":4,"items":[{"name":"chicory","plural":"chicories","qty":8,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":8,"unit":"slices","have":false},{"name":"semi-skimmed milk","plural":"semi-skimmed milk","qty":50,"unit":"cl","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false},{"name":"grated emmental","plural":"grated emmental","qty":40,"unit":"g","have":false},{"name":"nutmeg","plural":"nutmeg","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Steam the chicory for 20 min and drain well.","timer":{"label":"Cooking","min":20}},{"text":"Mix the cornflour with a little cold milk, add the rest of the milk and thicken for 3 min, stirring.","timer":{"label":"Sauce","min":3}},{"text":"Preheat the oven to 200 °C. Roll the chicory in the ham and arrange them in a dish.","timer":null},{"text":"Cover with the sauce, sprinkle with emmental and bake for 20 min.","timer":{"label":"Oven","min":20}}],"variant":"Lighter","change":"The béchamel is made with semi-skimmed milk, without butter."},{"title":"Endives with ham and maroilles","intro":"The chicory gratin with the character of maroilles.","minutes":60,"calories":540,"difficulty":"Facile","imageSearch":"endive gratin strong cheese","veg":false,"oven":true,"cold":false,"missing":"","origin":"Speciality of the North","serves":4,"items":[{"name":"chicory","plural":"chicories","qty":8,"unit":"","have":false},{"name":"cooked ham","plural":"cooked ham","qty":8,"unit":"slices","have":false},{"name":"maroilles","plural":"maroilles","qty":0.5,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the chicory for 20 min and drain well.","timer":{"label":"Cooking","min":20}},{"text":"Make the béchamel with the butter, flour and milk.","timer":null},{"text":"Preheat the oven to 200 °C. Roll the chicory in the ham, arrange them in a dish and cover with béchamel.","timer":null},{"text":"Add the sliced maroilles and bake for 25 min.","timer":{"label":"Oven","min":25}}],"variant":"With maroilles","change":"Maroilles replaces the emmental, for a gratin true to the North."}]$r$::jsonb, 'claude')
