insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:spaghetti bolognaise', 'Spaghetti bolognese', array['en:spaghetti bolognese', 'en:bolognese', 'en:bolognese sauce', 'en:spaghetti bolo', 'en:spag bol']::text[], 'dish', $r$[{"title":"Spaghetti bolognese","intro":"A slow-simmered meat and tomato sauce on al dente spaghetti.","minutes":50,"calories":620,"difficulty":"Facile","imageSearch":"spaghetti bolognese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"oregano","plural":"oregano","qty":null,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, the diced carrot and the garlic in the oil for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the meat and brown it for 5 min, breaking it up.","timer":{"label":"Cooking","min":5}},{"text":"Pour in the tomatoes, add the oregano, salt and pepper, and simmer for 30 min.","timer":{"label":"Simmer","min":30}},{"text":"Cook the spaghetti in boiling salted water according to the packet.","timer":{"label":"Pasta","min":10}},{"text":"Serve the sauce on the pasta with the parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Lentil spaghetti bolognese","intro":"A hearty veggie bolognese made with red lentils.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"lentil bolognese pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"red lentil","plural":"red lentils","qty":150,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"oregano","plural":"oregano","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, carrot and garlic in the oil for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the rinsed lentils, the tomatoes, 30 cl of water, the oregano, salt and pepper.","timer":null},{"text":"Simmer for 20 min, stirring.","timer":{"label":"Simmer","min":20}},{"text":"Cook the spaghetti and serve with the sauce.","timer":{"label":"Pasta","min":10}}],"kids":true,"variant":"Vegetarian","change":"The meat is replaced with red lentils."},{"title":"Lighter spaghetti bolognese","intro":"The usual bolognese, with more vegetables and less fat.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"light bolognese vegetables","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":350,"unit":"g","have":false},{"name":"5% fat minced beef","plural":"5% fat minced beef","qty":350,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, carrots and courgette, all diced small, in the oil for 8 min.","timer":{"label":"Cooking","min":8}},{"text":"Add the meat and brown it for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the tomatoes and garlic, season, and simmer for 25 min.","timer":{"label":"Simmer","min":25}},{"text":"Cook the spaghetti and serve with the basil.","timer":{"label":"Pasta","min":10}}],"kids":true,"variant":"Lighter","change":"Made with 5% fat beef and more vegetables."}]$r$::jsonb, 'claude')
