insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate carbonara', 'Pâtes carbonara', array['en:carbonara', 'en:spaghetti carbonara']::text[], 'dish', $r$[{"title":"Spaghetti carbonara","intro":"The real carbonara: eggs, pecorino and guanciale, with no cream.","minutes":20,"calories":650,"difficulty":"Facile","imageSearch":"spaghetti carbonara","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"guanciale","plural":"guanciale","qty":150,"unit":"g","have":false},{"name":"egg yolk","plural":"egg yolks","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated pecorino","plural":"grated pecorino","qty":60,"unit":"g","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the spaghetti in boiling salted water.","timer":{"label":"Pasta","min":10}},{"text":"Brown the guanciale slices in a pan for 5 min, with no added fat.","timer":{"label":"Pan","min":5}},{"text":"Beat the yolks, the whole egg, the pecorino and plenty of pepper.","timer":null},{"text":"Drain the pasta, keeping a little cooking water, and put it in the pan off the heat.","timer":null},{"text":"Pour in the eggs, stirring quickly, with a little cooking water to make a creamy sauce.","timer":null}],"variant":"The classic","change":""},{"title":"French-style carbonara","intro":"The creamy French carbonara, with lardons and cream.","minutes":20,"calories":700,"difficulty":"Facile","imageSearch":"creamy carbonara bacon","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"bacon lardon","plural":"bacon lardons","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"egg yolk","plural":"egg yolks","qty":2,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":50,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Fry the lardons and the sliced onion for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the cream and heat for 2 min.","timer":{"label":"Cooking","min":2}},{"text":"Mix the drained pasta with the sauce, then stir in the yolks and parmesan off the heat.","timer":null}],"kids":true,"variant":"French style","change":"With lardons and cream, the way it is often made in France."},{"title":"Courgette carbonara","intro":"A green, creamy carbonara with no meat.","minutes":20,"calories":560,"difficulty":"Facile","imageSearch":"zucchini carbonara pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"egg yolk","plural":"egg yolks","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the spaghetti.","timer":{"label":"Pasta","min":10}},{"text":"Brown the diced courgettes with the garlic in the oil for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Beat the yolks, the egg, the parmesan and the pepper.","timer":null},{"text":"Mix the pasta with the courgettes off the heat, then with the eggs and a little cooking water.","timer":null}],"variant":"Vegetarian","change":"The lardons are replaced with nicely browned courgettes."}]$r$::jsonb, 'claude')
