insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:lasagne', 'Lasagnes', array['en:lasagna', 'en:beef lasagne']::text[], 'dish', $r$[{"title":"Lasagne bolognese","intro":"Layers of pasta, bolognese and béchamel, browned with parmesan.","minutes":90,"calories":680,"difficulty":"Moyen","imageSearch":"beef lasagna","veg":false,"oven":true,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"lasagne sheet","plural":"lasagne sheets","qty":12,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":50,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":70,"unit":"cl","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and garlic in the oil, add the meat, then the tomatoes. Simmer for 25 min.","timer":{"label":"Simmer","min":25}},{"text":"Make a béchamel: melt the butter, add the flour, then the milk, whisking for 5 min. Add salt and pepper.","timer":{"label":"Béchamel","min":5}},{"text":"Preheat the oven to 180 °C. In a dish, alternate bolognese, lasagne sheets and béchamel, in 3 layers.","timer":null},{"text":"Finish with béchamel and the parmesan.","timer":null},{"text":"Bake for 40 min.","timer":{"label":"Oven","min":40}}],"kids":true,"variant":"The classic","change":""},{"title":"Vegetable lasagne","intro":"Soft lasagne with sun-ripened vegetables.","minutes":80,"calories":520,"difficulty":"Moyen","imageSearch":"vegetable lasagna","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lasagne sheet","plural":"lasagne sheets","qty":12,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"aubergine","plural":"aubergines","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":60,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the diced vegetables in the oil for 15 min, add the tomatoes and cook for 10 min.","timer":{"label":"Cooking","min":25}},{"text":"Make a béchamel with the butter, flour and milk.","timer":null},{"text":"Preheat the oven to 180 °C. Alternate vegetables, lasagne sheets and béchamel in a dish.","timer":null},{"text":"Finish with sliced mozzarella and bake for 40 min.","timer":{"label":"Oven","min":40}}],"variant":"Vegetarian","change":"The meat is replaced with courgettes, aubergines and peppers."},{"title":"Salmon and spinach lasagne","intro":"A creamy lasagne with salmon and spinach.","minutes":70,"calories":600,"difficulty":"Moyen","imageSearch":"salmon spinach lasagna","veg":false,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"lasagne sheet","plural":"lasagne sheets","qty":12,"unit":"","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":3,"unit":"","have":false},{"name":"spinach","plural":"spinach","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"plain flour","plural":"plain flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":60,"unit":"cl","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":50,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Wilt the spinach in a pan for 5 min.","timer":{"label":"Pan","min":5}},{"text":"Make a béchamel, then add the cream, salt and pepper.","timer":null},{"text":"Preheat the oven to 180 °C. Cut the raw salmon into small cubes.","timer":null},{"text":"Alternate lasagne sheets, spinach, salmon and béchamel in a dish, then sprinkle with parmesan.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"variant":"Salmon and spinach","change":"The beef is replaced with salmon and spinach."}]$r$::jsonb, 'claude')
