insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate au pesto', 'Pâtes au pesto', array['en:pesto pasta', 'en:pesto', 'en:homemade pesto']::text[], 'dish', $r$[{"title":"Pesto pasta","intro":"A homemade basil, pine nut and parmesan pesto on hot pasta.","minutes":15,"calories":560,"difficulty":"Facile","imageSearch":"pasta basil pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"basil","plural":"basil","qty":50,"unit":"g","have":false},{"name":"pine nut","plural":"pine nuts","qty":30,"unit":"g","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":50,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":10,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta in boiling salted water.","timer":{"label":"Pasta","min":10}},{"text":"Blend the basil, pine nuts, garlic, parmesan and oil, and add salt.","timer":null},{"text":"Drain the pasta, keeping a little water, and mix with the pesto and a little cooking water.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Red pesto pasta","intro":"A red pesto with sun-dried tomatoes, full of sunshine.","minutes":15,"calories":580,"difficulty":"Facile","imageSearch":"red pesto pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"sun-dried tomato","plural":"sun-dried tomatoes","qty":100,"unit":"g","have":false},{"name":"almond","plural":"almonds","qty":30,"unit":"g","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":8,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Blend the drained sun-dried tomatoes, almonds, garlic, parmesan and oil.","timer":null},{"text":"Mix with the pasta and a little cooking water.","timer":null}],"kids":true,"variant":"Red pesto","change":"The basil is replaced with sun-dried tomatoes."},{"title":"Pesto pasta with chicken and cherry tomatoes","intro":"A colourful, filling dish with pesto and chicken.","minutes":25,"calories":620,"difficulty":"Facile","imageSearch":"pesto chicken pasta tomatoes","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":350,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":200,"unit":"g","have":false},{"name":"pesto","plural":"pestos","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Brown the diced chicken in the oil for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Add the halved cherry tomatoes for 2 min.","timer":{"label":"Pan","min":2}},{"text":"Mix with the pasta, the pesto and the parmesan.","timer":null}],"kids":true,"variant":"With chicken","change":"Pan-fried chicken and cherry tomatoes round off the pasta."}]$r$::jsonb, 'claude')
