insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate au saumon', 'Pâtes au saumon', array['en:salmon pasta', 'en:salmon tagliatelle', 'en:smoked salmon pasta']::text[], 'dish', $r$[{"title":"Salmon tagliatelle","intro":"Tagliatelle in a creamy salmon sauce with lemon and dill.","minutes":20,"calories":620,"difficulty":"Facile","imageSearch":"salmon cream tagliatelle","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tagliatelle","plural":"tagliatelle","qty":400,"unit":"g","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the tagliatelle.","timer":{"label":"Pasta","min":10}},{"text":"Fry the shallot in the oil, add the diced salmon and cook for 4 min.","timer":{"label":"Pan","min":4}},{"text":"Add the cream, the lemon zest and a little juice, the dill, salt and pepper.","timer":null},{"text":"Mix with the drained pasta.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Smoked salmon pasta","intro":"Even quicker, with smoked salmon and cream.","minutes":15,"calories":600,"difficulty":"Facile","imageSearch":"smoked salmon pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":200,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"chives","plural":"chives","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Heat the cream with the lemon zest and some pepper.","timer":null},{"text":"Mix the pasta with the cream, then the smoked salmon in strips and the chives.","timer":null}],"variant":"With smoked salmon","change":"Smoked salmon replaces the fresh salmon: nothing to cook."},{"title":"Lighter salmon pasta","intro":"A light, green version with salmon and spinach.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"light salmon spinach pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"wholewheat pasta","plural":"wholewheat pasta","qty":350,"unit":"g","have":false},{"name":"salmon fillet","plural":"salmon fillets","qty":2,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"light soft cheese","plural":"light soft cheese","qty":100,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Cook the diced salmon in a pan for 4 min, then add the spinach for 1 min.","timer":{"label":"Pan","min":5}},{"text":"Mix with the pasta, the soft cheese, a little cooking water and the lemon juice.","timer":null}],"variant":"Lighter","change":"The cream is replaced with light soft cheese and spinach."}]$r$::jsonb, 'claude')
