insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:one pot pasta', 'One pot pasta', array['en:one pot']::text[], 'dish', $r$[{"title":"Tomato and basil one pot pasta","intro":"Everything cooked in one pan: pasta, tomato and basil, in 15 minutes.","minutes":15,"calories":480,"difficulty":"Facile","imageSearch":"one pot pasta tomato basil","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"spaghetti","plural":"spaghetti","qty":400,"unit":"g","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the raw spaghetti, the halved tomatoes, the sliced onion, the garlic, the oil and the basil in a large pan.","timer":null},{"text":"Pour in 1 l of water, then add salt and pepper.","timer":null},{"text":"Bring to the boil and cook for 12 min, stirring often, until the water is absorbed.","timer":{"label":"Cooking","min":12}},{"text":"Serve with the parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Chorizo one pot pasta","intro":"The spicy version of the one pot, with chorizo and peppers.","minutes":15,"calories":600,"difficulty":"Facile","imageSearch":"one pot pasta chorizo","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"chorizo","plural":"chorizos","qty":120,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the pasta, the sliced chorizo, the tomatoes, the sliced pepper and the onion in a pan.","timer":null},{"text":"Pour in 80 cl of water and add a little salt.","timer":null},{"text":"Simmer for 12 min, stirring often.","timer":{"label":"Cooking","min":12}}],"kids":true,"variant":"With chorizo","change":"Chorizo flavours the pasta and the sauce."},{"title":"Creamy mushroom one pot pasta","intro":"A mild one pot with mushrooms.","minutes":15,"calories":560,"difficulty":"Facile","imageSearch":"creamy mushroom one pot pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"tagliatelle","plural":"tagliatelle","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the pasta, the sliced mushrooms, the onion, the garlic and the crumbled stock cube in a pan.","timer":null},{"text":"Pour in 90 cl of water and cook for 12 min, stirring.","timer":{"label":"Cooking","min":12}},{"text":"Add the cream and parmesan, season with pepper and serve.","timer":null}],"kids":true,"variant":"Mushrooms and cream","change":"Mushrooms and a little cream make the pasta creamy."}]$r$::jsonb, 'claude')
