insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pate aux champignon', 'Pâtes aux champignons', array['en:creamy mushroom pasta', 'en:mushroom cream pasta']::text[], 'dish', $r$[{"title":"Creamy mushroom pasta","intro":"Pasta in a creamy sauce with mushrooms and garlic.","minutes":20,"calories":580,"difficulty":"Facile","imageSearch":"creamy mushroom pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Brown the sliced mushrooms in the butter with the garlic for 8 min.","timer":{"label":"Pan","min":8}},{"text":"Add the cream, salt and pepper, and thicken for 2 min.","timer":{"label":"Cooking","min":2}},{"text":"Mix with the pasta, the parsley and the parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Mushroom and ham pasta","intro":"The creamy classic, with extra ham.","minutes":20,"calories":620,"difficulty":"Facile","imageSearch":"pasta ham mushroom cream","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"diced ham","plural":"diced ham","qty":150,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Brown the mushrooms in the butter for 6 min, then add the ham for 2 min.","timer":{"label":"Pan","min":8}},{"text":"Pour in the cream and mix with the pasta.","timer":null}],"kids":true,"variant":"With ham","change":"Diced ham is added to the sauce."},{"title":"Cream-free mushroom pasta","intro":"Pasta with pan-fried mushrooms, garlic and parsley, and lighter.","minutes":20,"calories":460,"difficulty":"Facile","imageSearch":"garlic mushroom pasta","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"pasta","plural":"pasta","qty":400,"unit":"g","have":false},{"name":"mushroom","plural":"mushrooms","qty":400,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the pasta.","timer":{"label":"Pasta","min":10}},{"text":"Brown the mushrooms in the oil over a high heat for 8 min, then add the garlic and parsley.","timer":{"label":"Pan","min":8}},{"text":"Mix with the pasta, a little cooking water and the parmesan.","timer":null}],"variant":"Cream-free","change":"The cream is replaced with olive oil and parmesan."}]$r$::jsonb, 'claude')
