insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:penne all arrabbiata', 'Penne all''arrabbiata', array['en:arrabbiata', 'en:pasta arrabbiata', 'en:penne arrabiata']::text[], 'dish', $r$[{"title":"Penne all'arrabbiata","intro":"A tomato sauce spiced up with chilli and garlic, simple and full of flavour.","minutes":20,"calories":450,"difficulty":"Facile","imageSearch":"penne arrabbiata","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"dried chilli","plural":"dried chillies","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the penne.","timer":{"label":"Pasta","min":10}},{"text":"Fry the sliced garlic and the crumbled chilli in the oil for 1 min.","timer":null},{"text":"Add the tomatoes, season with salt and reduce for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Mix with the penne and the parsley.","timer":null}],"variant":"The classic","change":""},{"title":"Tuna penne arrabbiata","intro":"Arrabbiata with tuna, for a more filling dish.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"tuna arrabbiata pasta","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"tuna in water","plural":"tuna in water","qty":200,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"dried chilli","plural":"dried chillies","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the penne.","timer":{"label":"Pasta","min":10}},{"text":"Fry the garlic and chilli in the oil, add the tomatoes and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the flaked tuna, then the pasta.","timer":null}],"variant":"With tuna","change":"Tuna is added to the spicy tomato sauce."},{"title":"Mild penne arrabbiata","intro":"The garlic tomato sauce, without the heat, for the whole family.","minutes":20,"calories":500,"difficulty":"Facile","imageSearch":"tomato pasta kids","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"penne","plural":"penne","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":5,"unit":"cl","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the penne.","timer":{"label":"Pasta","min":10}},{"text":"Fry the garlic in the oil, add the tomatoes and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Add the cream, then mix with the pasta and the parmesan.","timer":null}],"kids":true,"variant":"For kids","change":"No chilli, with a touch of cream and parmesan."}]$r$::jsonb, 'claude')
on conflict (key) do update set query = excluded.query, aliases = excluded.aliases, kind = excluded.kind, recipes = excluded.recipes, source = 'claude', updated_at = now();
insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:risotto aux champignon', 'Risotto aux champignons', array['en:mushroom risotto', 'en:risotto']::text[], 'dish', $r$[{"title":"Mushroom risotto","intro":"Creamy rice cooked slowly in stock, with mushrooms and parmesan.","minutes":35,"calories":560,"difficulty":"Moyen","imageSearch":"mushroom risotto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"arborio rice","plural":"arborio rice","qty":320,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"white wine","plural":"white wine","qty":10,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Heat 1 l of water with the stock cubes and keep it simmering.","timer":null},{"text":"Brown the sliced mushrooms in half the butter for 6 min. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Fry the shallot in the oil, add the rice and toast it for 2 min, then pour in the wine.","timer":null},{"text":"Add the stock a ladle at a time, stirring, for 18 min.","timer":{"label":"Cooking","min":18}},{"text":"Off the heat, add the mushrooms, the rest of the butter and the parmesan.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken and mushroom risotto","intro":"A creamy, filling risotto with chicken and mushrooms.","minutes":35,"calories":620,"difficulty":"Moyen","imageSearch":"chicken mushroom risotto","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"arborio rice","plural":"arborio rice","qty":320,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":50,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Keep 1 l of stock simmering.","timer":null},{"text":"Brown the diced chicken and the mushrooms for 8 min. Set aside.","timer":{"label":"Pan","min":8}},{"text":"Fry the onion, add the rice for 2 min, then the stock a ladle at a time for 18 min.","timer":{"label":"Cooking","min":18}},{"text":"Add the chicken, mushrooms, butter and parmesan.","timer":null}],"kids":true,"variant":"With chicken","change":"Pan-fried chicken makes the risotto more filling."},{"title":"Oven-baked mushroom risotto","intro":"The creamy risotto, without standing over the pan.","minutes":40,"calories":540,"difficulty":"Facile","imageSearch":"baked mushroom risotto","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"arborio rice","plural":"arborio rice","qty":300,"unit":"g","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":300,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"In an ovenproof casserole dish, fry the onion and mushrooms in the butter, then add the rice.","timer":null},{"text":"Pour in 90 cl of boiling water with the stock cubes, cover and bake for 25 min.","timer":{"label":"Oven","min":25}},{"text":"Add the parmesan, stir well and serve.","timer":null}],"variant":"Oven-baked","change":"The risotto cooks in the oven, with no stirring."}]$r$::jsonb, 'claude')
