insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gnocchi', 'Gnocchis', array['en:pan fried gnocchi']::text[], 'dish', $r$[{"title":"Pan-fried gnocchi with tomato sauce and mozzarella","intro":"Gnocchi browned in a pan, in a tomato sauce with melting mozzarella.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"gnocchi tomato mozzarella","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"gnocchi","plural":"gnocchi","qty":800,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"mozzarella","plural":"mozzarellas","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the gnocchi in the oil in a pan for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the garlic and tomatoes, season, and cook for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Add the mozzarella in pieces and the basil, and cover for 2 min so that it melts.","timer":{"label":"Cooking","min":2}}],"kids":true,"variant":"The classic","change":""},{"title":"Gnocchi with cream and gorgonzola","intro":"Soft gnocchi in an Italian blue cheese sauce.","minutes":15,"calories":620,"difficulty":"Facile","imageSearch":"gnocchi gorgonzola cream","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"gnocchi","plural":"gnocchi","qty":800,"unit":"g","have":false},{"name":"gorgonzola","plural":"gorgonzola","qty":120,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"walnut","plural":"walnuts","qty":30,"unit":"g","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the gnocchi in boiling water for 2 min, until they float.","timer":{"label":"Cooking","min":2}},{"text":"Melt the gorgonzola in the cream over a low heat.","timer":null},{"text":"Mix with the gnocchi, add the crushed walnuts and some pepper.","timer":null}],"variant":"With gorgonzola","change":"A creamy gorgonzola sauce replaces the tomato."},{"title":"Pan-fried gnocchi with vegetables","intro":"A light, colourful dish, ready in 20 minutes.","minutes":20,"calories":440,"difficulty":"Facile","imageSearch":"gnocchi vegetables pan","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"gnocchi","plural":"gnocchi","qty":800,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":200,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the gnocchi in 2 tbsp of oil for 6 min. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Fry the diced courgettes with the garlic for 6 min.","timer":{"label":"Pan","min":6}},{"text":"Add the cherry tomatoes and the gnocchi for 2 min, then the parmesan.","timer":{"label":"Pan","min":2}}],"variant":"With vegetables","change":"Pan-fried courgettes and cherry tomatoes go with the gnocchi."}]$r$::jsonb, 'claude')
