insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:soupe de legume', 'Vegetable soup', array['en:vegetable soup', 'en:homemade soup', 'en:vegetable veloute']::text[], 'dish', $r$[{"title":"Vegetable soup","intro":"A simple homemade soup with whatever vegetables are in season, blended smooth.","minutes":35,"calories":140,"difficulty":"Facile","imageSearch":"vegetable soup bowl","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":2,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":15,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Peel the vegetables and cut them into chunks.","timer":null},{"text":"Fry the onion and leek in the butter for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the rest of the vegetables, cover with water, crumble in the stock cube and cook for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Blend, then season with salt and pepper.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Chunky vegetable soup","intro":"Grandma's soup, with chunks and a touch of cream.","minutes":35,"calories":190,"difficulty":"Facile","imageSearch":"rustic vegetable soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":5,"unit":"cl","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut all the vegetables into chunks.","timer":null},{"text":"Put them in a pan, cover with water, crumble in the stock cube and cook for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Mash roughly with a potato masher, stir in the cream, then season with salt and pepper.","timer":null}],"kids":true,"variant":"Chunky","change":"The vegetables are roughly mashed, with a little cream."},{"title":"Vegetable and vermicelli soup","intro":"A broth full of diced vegetables and vermicelli: a proper supper dish.","minutes":30,"calories":180,"difficulty":"Facile","imageSearch":"vegetable noodle soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"vermicelli","plural":"vermicelli","qty":60,"unit":"g","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the vegetables into small cubes and fry them in the oil for 5 minutes.","timer":{"label":"Cooking","min":5