false},{"name":"fresh ginger","plural":"fresh ginger","qty":1,"unit":"tbsp","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and grated ginger in the oil for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the sliced carrots, cover with water, crumble in the stock cube and cook for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Blend with the coconut milk and add salt.","timer":null}],"variant":"Coconut and ginger","change":"Coconut milk and ginger replace the cream and cumin."},{"title":"Carrot and orange soup","intro":"A soup full of vitamins, with carrot and orange.","minutes":35,"calories":160,"difficulty":"Facile","imageSearch":"carrot orange soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":8,"unit":"","have":false},{"name":"orange","plural":"oranges","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion in the oil for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the carrots, cover with water, crumble in the stock cube and cook for 25 minutes.","timer":{"label":"Cooking","min":25}},{"text":"Blend with the juice of the oranges, then season with salt and pepper.","timer":null}],"variant":"With orange","change":"Orange juice adds a fruity note."}]$r$::jsonb, 'claude')
