insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gaspacho', 'Gazpacho', array['en:gazpacho', 'en:cold tomato soup']::text[], 'dish', $r$[{"title":"Gazpacho","intro":"The cold Andalusian soup: tomatoes, cucumber and pepper, blended with a drizzle of olive oil.","minutes":15,"calories":140,"difficulty":"Facile","imageSearch":"gazpacho cold tomato soup","veg":true,"oven":false,"cold":true,"missing":"","origin":"Spanish dish","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":6,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"sherry vinegar","plural":"sherry vinegar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the vegetables into chunks.","timer":null},{"text":"Blend them with the garlic, oil, vinegar, salt and pepper until very smooth.","timer":null},{"text":"Chill for at least 2 hours before serving.","timer":{"label":"Chill","min":120}}],"variant":"The classic","change":""},{"title":"Watermelon gazpacho","intro":"A sweet and savoury gazpacho, super refreshing.","minutes":15,"calories":110,"difficulty":"Facile","imageSearch":"watermelon gazpacho","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"watermelon","plural":"watermelons","qty":600,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the seedless watermelon, tomatoes and cucumber into chunks.","timer":null},{"text":"Blend with the oil, the juice of the lime, the mint and the salt.","timer":null},{"text":"Chill for 2 hours.","timer":{"label":"Chill","min":120}}],"variant":"With watermelon","change":"Watermelon replaces half of the tomatoes."},{"title":"Green gazpacho","intro":"An all-green gazpacho, fresh and creamy.","minutes":15,"calories":180,"difficulty":"Facile","imageSearch":"green gazpacho cucumber avocado","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"cucumber","plural":"cucumbers","qty":1,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the vegetables into chunks.","timer":null},{"text":"Blend with the yoghurt, the juice of the lemon, the basil, the oil and the salt.","timer":null},{"text":"Chill for 1 hour.","timer":{"label":"Chill","min":60}}],"variant":"Green","change":"Cucumber, avocado and herbs replace the tomato."}]$r$::jsonb, 'claude')
