insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:minestrone', 'Minestrone', array['en:minestrone soup']::text[], 'dish', $r$[{"title":"Minestrone","intro":"The Italian soup with vegetables, beans and small pasta, served with Parmesan.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"minestrone soup","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"celery stick","plural":"celery sticks","qty":1,"unit":"","have":false},{"name":"white bean","plural":"white beans","qty":250,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"macaroni","plural":"macaroni","qty":80,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the diced onion, carrot and celery in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the courgette, tomatoes, 1 l of water and the stock cube. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the drained beans and the pasta, and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Serve with the Parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Minestrone with pesto","intro":"Minestrone, lifted with a spoonful of pesto when you serve it.","minutes":45,"calories":330,"difficulty":"Facile","imageSearch":"minestrone pesto","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"potato","plural":"potatoes","qty":1,"unit":"","have":false},{"name":"macaroni","plural":"macaroni","qty":80,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":1,"unit":"","have":false},{"name":"pesto","plural":"pesto","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and carrots in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the potato, courgette, chopped green beans, 1 l of water and the stock cube. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the pasta and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Serve with a spoonful of pesto in each bowl.","timer":null}],"variant":"With pesto","change":"A spoonful of pesto flavours each bowl."},{"title":"Minestrone with ham","intro":"A heartier minestrone, with ham.","minutes":45,"calories":340,"difficulty":"Facile","imageSearch":"minestrone ham","veg":false,"oven":false,"cold":false,"missing":"","origin":"Italian dish","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"white bean","plural":"white beans","qty":250,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"macaroni","plural":"macaroni","qty":80,"unit":"g","have":false},{"name":"cured ham","plural":"cured ham","qty":80,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, diced ham and carrots in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the courgette, tomatoes, 1 l of water and the stock cube. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the beans and pasta, and cook for 10 minutes.","timer":{"label":"Cooking","min":10}}],"kids":true,"variant":"With ham","change":"Cubes of cured ham flavour the broth."}]$r$::jsonb, 'claude')
