insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade nicoise', 'Niçoise salad', array['en:nicoise salad']::text[], 'dish', $r$[{"title":"Niçoise salad","intro":"The salad from the South: tuna, hard-boiled eggs, tomatoes, olives and anchovies, with an olive oil dressing.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"nicoise salad tuna egg","veg":false,"oven":false,"cold":true,"missing":"","origin":"Speciality from Nice","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"tuna in brine","plural":"tuna in brine","qty":200,"unit":"g","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"anchovy","plural":"anchovies","qty":8,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"red wine vinegar","plural":"red wine vinegar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the eggs for 10 minutes, then cool them.","timer":{"label":"Eggs","min":10}},{"text":"Cut the tomatoes into wedges, the pepper into strips and the onion into thin rings.","timer":null},{"text":"Arrange the vegetables, tuna, quartered eggs, olives and anchovies.","timer":null},{"text":"Drizzle with a dressing of oil, vinegar, salt and pepper.","timer":null}],"variant":"The classic","change":""},{"title":"Niçoise salad with potatoes and green beans","intro":"The brasserie-style niçoise, with potatoes and green beans.","minutes":35,"calories":520,"difficulty":"Facile","imageSearch":"nicoise salad potatoes green beans","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":4,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":200,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"tuna in brine","plural":"tuna in brine","qty":200,"unit":"g","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"red wine vinegar","plural":"red wine vinegar","qty":1,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the potatoes for 20 minutes and the green beans for 8 minutes in salted water.","timer":{"label":"Cooking","min":20}},{"text":"Boil the eggs for 10 minutes and peel them.","timer":{"label":"Eggs","min":10}},{"text":"Make the dressing with the mustard, vinegar, oil, salt and pepper.","timer":null},{"text":"Mix all the chopped ingredients and drizzle with the dressing.","timer":null}],"variant":"More filling","change":"Potatoes and green beans make it a full meal."},{"title":"Vegetarian niçoise salad","intro":"All the colours of a niçoise, with no fish.","minutes":20,"calories":400,"difficulty":"Facile","imageSearch":"vegetarian nicoise salad chickpeas","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"tomato","plural":"tomatoes","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"black olive","plural":"black olives","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"red wine vinegar","plural":"red wine vinegar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Boil the eggs for 10 minutes and cool them.","timer":{"label":"Eggs","min":10}},{"text":"Cut the tomatoes and the pepper.","timer":null},{"text":"Mix with the drained chickpeas, the olives and the quartered eggs, then add the dressing.","timer":null}],"variant":"Vegetarian","change":"The tuna and anchovies are replaced by chickpeas."}]$r$::jsonb, 'claude')
