insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade cesar', 'Caesar salad', array['en:caesar salad', 'en:chicken caesar salad']::text[], 'dish', $r$[{"title":"Caesar salad","intro":"Crunchy romaine, golden chicken, croutons and a Parmesan Caesar dressing.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"caesar salad chicken","veg":false,"oven":false,"cold":true,"missing":"","origin":"American dish","serves":4,"items":[{"name":"romaine lettuce","plural":"romaine lettuces","qty":1,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":3,"unit":"slices","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in 1 tbsp of oil for 10 minutes, then slice it.","timer":{"label":"Pan","min":10}},{"text":"Cut the bread into cubes and brown them for 3 minutes in the rest of the oil with the garlic.","timer":{"label":"Pan","min":3}},{"text":"Mix the mayonnaise, the juice of the lemon, half the Parmesan, salt and pepper.","timer":null},{"text":"Toss the lettuce with the dressing, then add the chicken, croutons and the rest of the Parmesan.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Light Caesar salad","intro":"A lighter Caesar, just as tasty.","minutes":25,"calories":400,"difficulty":"Facile","imageSearch":"light caesar salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"romaine lettuce","plural":"romaine lettuces","qty":1,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"wholemeal bread","plural":"wholemeal bread","qty":2,"unit":"slices","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the chicken for 10 minutes in a non-stick pan and slice it.","timer":{"label":"Pan","min":10}},{"text":"Dry-toast the bread cubes for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Mix the yoghurt, mustard, lemon juice, half the Parmesan, salt and pepper.","timer":null},{"text":"Toss the lettuce with the dressing and add the rest.","timer":null}],"variant":"Lighter","change":"The dressing is made with yoghurt and the croutons are dry-toasted."},{"title":"Prawn Caesar salad","intro":"A Caesar with a twist: pan-fried garlic prawns.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"shrimp caesar salad","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"romaine lettuce","plural":"romaine lettuces","qty":1,"unit":"","have":false},{"name":"prawn","plural":"prawns","qty":300,"unit":"g","have":false},{"name":"sliced white bread","plural":"sliced white bread","qty":3,"unit":"slices","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the prawns with the garlic in 1 tbsp of oil for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Brown the bread cubes in the rest of the oil for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Mix the mayonnaise, lemon juice and half the Parmesan.","timer":null},{"text":"Toss the lettuce with the dressing, prawns, croutons and Parmesan.","timer":null}],"variant":"With prawns","change":"Garlic prawns replace the chicken."}]$r$::jsonb, 'claude')
