insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:salade de lentille', 'Lentil salad', array['en:lentil salad', 'en:green lentil salad']::text[], 'dish', $r$[{"title":"Lentil salad","intro":"Warm green lentils with shallot, parsley and a mustard dressing.","minutes":35,"calories":340,"difficulty":"Facile","imageSearch":"lentil salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"green lentil","plural":"green lentils","qty":250,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"red wine vinegar","plural":"red wine vinegar","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the lentils for 25 minutes in water with the diced carrot.","timer":{"label":"Cooking","min":25}},{"text":"Make the dressing with the mustard, vinegar, oil, salt and pepper.","timer":null},{"text":"Drain the lentils and toss them while warm with the sliced shallots, parsley and dressing.","timer":null}],"variant":"The classic","change":""},{"title":"Lentil salad with smoked salmon","intro":"A smart lentil salad with smoked salmon.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"lentil salad smoked salmon","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"green lentil","plural":"green lentils","qty":250,"unit":"g","have":false},{"name":"smoked salmon","plural":"smoked salmon","qty":150,"unit":"g","have":false},{"name":"shallot","plural":"shallots","qty":1,"unit":"","have":false},{"name":"dill","plural":"dill","qty":null,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":5,"unit":"cl","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the lentils for 25 minutes and drain them.","timer":{"label":"Cooking","min":25}},{"text":"Mix the oil, the juice of the lemon, salt and pepper, and dress the lentils with the shallot.","timer":null},{"text":"Add the salmon in strips and a spoonful of cream with dill.","timer":null}],"variant":"With smoked salmon","change":"Smoked salmon and dill cream finish the salad."},{"title":"Lentil, feta and crunchy veg salad","intro":"A colourful, filling salad, perfect for a packed lunch.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"lentil feta salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"green lentil","plural":"green lentils","qty":250,"unit":"g","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"cherry tomato","plural":"cherry tomatoes","qty":150,"unit":"g","have":false},{"name":"red onion","plural":"red onions","qty":0.5,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the lentils for 25 minutes and leave them to cool.","timer":{"label":"Cooking","min":25}},{"text":"Cut the cucumber, tomatoes and onion.","timer":null},{"text":"Mix everything with the crumbled feta, the mint, the juice of the lemon, the oil, salt and pepper.","timer":null}],"variant":"Feta and veg","change":"Feta, cucumber and cherry tomatoes make the salad fresher."}]$r$::jsonb, 'claude')
