insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:taboule', 'Tabbouleh', array['en:tabbouleh', 'en:couscou salad', 'en:bulgur salad']::text[], 'dish', $r$[{"title":"Couscous tabbouleh","intro":"Fresh couscous with tomato, cucumber, mint and lemon.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"couscous tabbouleh salad","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":250,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Pour 25 cl of boiling salted water over the couscous, cover for 5 minutes and fluff with a fork.","timer":{"label":"Rest","min":5}},{"text":"Cut the tomatoes, cucumber and onion into small cubes.","timer":null},{"text":"Mix with the couscous, the chopped mint and parsley, the juice of the lemons, the oil, salt and pepper.","timer":null},{"text":"Chill for 1 hour.","timer":{"label":"Chill","min":60}}],"kids":true,"variant":"The classic","change":""},{"title":"Lebanese tabbouleh","intro":"The real Lebanese tabbouleh: mostly parsley, with a little bulgur.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"lebanese tabbouleh parsley","veg":true,"oven":false,"cold":true,"missing":"","origin":"Lebanese dish","serves":4,"items":[{"name":"flat-leaf parsley","plural":"flat-leaf parsley","qty":150,"unit":"g","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"bulgur","plural":"bulgur","qty":60,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Soak the bulgur in cold water for 15 minutes and drain it well.","timer":{"label":"Soaking","min":15}},{"text":"Finely chop the parsley and mint, and cut the tomatoes and spring onions into small cubes.","timer":null},{"text":"Mix everything with the juice of the lemons, the oil and the salt.","timer":null}],"variant":"Lebanese","change":"Lots of parsley and a little bulgur, Lebanese style."},{"title":"Quinoa tabbouleh","intro":"A fresh tabbouleh made with quinoa.","minutes":25,"calories":330,"difficulty":"Facile","imageSearch":"quinoa tabbouleh","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"quinoa","plural":"quinoa","qty":200,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the quinoa for 12 minutes in salted water and leave it to cool.","timer":{"label":"Cooking","min":12}},{"text":"Cut the vegetables into small cubes.","timer":null},{"text":"Mix with the quinoa, the mint, the juice of the lemons, the oil, salt and pepper.","timer":null}],"variant":"With quinoa","change":"Quinoa replaces the couscous, so it is gluten-free."}]$r$::jsonb, 'claude')
