insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:chili con carne', 'Chilli con carne', array['en:chilli con carne', 'en:chili', 'en:chilli']::text[], 'dish', $r$[{"title":"Chilli con carne","intro":"Minced beef, kidney beans and tomatoes, spiced with cumin and chilli.","minutes":50,"calories":560,"difficulty":"Facile","imageSearch":"chili con carne","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"kidney bean","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"tsp","have":false},{"name":"chilli powder","plural":"chilli powder","qty":0.5,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onions, diced pepper and garlic in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the meat and spices, and brown for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the tomatoes, season with salt and simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Add the drained kidney beans and cook for 10 minutes. Serve with rice.","timer":{"label":"Cooking","min":10}}],"kids":true,"variant":"The classic","change":""},{"title":"Chilli sin carne","intro":"The all-veg chilli, with kidney beans, lentils and sweetcorn.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"vegetarian chili beans","veg":true,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"kidney bean","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"red lentil","plural":"red lentils","qty":100,"unit":"g","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":150,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"tsp","have":false},{"name":"smoked paprika","plural":"smoked paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onions, pepper and garlic in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the spices, the rinsed lentils, the tomatoes and 20 cl of water. Simmer for 20 minutes.","timer":{"label":"Simmer","min":20}},{"text":"Add the beans and sweetcorn, and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"The meat is replaced by lentils and more beans."},{"title":"Mild chilli con carne","intro":"The chilli for the whole family, mild and tasty.","minutes":45,"calories":580,"difficulty":"Facile","imageSearch":"mild chili kids","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"kidney bean","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":150,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":60,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion in the oil, then the meat with the cumin for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the tomatoes and simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Add the beans and sweetcorn, cook for 5 minutes and serve with the cheddar.","timer":{"label":"Cooking","min":5}}],"kids":true,"variant":"For kids","change":"No chilli, with a little sweetcorn, served with grated cheese."}]$r$::jsonb, 'claude')
