insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:curry de poulet', 'Chicken curry', array['en:chicken curry', 'en:coconut chicken curry']::text[], 'dish', $r$[{"title":"Chicken and coconut milk curry","intro":"Tender chicken in a creamy coconut and curry sauce.","minutes":35,"calories":520,"difficulty":"Facile","imageSearch":"chicken coconut curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":200,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, garlic and ginger in the oil for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the chopped chicken and the curry powder, and brown for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Pour in the tomatoes and coconut milk, season with salt and simmer for 20 minutes.","timer":{"label":"Simmer","min":20}},{"text":"Serve with rice and the coriander.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Light chicken curry","intro":"A fragrant, light curry, full of vegetables.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"light chicken curry yogurt","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tbsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion in the oil, then add the chopped chicken and the curry powder for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the courgette, pepper and tomatoes, and simmer for 20 minutes.","timer":{"label":"Simmer","min":20}},{"text":"Take off the heat, stir in the yoghurt and season with salt.","timer":null}],"variant":"Lighter","change":"The coconut milk is replaced by yoghurt and more vegetables."},{"title":"Chicken, vegetable and potato curry","intro":"A complete curry, with no need for rice.","minutes":40,"calories":500,"difficulty":"Facile","imageSearch":"chicken potato curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"pea","plural":"peas","qty":150,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and the chopped chicken with the curry powder for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the diced potatoes, the coconut milk and 10 cl of water. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the peas and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"kids":true,"variant":"With vegetables","change":"Potatoes and peas make it a full meal."}]$r$::jsonb, 'claude')
