insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet tikka masala', 'Chicken tikka masala', array['en:chicken tikka masala', 'en:tikka masala']::text[], 'dish', $r$[{"title":"Chicken tikka masala","intro":"Chicken marinated in yoghurt and spices, in a creamy tomato sauce.","minutes":45,"calories":540,"difficulty":"Moyen","imageSearch":"chicken tikka masala","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and mix it with the yoghurt, half the spices and some salt. Leave to marinate for 15 minutes.","timer":{"label":"Marinate","min":15}},{"text":"Brown the chicken in the oil for 6 minutes. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Fry the onion, garlic and ginger, add the rest of the spices, then the tomatoes. Cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the cream and the chicken, and simmer for 10 minutes. Serve with basmati rice.","timer":{"label":"Simmer","min":10}}],"variant":"The classic","change":""},{"title":"Light chicken tikka masala","intro":"All the tikka spices, with a lighter sauce.","minutes":45,"calories":400,"difficulty":"Moyen","imageSearch":"light tikka masala","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":2,"unit":"","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Marinate the chopped chicken with one yoghurt and half the spices for 15 minutes.","timer":{"label":"Marinate","min":15}},{"text":"Brown it for 6 minutes, then add the onion, garlic, the rest of the spices and the tomatoes.","timer":{"label":"Pan","min":6}},{"text":"Simmer for 15 minutes, then stir in the second yoghurt off the heat.","timer":{"label":"Simmer","min":15}}],"variant":"Lighter","change":"The cream is replaced by yoghurt."},{"title":"Chickpea tikka masala","intro":"The tikka sauce, with chickpeas and spinach.","minutes":30,"calories":420,"difficulty":"Facile","imageSearch":"chickpea tikka masala","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":500,"unit":"g","have":false},{"name":"baby spinach","plural":"baby spinach","qty":100,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and garlic in the oil with the spices for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the tomatoes and simmer for 10 minutes.","timer":{"label":"Simmer","min":10}},{"text":"Add the chickpeas, cream and spinach, and cook for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"The chicken is replaced by chickpeas and spinach."}]$r$::jsonb, 'claude')
