insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:butter chicken', 'Butter chicken', array['en:murgh makhani', 'en:poulet au beurre']::text[], 'dish', $r$[{"title":"Butter chicken","intro":"The Indian butter chicken: a mild, buttery, creamy tomato sauce.","minutes":45,"calories":620,"difficulty":"Moyen","imageSearch":"butter chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"plain yoghurt","plural":"plain yoghurts","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Marinate the chopped chicken with the yoghurt, 1 tsp of garam masala and some salt for 15 minutes.","timer":{"label":"Marinate","min":15}},{"text":"Brown the chicken in half the butter for 6 minutes. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Soften the onion, garlic and ginger in the rest of the butter, add the spices and the tomatoes. Cook for 10 minutes, then blend.","timer":{"label":"Cooking","min":10}},{"text":"Add the cream and the chicken, and simmer for 10 minutes.","timer":{"label":"Simmer","min":10}}],"kids":true,"variant":"The classic","change":""},{"title":"Quick butter chicken","intro":"Butter chicken for busy evenings.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"quick butter chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"passata","plural":"passata","qty":40,"unit":"cl","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chopped chicken in the butter with the garlic for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Add the garam masala and the passata, and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the cream, season with salt and let it thicken for 3 minutes.","timer":{"label":"Cooking","min":3}}],"kids":true,"variant":"Quick","change":"No marinade and no blended sauce: ready in 25 minutes."},{"title":"Butter paneer","intro":"The butter chicken sauce, with a cheese that holds its shape when cooked.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"paneer butter masala","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"paneer","plural":"paneer","qty":400,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":15,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"garam masala","plural":"garam masala","qty":2,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the paneer into cubes and brown them for 4 minutes in half the butter.","timer":{"label":"Pan","min":4}},{"text":"Soften the onion and garlic in the rest of the butter, add the spices and the tomatoes, and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the cream and the paneer and simmer for 5 minutes.","timer":{"label":"Simmer","min":5}}],"variant":"Vegetarian","change":"The chicken is replaced by paneer, or halloumi."}]$r$::jsonb, 'claude')
