insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:curry de legume', 'Vegetable curry', array['en:vegetable curry', 'en:coconut vegetable curry', 'en:vegetarian curry', 'en:veggie curry']::text[], 'dish', $r$[{"title":"Vegetable and coconut milk curry","intro":"Tender vegetables in a coconut sauce flavoured with curry.","minutes":35,"calories":380,"difficulty":"Facile","imageSearch":"vegetable coconut curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired","serves":4,"items":[{"name":"potato","plural":"potatoes","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"cauliflower","plural":"cauliflowers","qty":0.5,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion in the oil with the curry powder for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the chopped potatoes and carrots, the coconut milk and 15 cl of water. Cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Add the cauliflower florets and the courgette, and cook for another 12 minutes.","timer":{"label":"Cooking","min":12}},{"text":"Add the chickpeas, season with salt and serve with rice.","timer":null}],"variant":"The classic","change":""},{"title":"Sweet potato and spinach curry","intro":"A mild curry with soft sweet potato.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"sweet potato spinach curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian-inspired","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":2,"unit":"","have":false},{"name":"baby spinach","plural":"baby spinach","qty":150,"unit":"g","have":false},{"name":"red lentil","plural":"red lentils","qty":100,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion with the curry powder for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the diced sweet potato, the lentils, the coconut milk and 30 cl of water. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the spinach for 2 minutes and season with salt.","timer":{"label":"Cooking","min":2}}],"variant":"Sweet potato","change":"Sweet potato and spinach replace the other vegetables."},{"title":"Green vegetable curry","intro":"A fragrant Thai curry, with basil and lime.","minutes":30,"calories":360,"difficulty":"Facile","imageSearch":"thai green vegetable curry","veg":true,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"green curry paste","plural":"green curry paste","qty":2,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"mushroom","plural":"mushrooms","qty":150,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the curry paste in the oil for 1 minute, then pour in the coconut milk.","timer":null},{"text":"Add the chopped vegetables and cook for 12 minutes.","timer":{"label":"Cooking","min":12}},{"text":"Add the soy sauce, the juice of the lime and the basil.","timer":null}],"variant":"Thai green","change":"Green curry paste replaces the curry powder."}]$r$::jsonb, 'claude')
