insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:dal de lentille', 'Lentil dal', array['en:lentil dal', 'en:dal', 'en:dhal', 'en:dahl', 'en:red lentil dal']::text[], 'dish', $r$[{"title":"Red lentil dal","intro":"Soft red lentils with coconut milk and mild spices.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"red lentil dal","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"red lentil","plural":"red lentils","qty":250,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"curry powder","plural":"curry powder","qty":1,"unit":"tbsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion, garlic and ginger in the oil with the spices for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the rinsed lentils, the tomatoes, the coconut milk and 50 cl of water.","timer":null},{"text":"Cook for 20 minutes, stirring, until creamy.","timer":{"label":"Cooking","min":20}},{"text":"Season with salt and serve with rice or naan bread.","timer":null}],"variant":"The classic","change":""},{"title":"Spinach dal","intro":"The creamy dal, with spinach for some green.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"spinach lentil dal","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"red lentil","plural":"red lentils","qty":250,"unit":"g","have":false},{"name":"spinach","plural":"spinach","qty":200,"unit":"g","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"curry powder","plural":"curry powder","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and garlic with the curry powder for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the lentils, the coconut milk and 60 cl of water. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the spinach and cook for 3 minutes.","timer":{"label":"Cooking","min":3}}],"variant":"With spinach","change":"Spinach is added at the end."},{"title":"Lentil and sweet potato dal","intro":"An even milder, more nourishing dal.","minutes":35,"calories":430,"difficulty":"Facile","imageSearch":"sweet potato lentil dal","veg":true,"oven":false,"cold":false,"missing":"","origin":"Indian dish","serves":4,"items":[{"name":"red lentil","plural":"red lentils","qty":200,"unit":"g","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":1,"unit":"","have":false},{"name":"coconut milk","plural":"coconut milk","qty":20,"unit":"cl","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"curry powder","plural":"curry powder","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion with the curry powder for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Add the sweet potato in small cubes, the lentils, the coconut milk and 60 cl of water.","timer":null},{"text":"Cook for 25 minutes and season with salt.","timer":{"label":"Cooking","min":25}}],"kids":true,"variant":"Sweet potato","change":"Cubes of sweet potato make the dal more filling."}]$r$::jsonb, 'claude')
