insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:fajita', 'Fajitas', array['en:chicken fajita']::text[], 'dish', $r$[{"title":"Chicken fajitas","intro":"Spiced strips of chicken and peppers, rolled in tortillas.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"chicken fajitas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"fajita seasoning","plural":"fajita seasoning","qty":2,"unit":"tbsp","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":10,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken, peppers and onion into strips.","timer":null},{"text":"Brown the chicken in the oil with the seasoning for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Add the vegetables and cook for 6 minutes. They should stay crunchy.","timer":{"label":"Pan","min":6}},{"text":"Warm the tortillas and fill them with the cream and the fried mix.","timer":null}],"kids":true,"makes":{"n":8,"one":"fajita","many":"fajitas"},"variant":"The classic","change":""},{"title":"Beef fajitas","intro":"Beef fajitas, with guacamole.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"beef fajitas","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"steak","plural":"steaks","qty":500,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"fajita seasoning","plural":"fajita seasoning","qty":2,"unit":"tbsp","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mash the avocado with the juice of the lime and some salt.","timer":null},{"text":"Sear the beef strips with the seasoning over a high heat for 3 minutes.","timer":{"label":"Pan","min":3}},{"text":"Add the peppers and onion and cook for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Fill the warm tortillas with the beef, vegetables and avocado.","timer":null}],"makes":{"n":8,"one":"fajita","many":"fajitas"},"variant":"With beef","change":"Strips of beef replace the chicken."},{"title":"Vegetarian fajitas","intro":"Fajitas full of vegetables and beans.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"vegetarian fajitas beans","veg":true,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"black bean","plural":"black beans","qty":400,"unit":"g","have":false},{"name":"mushroom","plural":"mushrooms","qty":200,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tortilla","plural":"tortillas","qty":8,"unit":"","have":false},{"name":"fajita seasoning","plural":"fajita seasoning","qty":2,"unit":"tbsp","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the mushrooms, peppers and onion strips with the seasoning for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the drained black beans for 2 minutes.","timer":{"label":"Pan","min":2}},{"text":"Fill the tortillas with the yoghurt and the fried mix.","timer":null}],"makes":{"n":8,"one":"fajita","many":"fajitas"},"variant":"Vegetarian","change":"The chicken is replaced by black beans and mushrooms."}]$r$::jsonb, 'claude')
