insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:taco', 'Tacos', array['en:mexican taco']::text[], 'dish', $r$[{"title":"Beef tacos","intro":"Small tortillas filled with spiced beef, onion, coriander and lime.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"beef tacos","veg":false,"oven":false,"cold":false,"missing":"","origin":"Mexican dish","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"corn tortilla","plural":"corn tortillas","qty":12,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry half the onion in the oil, add the meat and spices and cook for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Cut the tomatoes and the rest of the onion into small cubes.","timer":null},{"text":"Warm the tortillas in a dry pan.","timer":null},{"text":"Fill with the meat, tomato, onion and coriander, with a squeeze of lime.","timer":null}],"kids":true,"makes":{"n":12,"one":"taco","many":"tacos"},"variant":"The classic","change":""},{"title":"Chicken tacos","intro":"Light tacos with chicken and lime.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"chicken tacos","veg":false,"oven":false,"cold":false,"missing":"","origin":"Mexican dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"corn tortilla","plural":"corn tortillas","qty":12,"unit":"","have":false},{"name":"red cabbage","plural":"red cabbages","qty":0.25,"unit":"","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into strips and mix it with the juice of one lime, the paprika and some salt.","timer":null},{"text":"Brown it for 6 minutes in the oil.","timer":{"label":"Pan","min":6}},{"text":"Slice the cabbage finely.","timer":null},{"text":"Fill the warm tortillas with the chicken, cabbage, yoghurt and coriander.","timer":null}],"kids":true,"makes":{"n":12,"one":"taco","many":"tacos"},"variant":"With chicken","change":"Chicken marinated in lime replaces the beef."},{"title":"Fish tacos","intro":"Baja California tacos, with crispy fish.","minutes":30,"calories":480,"difficulty":"Facile","imageSearch":"fish tacos","veg":false,"oven":false,"cold":false,"missing":"","origin":"Mexican dish","serves":4,"items":[{"name":"cod fillet","plural":"cod fillets","qty":400,"unit":"g","have":false},{"name":"corn tortilla","plural":"corn tortillas","qty":12,"unit":"","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"white cabbage","plural":"white cabbages","qty":0.25,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":3,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the fish into sticks, add salt and coat them in the flour.","timer":null},{"text":"Brown them in the oil for 5 minutes.","timer":{"label":"Pan","min":5}},{"text":"Mix the mayonnaise with the juice of one lime.","timer":null},{"text":"Fill the tortillas with shredded cabbage, fish, sauce and coriander.","timer":null}],"makes":{"n":12,"one":"taco","many":"tacos"},"variant":"With fish","change":"Breaded white fish replaces the meat."}]$r$::jsonb, 'claude')
