insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:burrito', 'Burritos', array[]::text[], 'dish', $r$[{"title":"Beef burritos","intro":"Big tortillas filled with spiced beef, rice, beans and cheese.","minutes":35,"calories":680,"difficulty":"Facile","imageSearch":"beef burrito","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":400,"unit":"g","have":false},{"name":"rice","plural":"rice","qty":150,"unit":"g","have":false},{"name":"kidney bean","plural":"kidney beans","qty":250,"unit":"g","have":false},{"name":"tortilla","plural":"tortillas","qty":4,"unit":"","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":80,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tex-mex seasoning","plural":"tex-mex seasoning","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the onion, meat and spices for 8 minutes, then add the beans for 2 minutes.","timer":{"label":"Pan","min":10}},{"text":"Fill each tortilla with rice, meat, diced tomato and cheddar.","timer":null},{"text":"Fold in the sides, then roll up tightly and brown for 2 minutes on each side in a pan.","timer":{"label":"Pan","min":4}}],"kids":true,"makes":{"n":4,"one":"burrito","many":"burritos"},"variant":"The classic","change":""},{"title":"Chicken burritos","intro":"Loaded chicken and avocado burritos.","minutes":35,"calories":640,"difficulty":"Facile","imageSearch":"chicken burrito avocado","veg":false,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"rice","plural":"rice","qty":150,"unit":"g","have":false},{"name":"black bean","plural":"black beans","qty":250,"unit":"g","have":false},{"name":"tortilla","plural":"tortillas","qty":4,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":100,"unit":"g","have":false},{"name":"tex-mex seasoning","plural":"tex-mex seasoning","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the chicken strips with the seasoning for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Fill the tortillas with rice, chicken, beans, sweetcorn and avocado, then roll them up.","timer":null}],"makes":{"n":4,"one":"burrito","many":"burritos"},"variant":"With chicken","change":"Chicken replaces the beef, with avocado."},{"title":"Vegetarian burritos","intro":"Generous burritos, all veg.","minutes":30,"calories":560,"difficulty":"Facile","imageSearch":"vegetarian bean burrito","veg":true,"oven":false,"cold":false,"missing":"","origin":"Tex-Mex dish","serves":4,"items":[{"name":"black bean","plural":"black beans","qty":400,"unit":"g","have":false},{"name":"rice","plural":"rice","qty":150,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":150,"unit":"g","have":false},{"name":"tortilla","plural":"tortillas","qty":4,"unit":"","have":false},{"name":"grated cheddar","plural":"grated cheddar","qty":60,"unit":"g","have":false},{"name":"tex-mex seasoning","plural":"tex-mex seasoning","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Fry the diced pepper with the seasoning for 5 minutes, then add the beans and sweetcorn for 3 minutes.","timer":{"label":"Pan","min":8}},{"text":"Fill the tortillas with rice, vegetables and cheddar, roll up and brown for 2 minutes on each side.","timer":{"label":"Pan","min":4}}],"makes":{"n":4,"one":"burrito","many":"burritos"},"variant":"Vegetarian","change":"Beans, rice, peppers and sweetcorn, with no meat."}]$r$::jsonb, 'claude')
