insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:burger maison', 'Homemade burger', array['en:homemade burger', 'en:burger', 'en:hamburger', 'en:cheeseburger']::text[], 'dish', $r$[{"title":"Homemade burger","intro":"A juicy patty, melted cheddar, salad and a homemade sauce in a brioche bun.","minutes":25,"calories":720,"difficulty":"Facile","imageSearch":"homemade cheeseburger","veg":false,"oven":false,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"burger bun","plural":"burger buns","qty":4,"unit":"","have":false},{"name":"beef burger patty","plural":"beef burger patties","qty":4,"unit":"","have":false},{"name":"cheddar","plural":"cheddar","qty":4,"unit":"slices","have":false},{"name":"tomato","plural":"tomatoes","qty":1,"unit":"","have":false},{"name":"red onion","plural":"red onions","qty":1,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"gherkin","plural":"gherkins","qty":4,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":2,"unit":"tbsp","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the ketchup and mayonnaise to make the sauce.","timer":null},{"text":"Toast the halved buns for 1 minute in a pan.","timer":{"label":"Pan","min":1}},{"text":"Cook the patties for 3 minutes on each side, season with salt and pepper, and put the cheddar on top at the end.","timer":{"label":"Pan","min":6}},{"text":"Build the burgers: sauce, lettuce, patty, tomato, onion and gherkins.","timer":null}],"kids":true,"makes":{"n":4,"one":"burger","many":"burgers"},"variant":"The classic","change":""},{"title":"Crispy chicken burger","intro":"The crispy chicken burger, with a honey and mustard sauce.","minutes":30,"calories":680,"difficulty":"Facile","imageSearch":"crispy chicken burger","veg":false,"oven":false,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"burger bun","plural":"burger buns","qty":4,"unit":"","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":3,"unit":"tbsp","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"tomato","plural":"tomatoes","qty":1,"unit":"","have":false},{"name":"mayonnaise","plural":"mayonnaise","qty":2,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice each chicken breast in two through the middle. Coat them in the flour, then the beaten egg, then the breadcrumbs.","timer":null},{"text":"Brown them in the oil for 4 minutes on each side.","timer":{"label":"Pan","min":8}},{"text":"Mix the mayonnaise, honey and mustard.","timer":null},{"text":"Build the burgers with the sauce, lettuce, chicken and tomato.","timer":null}],"kids":true,"makes":{"n":4,"one":"burger","many":"burgers"},"variant":"With chicken","change":"A breaded chicken fillet replaces the patty."},{"title":"Veggie burger","intro":"A tasty veggie burger with a bean patty.","minutes":30,"calories":600,"difficulty":"Facile","imageSearch":"veggie bean burger","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"burger bun","plural":"burger buns","qty":4,"unit":"","have":false},{"name":"kidney bean","plural":"kidney beans","qty":400,"unit":"g","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":50,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"cheddar","plural":"cheddar","qty":4,"unit":"slices","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"tomato","plural":"tomatoes","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mash the drained beans with the chopped onion, egg, breadcrumbs, cumin and salt. Shape into 4 patties.","timer":null},{"text":"Brown them in the oil for 4 minutes on each side, adding the cheddar at the end.","timer":{"label":"Pan","min":8}},{"text":"Build the burgers with the ketchup, lettuce and tomato.","timer":null}],"makes":{"n":4,"one":"burger","many":"burgers"},"variant":"Vegetarian","change":"A kidney bean patty replaces the beef."}]$r$::jsonb, 'claude')
