insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:riz cantonai', 'Cantonese fried rice', array['en:cantonese fried rice', 'en:egg fried rice', 'en:fried rice']::text[], 'dish', $r$[{"title":"Cantonese fried rice","intro":"The takeaway favourite: fried rice with ham, eggs, peas and soy sauce.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"cantonese fried rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"cooked rice","plural":"cooked rice","qty":600,"unit":"g","have":false},{"name":"diced ham","plural":"diced ham","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"pea","plural":"peas","qty":150,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Beat the eggs and cook them as a thin omelette in 1 tbsp of oil, then cut it into strips.","timer":{"label":"Pan","min":2}},{"text":"Stir-fry the cold rice in the rest of the oil for 5 minutes over a high heat.","timer":{"label":"Wok","min":5}},{"text":"Add the ham, peas and spring onions for 3 minutes.","timer":{"label":"Wok","min":3}},{"text":"Add the soy sauce and the omelette, and mix.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Prawn Cantonese fried rice","intro":"Fried rice with juicy prawns.","minutes":20,"calories":460,"difficulty":"Facile","imageSearch":"shrimp fried rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"cooked rice","plural":"cooked rice","qty":600,"unit":"g","have":false},{"name":"prawn","plural":"prawns","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"pea","plural":"peas","qty":150,"unit":"g","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Scramble the eggs in 1 tbsp of oil. Set aside.","timer":{"label":"Pan","min":2}},{"text":"Stir-fry the prawns for 2 minutes, then the rice for 5 minutes over a high heat.","timer":{"label":"Wok","min":7}},{"text":"Add the peas, spring onions, eggs and soy sauce.","timer":null}],"variant":"With prawns","change":"Prawns replace the ham."},{"title":"Vegetable fried rice","intro":"A fried rice full of vegetables, ready in 15 minutes.","minutes":15,"calories":400,"difficulty":"Facile","imageSearch":"vegetable fried rice","veg":true,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"cooked rice","plural":"cooked rice","qty":600,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"pea","plural":"peas","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Stir-fry the diced carrots and pepper in the oil for 4 minutes.","timer":{"label":"Wok","min":4}},{"text":"Add the rice and stir-fry for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Push the rice to the side, scramble the eggs, then mix in the peas and soy sauce.","timer":null}],"variant":"Vegetarian","change":"The ham is replaced by crunchy vegetables."}]$r$::jsonb, 'claude')
