insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:nouille sautee', 'Stir-fried noodles', array['en:stir fried noodle', 'en:chow mein', 'en:noodle stir fry', 'en:wok noodle', 'en:chinese noodle']::text[], 'dish', $r$[{"title":"Chicken stir-fried noodles","intro":"Wok-fried noodles with chicken, crunchy vegetables and a soy and honey sauce.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"chicken stir fry noodles","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"chinese noodle","plural":"chinese noodles","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the noodles following the packet and rinse them in cold water.","timer":{"label":"Cooking","min":4}},{"text":"Stir-fry the chicken strips with the garlic in the oil for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Add the julienned vegetables and cook for 4 minutes.","timer":{"label":"Wok","min":4}},{"text":"Add the noodles, soy sauce and honey, and stir-fry for 2 minutes.","timer":{"label":"Wok","min":2}}],"kids":true,"variant":"The classic","change":""},{"title":"Prawn stir-fried noodles","intro":"A noodle stir-fry with prawns and ginger.","minutes":20,"calories":480,"difficulty":"Facile","imageSearch":"shrimp noodles","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"chinese noodle","plural":"chinese noodles","qty":300,"unit":"g","have":false},{"name":"prawn","plural":"prawns","qty":300,"unit":"g","have":false},{"name":"pak choi","plural":"pak choi","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the noodles and rinse them.","timer":{"label":"Cooking","min":4}},{"text":"Stir-fry the prawns with the ginger for 3 minutes.","timer":{"label":"Wok","min":3}},{"text":"Add the sliced vegetables for 3 minutes, then the noodles and soy sauce for 2 minutes.","timer":{"label":"Wok","min":5}}],"variant":"With prawns","change":"Prawns replace the chicken."},{"title":"Vegetable stir-fried noodles","intro":"An all-veg stir-fry with crunchy vegetables.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"vegetable stir fry noodles","veg":true,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"chinese noodle","plural":"chinese noodles","qty":300,"unit":"g","have":false},{"name":"firm tofu","plural":"firm tofu","qty":200,"unit":"g","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"mushroom","plural":"mushrooms","qty":150,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the noodles and rinse them.","timer":{"label":"Cooking","min":4}},{"text":"Brown the cubed tofu in the oil for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Add the sliced vegetables and the small broccoli florets for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Add the noodles and soy sauce for 2 minutes.","timer":{"label":"Wok","min":2}}],"variant":"Vegetarian","change":"Just vegetables, with tofu if you like."}]$r$::jsonb, 'claude')
