insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pad thai', 'Pad thai', array['en:phad thai']::text[], 'dish', $r$[{"title":"Chicken pad thai","intro":"Thai-style fried rice noodles: chicken, egg, peanuts and lime.","minutes":30,"calories":560,"difficulty":"Moyen","imageSearch":"chicken pad thai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"rice noodle","plural":"rice noodles","qty":250,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"beansprout","plural":"beansprouts","qty":150,"unit":"g","have":false},{"name":"peanut","plural":"peanuts","qty":40,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":1,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Soak the noodles in hot water for 10 minutes, then drain them.","timer":{"label":"Soaking","min":10}},{"text":"Stir-fry the chicken strips in the oil for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Push them to the side and scramble the eggs.","timer":null},{"text":"Add the noodles, soy sauce, sugar and the juice of one lime, and stir-fry for 3 minutes.","timer":{"label":"Wok","min":3}},{"text":"Add the beansprouts and spring onions, and serve with the crushed peanuts and lime.","timer":null}],"variant":"The classic","change":""},{"title":"Prawn pad thai","intro":"The classic pad thai from the streets of Bangkok.","minutes":30,"calories":520,"difficulty":"Moyen","imageSearch":"shrimp pad thai","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"rice noodle","plural":"rice noodles","qty":250,"unit":"g","have":false},{"name":"prawn","plural":"prawns","qty":300,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"beansprout","plural":"beansprouts","qty":150,"unit":"g","have":false},{"name":"peanut","plural":"peanuts","qty":40,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Soak the noodles for 10 minutes and drain them.","timer":{"label":"Soaking","min":10}},{"text":"Stir-fry the prawns for 3 minutes, then scramble the eggs next to them.","timer":{"label":"Wok","min":3}},{"text":"Add the noodles, soy sauce, sugar and lime juice for 3 minutes.","timer":{"label":"Wok","min":3}},{"text":"Add the beansprouts and peanuts.","timer":null}],"variant":"With prawns","change":"Prawns replace the chicken, as in Bangkok."},{"title":"Tofu pad thai","intro":"The all-veg pad thai, with crispy tofu.","minutes":30,"calories":500,"difficulty":"Moyen","imageSearch":"tofu pad thai","veg":true,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"rice noodle","plural":"rice noodles","qty":250,"unit":"g","have":false},{"name":"firm tofu","plural":"firm tofu","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"beansprout","plural":"beansprouts","qty":150,"unit":"g","have":false},{"name":"peanut","plural":"peanuts","qty":40,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Soak the noodles for 10 minutes.","timer":{"label":"Soaking","min":10}},{"text":"Brown the cubed tofu in the oil for 6 minutes.","timer":{"label":"Wok","min":6}},{"text":"Scramble the eggs next to it, then add the noodles, soy sauce, sugar and lime for 3 minutes.","timer":{"label":"Wok","min":3}},{"text":"Add the beansprouts and peanuts.","timer":null}],"variant":"Vegetarian","change":"Browned tofu replaces the meat."}]$r$::jsonb, 'claude')
