insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet teriyaki', 'Teriyaki chicken', array['en:teriyaki chicken', 'en:teriyaki', 'en:chicken teriyaki']::text[], 'dish', $r$[{"title":"Teriyaki chicken","intro":"Glazed chicken in a sweet and salty soy sauce, served with rice.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"chicken teriyaki rice","veg":false,"oven":false,"cold":false,"missing":"","origin":"Japanese dish","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":6,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":5,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":1,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the soy sauce, honey, vinegar, ginger and garlic.","timer":null},{"text":"Brown the chopped chicken in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Pour in the sauce and let it caramelise for 5 minutes, coating the chicken well.","timer":{"label":"Pan","min":5}},{"text":"Sprinkle with sesame seeds and serve with rice.","timer":null}],"kids":true,"variant":"The classic","change":""},{"title":"Teriyaki salmon","intro":"Glazed, tender salmon in teriyaki sauce.","minutes":20,"calories":520,"difficulty":"Facile","imageSearch":"salmon teriyaki","veg":false,"oven":false,"cold":false,"missing":"","origin":"Japanese dish","serves":4,"items":[{"name":"salmon fillet","plural":"salmon fillets","qty":4,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the soy sauce, honey and ginger.","timer":null},{"text":"Cook the salmon skin-side down for 4 minutes, then turn it over for 2 minutes.","timer":{"label":"Pan","min":6}},{"text":"Pour in the sauce and let it reduce for 2 minutes, spooning it over the salmon.","timer":{"label":"Pan","min":2}},{"text":"Sprinkle with sesame seeds.","timer":null}],"variant":"With salmon","change":"Salmon fillets replace the chicken."},{"title":"Teriyaki tofu","intro":"The all-veg teriyaki, with glazed tofu.","minutes":25,"calories":420,"difficulty":"Facile","imageSearch":"tofu teriyaki","veg":true,"oven":false,"cold":false,"missing":"","origin":"Japanese dish","serves":4,"items":[{"name":"firm tofu","plural":"firm tofu","qty":400,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Cut the tofu into cubes and roll them in the cornflour.","timer":null},{"text":"Brown them in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Steam the broccoli for 6 minutes.","timer":{"label":"Steam","min":6}},{"text":"Pour the soy sauce and honey over the tofu, let it caramelise for 2 minutes, and serve with the broccoli.","timer":{"label":"Pan","min":2}}],"variant":"Vegetarian","change":"Crispy tofu replaces the chicken."}]$r$::jsonb, 'claude')
