insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:porc au caramel', 'Caramel pork', array['en:caramel pork', 'en:vietnamese caramel pork']::text[], 'dish', $r$[{"title":"Caramel pork","intro":"Tender pieces of pork, glazed in a fish sauce caramel.","minutes":60,"calories":560,"difficulty":"Moyen","imageSearch":"vietnamese caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese dish","serves":4,"items":[{"name":"pork shoulder","plural":"pork shoulder","qty":800,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"fish sauce","plural":"fish sauce","qty":3,"unit":"tbsp","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the pork into cubes.","timer":null},{"text":"Make a caramel with the sugar and 2 tbsp of water, until it is amber.","timer":{"label":"Caramel","min":5}},{"text":"Add the pork, the sliced onions and the garlic, and stir well.","timer":null},{"text":"Pour in the fish sauce, soy sauce and 20 cl of water, and simmer for 45 minutes until the sauce is syrupy.","timer":{"label":"Simmer","min":45}}],"variant":"The classic","change":""},{"title":"Caramel chicken","intro":"The same glazed caramel, with chicken, and quicker.","minutes":35,"calories":500,"difficulty":"Facile","imageSearch":"caramel chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese dish","serves":4,"items":[{"name":"chicken thigh","plural":"chicken thighs","qty":8,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"fish sauce","plural":"fish sauce","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Chop the chicken into pieces.","timer":null},{"text":"Make an amber caramel with the sugar and a little water.","timer":{"label":"Caramel","min":5}},{"text":"Add the chicken, onion, garlic and ginger, then the fish sauce, soy sauce and 10 cl of water.","timer":null},{"text":"Simmer for 25 minutes.","timer":{"label":"Simmer","min":25}}],"kids":true,"variant":"With chicken","change":"The pork is replaced by chicken thighs."},{"title":"Quick caramel pork","intro":"Caramel pork for a weeknight.","minutes":25,"calories":520,"difficulty":"Facile","imageSearch":"quick caramel pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese dish","serves":4,"items":[{"name":"pork tenderloin","plural":"pork tenderloins","qty":1,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":3,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"fish sauce","plural":"fish sauce","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cut the tenderloin into thin slices.","timer":null},{"text":"Sear them in the oil for 4 minutes.","timer":{"label":"Pan","min":4}},{"text":"Add the sugar, garlic, soy sauce and fish sauce, and let it caramelise for 5 minutes.","timer":{"label":"Pan","min":5}}],"variant":"Quick","change":"With thinly sliced tenderloin, it is ready in 25 minutes."}]$r$::jsonb, 'claude')
