insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:bo bun', 'Bo bun', array['en:bobun', 'en:beef bo bun', 'en:vietnamese vermicelli bowl']::text[], 'dish', $r$[{"title":"Beef bo bun","intro":"Rice vermicelli, lemongrass beef, fresh vegetables and herbs, with a fish sauce dressing.","minutes":30,"calories":520,"difficulty":"Moyen","imageSearch":"bo bun beef vermicelli bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese dish","serves":4,"items":[{"name":"rice vermicelli","plural":"rice vermicelli","qty":200,"unit":"g","have":false},{"name":"beef steak","plural":"beef steaks","qty":400,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"lettuce","plural":"lettuces","qty":0.5,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"peanut","plural":"peanuts","qty":40,"unit":"g","have":false},{"name":"fish sauce","plural":"fish sauce","qty":4,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false},{"name":"lemongrass","plural":"lemongrass","qty":1,"unit":"","have":false}],"steps":[{"text":"Make the sauce: fish sauce, the juice of the limes, sugar and 8 tbsp of water.","timer":null},{"text":"Cook the vermicelli for 3 minutes and rinse them in cold water.","timer":{"label":"Cooking","min":3}},{"text":"Stir-fry the beef strips with the chopped lemongrass for 3 minutes over a high heat.","timer":{"label":"Wok","min":3}},{"text":"In bowls, layer the lettuce, vermicelli, julienned vegetables, beef, herbs and peanuts, then add the sauce.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken bo bun","intro":"The chicken bo bun, fresh and fragrant.","minutes":30,"calories":480,"difficulty":"Moyen","imageSearch":"chicken vermicelli bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"Vietnamese dish","serves":4,"items":[{"name":"rice vermicelli","plural":"rice vermicelli","qty":200,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"lettuce","plural":"lettuces","qty":0.5,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"peanut","plural":"peanuts","qty":40,"unit":"g","have":false},{"name":"fish sauce","plural":"fish sauce","qty":4,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Make the sauce: fish sauce, the juice of the limes, sugar and water.","timer":null},{"text":"Cook the vermicelli and rinse them.","timer":{"label":"Cooking","min":3}},{"text":"Stir-fry the chicken strips for 6 minutes.","timer":{"label":"Wok","min":6}},{"text":"Build the bowls and drizzle with the sauce.","timer":null}],"variant":"With chicken","change":"Marinated chicken replaces the beef."},{"title":"Vegetarian bo bun","intro":"The all-veg bo bun, with browned tofu.","minutes":30,"calories":460,"difficulty":"Moyen","imageSearch":"vegetarian vermicelli bowl tofu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Vietnamese dish","serves":4,"items":[{"name":"rice vermicelli","plural":"rice vermicelli","qty":200,"unit":"g","have":false},{"name":"firm tofu","plural":"firm tofu","qty":250,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"lettuce","plural":"lettuces","qty":0.5,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"peanut","plural":"peanuts","qty":40,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":2,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Make the sauce with the soy sauce, the juice of the limes, the sugar and a little water.","timer":null},{"text":"Cook the vermicelli and rinse them.","timer":{"label":"Cooking","min":3}},{"text":"Brown the cubed tofu for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Build the bowls with the vegetables, herbs and peanuts.","timer":null}],"variant":"Vegetarian","change":"Tofu replaces the meat."}]$r$::jsonb, 'claude')
