insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poke bowl', 'Poke bowl', array['en:poke', 'en:salmon poke bowl', 'en:salmon bowl']::text[], 'dish', $r$[{"title":"Salmon poke bowl","intro":"Vinegared rice, raw salmon marinated in soy, avocado, cucumber and sesame.","minutes":25,"calories":580,"difficulty":"Facile","imageSearch":"salmon poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"Hawaiian dish","serves":4,"items":[{"name":"sushi rice","plural":"sushi rice","qty":250,"unit":"g","have":false},{"name":"extra-fresh salmon fillet","plural":"extra-fresh salmon fillets","qty":2,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"edamame bean","plural":"edamame beans","qty":100,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":2,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":1,"unit":"","have":false}],"steps":[{"text":"Cook the rice, mix it with the rice vinegar and leave it to cool a little.","timer":{"label":"Cooking","min":15}},{"text":"Cut the salmon into cubes and marinate it in the soy sauce for 10 minutes.","timer":{"label":"Marinate","min":10}},{"text":"Slice the avocado and cucumber.","timer":null},{"text":"In bowls, arrange the rice, salmon, vegetables, edamame, sesame seeds and spring onion.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken poke bowl","intro":"A cooked poke bowl, with glazed chicken.","minutes":25,"calories":560,"difficulty":"Facile","imageSearch":"chicken poke bowl","veg":false,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"sweetcorn","plural":"sweetcorn","qty":100,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Brown the diced chicken for 6 minutes, then glaze it with the soy sauce and honey for 2 minutes.","timer":{"label":"Pan","min":8}},{"text":"Grate the carrot and slice the avocado.","timer":null},{"text":"Build the bowls and sprinkle with sesame seeds.","timer":null}],"kids":true,"variant":"With chicken","change":"Teriyaki-style chicken replaces the raw fish."},{"title":"Vegetarian poke bowl","intro":"A colourful, filling bowl, with tofu.","minutes":25,"calories":500,"difficulty":"Facile","imageSearch":"tofu poke bowl","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"rice","plural":"rice","qty":250,"unit":"g","have":false},{"name":"firm tofu","plural":"firm tofu","qty":250,"unit":"g","have":false},{"name":"avocado","plural":"avocados","qty":1,"unit":"","have":false},{"name":"edamame bean","plural":"edamame beans","qty":100,"unit":"g","have":false},{"name":"red cabbage","plural":"red cabbages","qty":0.25,"unit":"","have":false},{"name":"mango","plural":"mangoes","qty":1,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"sesame seed","plural":"sesame seeds","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Cook the rice.","timer":{"label":"Cooking","min":12}},{"text":"Cut the tofu into cubes and marinate it in the soy sauce for 10 minutes.","timer":{"label":"Marinate","min":10}},{"text":"Slice the avocado and mango, and shred the cabbage.","timer":null},{"text":"Build the bowls and sprinkle with sesame seeds.","timer":null}],"variant":"Vegetarian","change":"Marinated tofu replaces the salmon."}]$r$::jsonb, 'claude')
