insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:ramen', 'Ramen', array['en:homemade ramen', 'en:ramen soup']::text[], 'dish', $r$[{"title":"Chicken ramen","intro":"A broth flavoured with soy and ginger, noodles, chicken, a soft-boiled egg and vegetables.","minutes":40,"calories":520,"difficulty":"Moyen","imageSearch":"chicken ramen bowl","veg":false,"oven":false,"cold":false,"missing":"","origin":"Japanese dish","serves":4,"items":[{"name":"ramen noodle","plural":"ramen noodles","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":4,"unit":"tbsp","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"mushroom","plural":"mushrooms","qty":150,"unit":"g","have":false},{"name":"pak choi","plural":"pak choi","qty":2,"unit":"","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Boil the eggs for 6 minutes 30 seconds, then cool them.","timer":{"label":"Eggs","min":6}},{"text":"Heat 1.5 l of water with the stock cubes, soy sauce, ginger and garlic.","timer":null},{"text":"Poach the chicken in the broth for 12 minutes, then slice it.","timer":{"label":"Cooking","min":12}},{"text":"Add the mushrooms and pak choi for 3 minutes, and cook the noodles separately.","timer":{"label":"Cooking","min":3}},{"text":"Serve the noodles in bowls with the broth, chicken, halved egg and spring onion.","timer":null}],"variant":"The classic","change":""},{"title":"Vegetarian miso ramen","intro":"A comforting ramen with miso, tofu and vegetables.","minutes":30,"calories":460,"difficulty":"Moyen","imageSearch":"miso ramen vegetarian","veg":true,"oven":false,"cold":false,"missing":"","origin":"Japanese dish","serves":4,"items":[{"name":"ramen noodle","plural":"ramen noodles","qty":300,"unit":"g","have":false},{"name":"miso paste","plural":"miso paste","qty":3,"unit":"tbsp","have":false},{"name":"firm tofu","plural":"firm tofu","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"mushroom","plural":"mushrooms","qty":150,"unit":"g","have":false},{"name":"spinach","plural":"spinach","qty":100,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Boil the eggs for 6 minutes 30 seconds and cool them.","timer":{"label":"Eggs","min":6}},{"text":"Heat 1.5 l of water with the stock cubes, then add the mushrooms and cubed tofu for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Off the heat, stir the miso into the broth and add the soy sauce and spinach.","timer":null},{"text":"Cook the noodles and serve with the broth, egg and spring onion.","timer":null}],"variant":"Vegetarian","change":"A miso broth replaces the chicken broth."},{"title":"Quick ramen","intro":"A steaming bowl of ramen in 15 minutes.","minutes":15,"calories":420,"difficulty":"Facile","imageSearch":"quick ramen","veg":false,"oven":false,"cold":false,"missing":"","origin":"Japanese dish","serves":4,"items":[{"name":"ramen noodle","plural":"ramen noodles","qty":300,"unit":"g","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"soy sauce","plural":"soy sauce","qty":3,"unit":"tbsp","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":1,"unit":"","have":false},{"name":"spring onion","plural":"spring onions","qty":2,"unit":"","have":false}],"steps":[{"text":"Heat 1.2 l of water with the stock cubes and soy sauce.","timer":null},{"text":"Add the julienned carrot and the noodles, and cook for 4 minutes.","timer":{"label":"Cooking","min":4}},{"text":"Crack the eggs into the broth and let them poach for 3 minutes.","timer":{"label":"Cooking","min":3}},{"text":"Serve with the sliced spring onion.","timer":null}],"variant":"Quick","change":"With ready-made stock and leftover vegetables, in 15 minutes."}]$r$::jsonb, 'claude')
