insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:curry vert thai', 'Thai green curry', array['en:thai green curry', 'en:green curry', 'en:chicken green curry']::text[], 'dish', $r$[{"title":"Thai green chicken curry","intro":"Chicken and vegetables in coconut milk, flavoured with green curry paste and basil.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"thai green curry chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"green curry paste","plural":"green curry paste","qty":2,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"soy sauce","plural":"soy sauce","qty":1,"unit":"tbsp","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the curry paste in the oil for 1 minute.","timer":null},{"text":"Add the chicken strips and brown them for 4 minutes.","timer":{"label":"Cooking","min":4}},{"text":"Pour in the coconut milk, add the vegetables and cook for 12 minutes.","timer":{"label":"Cooking","min":12}},{"text":"Add the soy sauce, the juice of the lime and the basil. Serve with rice.","timer":null}],"variant":"The classic","change":""},{"title":"Thai green prawn curry","intro":"Green curry with juicy prawns.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"thai green curry shrimp","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"prawn","plural":"prawns","qty":400,"unit":"g","have":false},{"name":"green curry paste","plural":"green curry paste","qty":2,"unit":"tbsp","have":false},{"name":"coconut milk","plural":"coconut milk","qty":40,"unit":"cl","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"mangetout","plural":"mangetout","qty":150,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Fry the curry paste in the oil for 1 minute, then pour in the coconut milk.","timer":null},{"text":"Add the pepper and mangetout, and cook for 8 minutes.","timer":{"label":"Cooking","min":8}},{"text":"Add the prawns for 3 minutes, then the lime and basil.","timer":{"label":"Cooking","min":3}}],"variant":"With prawns","change":"Prawns replace the chicken."},{"title":"Light Thai green curry","intro":"All the flavour of green curry, but lighter.","minutes":30,"calories":380,"difficulty":"Facile","imageSearch":"light thai green curry","veg":false,"oven":false,"cold":false,"missing":"","origin":"Thai dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"green curry paste","plural":"green curry paste","qty":2,"unit":"tbsp","have":false},{"name":"light coconut milk","plural":"light coconut milk","qty":20,"unit":"cl","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"lime","plural":"limes","qty":1,"unit":"","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false}],"steps":[{"text":"Heat the curry paste in a casserole dish with a little coconut milk for 1 minute.","timer":null},{"text":"Add the rest of the coconut milk, 20 cl of water and the stock cube.","timer":null},{"text":"Add the chicken strips and the vegetables, and cook for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Add the lime and basil.","timer":null}],"variant":"Lighter","change":"Half coconut milk, half stock."}]$r$::jsonb, 'claude')
