insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet aigre dou', 'Sweet and sour chicken', array['en:sweet and sour chicken', 'en:sweet and sour pork', 'en:sweet sour chicken']::text[], 'dish', $r$[{"title":"Sweet and sour chicken","intro":"Crispy chicken in a sweet and sour sauce with pineapple and peppers.","minutes":30,"calories":540,"difficulty":"Facile","imageSearch":"sweet and sour chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":3,"unit":"tbsp","have":false},{"name":"pineapple","plural":"pineapple","qty":200,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":3,"unit":"tbsp","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":2,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Mix the ketchup, vinegar, sugar, soy sauce and 10 cl of water.","timer":null},{"text":"Dice the chicken, roll it in the cornflour and brown it in the oil for 6 minutes. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Stir-fry the chopped peppers and onion for 4 minutes, then add the pineapple.","timer":{"label":"Wok","min":4}},{"text":"Pour in the sauce, let it thicken for 2 minutes and add the chicken. Serve with rice.","timer":{"label":"Wok","min":2}}],"kids":true,"variant":"The classic","change":""},{"title":"Sweet and sour pork","intro":"The Chinese restaurant classic, with pork.","minutes":30,"calories":580,"difficulty":"Facile","imageSearch":"sweet and sour pork","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"pork tenderloin","plural":"pork tenderloins","qty":1,"unit":"","have":false},{"name":"cornflour","plural":"cornflour","qty":3,"unit":"tbsp","have":false},{"name":"pineapple","plural":"pineapple","qty":200,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"ketchup","plural":"ketchup","qty":3,"unit":"tbsp","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":2,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":2,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false}],"steps":[{"text":"Make the sauce: ketchup, vinegar, sugar and 10 cl of water.","timer":null},{"text":"Dice the pork, coat it in the cornflour and brown it for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Stir-fry the pepper, onion and pineapple for 4 minutes.","timer":{"label":"Wok","min":4}},{"text":"Add the sauce and the pork, and let it thicken for 2 minutes.","timer":{"label":"Wok","min":2}}],"variant":"With pork","change":"Pork tenderloin replaces the chicken."},{"title":"Light sweet and sour chicken","intro":"The sweet and sour in a light version, with more vegetables.","minutes":25,"calories":400,"difficulty":"Facile","imageSearch":"light sweet sour chicken","veg":false,"oven":false,"cold":false,"missing":"","origin":"Chinese dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"pineapple","plural":"pineapple","qty":150,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"broccoli","plural":"broccoli","qty":1,"unit":"","have":false},{"name":"pineapple juice","plural":"pineapple juice","qty":10,"unit":"cl","have":false},{"name":"soy sauce","plural":"soy sauce","qty":2,"unit":"tbsp","have":false},{"name":"rice vinegar","plural":"rice vinegar","qty":1,"unit":"tbsp","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Brown the diced chicken in the oil for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Add the pepper, small broccoli florets and the pineapple, and cook for 5 minutes.","timer":{"label":"Wok","min":5}},{"text":"Mix the pineapple juice, soy sauce, vinegar and cornflour, pour it in and let it thicken for 2 minutes.","timer":{"label":"Wok","min":2}}],"variant":"Lighter","change":"The chicken is not coated in cornflour, and the sauce is less sweet."}]$r$::jsonb, 'claude')
