insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:couscou', 'Couscous', array['en:couscou royal', 'en:moroccan couscou', 'en:chicken couscou']::text[], 'dish', $r$[{"title":"Couscous with chicken and merguez","intro":"Couscous grains, a spiced broth, tender vegetables, chicken and merguez sausages.","minutes":90,"calories":720,"difficulty":"Moyen","imageSearch":"couscous chicken merguez vegetables","veg":false,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":400,"unit":"g","have":false},{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"merguez","plural":"merguez","qty":4,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":2,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken and onions in the oil in a large pot.","timer":null},{"text":"Add the spices, tomatoes, and the carrots and turnips in chunks, then 1.5 l of water. Simmer for 40 minutes.","timer":{"label":"Simmer","min":40}},{"text":"Add the courgettes and chickpeas and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Grill the merguez for 10 minutes.","timer":{"label":"Grill","min":10}},{"text":"Pour over the same volume of boiling salted water as couscous, cover for 5 minutes, then fluff with the butter. Serve with the broth, vegetables and meats.","timer":{"label":"Rest","min":5}}],"kids":true,"variant":"The classic","change":""},{"title":"Vegetable couscous","intro":"A generous, fragrant vegetable couscous.","minutes":60,"calories":520,"difficulty":"Facile","imageSearch":"vegetable couscous","veg":true,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":350,"unit":"g","have":false},{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"turnip","plural":"turnips","qty":2,"unit":"","have":false},{"name":"pumpkin","plural":"pumpkin","qty":300,"unit":"g","have":false},{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"raisin","plural":"raisins","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onions in the oil with the spices.","timer":null},{"text":"Add the tomatoes, carrots, turnips and 1.2 l of water. Simmer for 25 minutes.","timer":{"label":"Simmer","min":25}},{"text":"Add the courgettes, pumpkin, chickpeas and raisins, and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Prepare the couscous with the same volume of boiling salted water and fluff it.","timer":null}],"variant":"Vegetarian","change":"Only vegetables and chickpeas."},{"title":"Quick chicken couscous","intro":"The taste of couscous for a weeknight.","minutes":35,"calories":560,"difficulty":"Facile","imageSearch":"quick chicken couscous","veg":false,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"couscous","plural":"couscous","qty":300,"unit":"g","have":false},{"name":"chicken breast","plural":"chicken breasts","qty":3,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chopped chicken and the onion in the oil with the spices for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the diced carrots and courgettes, the tomatoes and 50 cl of water. Cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Add the chickpeas for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Prepare the couscous and serve with the broth.","timer":null}],"kids":true,"variant":"Quick","change":"With chicken breast and small pieces of vegetables, ready in 35 minutes."}]$r$::jsonb, 'claude')
