insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tajine de poulet', 'Chicken tagine', array['en:chicken tagine', 'en:tajine', 'en:chicken tagine with lemon and olive', 'en:tagine']::text[], 'dish', $r$[{"title":"Chicken tagine with preserved lemons and olives","intro":"Tender chicken flavoured with ginger and saffron, with preserved lemons and olives.","minutes":75,"calories":520,"difficulty":"Moyen","imageSearch":"chicken tagine lemon olives","veg":false,"oven":false,"cold":false,"missing":"","origin":"Moroccan dish","serves":4,"items":[{"name":"chicken pieces","plural":"chicken pieces","qty":1,"unit":"","have":false},{"name":"preserved lemon","plural":"preserved lemons","qty":2,"unit":"","have":false},{"name":"green olive","plural":"green olives","qty":100,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"ginger","plural":"ginger","qty":1,"unit":"tsp","have":false},{"name":"turmeric","plural":"turmeric","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the chicken in the oil with the sliced onions and garlic.","timer":null},{"text":"Add the spices, 30 cl of water, salt and pepper.","timer":null},{"text":"Cover and simmer for 45 minutes.","timer":{"label":"Simmer","min":45}},{"text":"Add the preserved lemons in quarters and the olives, and cook uncovered for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Sprinkle with coriander and serve with couscous or bread.","timer":null}],"variant":"The classic","change":""},{"title":"Chicken tagine with apricots","intro":"A mild, fragrant tagine with apricots and almonds.","minutes":75,"calories":580,"difficulty":"Moyen","imageSearch":"chicken apricot tagine","veg":false,"oven":false,"cold":false,"missing":"","origin":"Moroccan dish","serves":4,"items":[{"name":"chicken pieces","plural":"chicken pieces","qty":1,"unit":"","have":false},{"name":"dried apricot","plural":"dried apricots","qty":150,"unit":"g","have":false},{"name":"almond","plural":"almonds","qty":50,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"honey","plural":"honey","qty":1,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the chicken and onions in the oil with the spices.","timer":null},{"text":"Add 30 cl of water and simmer for 40 minutes.","timer":{"label":"Simmer","min":40}},{"text":"Add the apricots and honey, and cook for 20 minutes.","timer":{"label":"Cooking","min":20}},{"text":"Toast the almonds and sprinkle them over just before serving.","timer":null}],"kids":true,"variant":"With apricots","change":"Dried apricots and honey make a sweet and savoury sauce."},{"title":"Vegetable tagine","intro":"A colourful tagine with tender vegetables and mild spices.","minutes":50,"calories":380,"difficulty":"Facile","imageSearch":"vegetable tagine","veg":true,"oven":false,"cold":false,"missing":"","origin":"Moroccan dish","serves":4,"items":[{"name":"carrot","plural":"carrots","qty":3,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":2,"unit":"","have":false},{"name":"potato","plural":"potatoes","qty":3,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":3,"unit":"","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"ras el hanout","plural":"ras el hanout","qty":2,"unit":"tsp","have":false},{"name":"preserved lemon","plural":"preserved lemons","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onions in the oil with the spices.","timer":null},{"text":"Add the chopped vegetables, the tomatoes and 30 cl of water.","timer":null},{"text":"Cover and simmer for 35 minutes.","timer":{"label":"Simmer","min":35}},{"text":"Add the chickpeas and preserved lemon for 10 minutes.","timer":{"label":"Cooking","min":10}}],"variant":"Vegetarian","change":"Only vegetables and chickpeas."}]$r$::jsonb, 'claude')
