insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:paella', 'Paella', array['en:paella valenciana', 'en:seafood paella', 'en:mixed paella']::text[], 'dish', $r$[{"title":"Paella","intro":"Saffron rice with chicken, chorizo, prawns, mussels and peas.","minutes":60,"calories":650,"difficulty":"Moyen","imageSearch":"seafood paella","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spanish dish","serves":4,"items":[{"name":"round-grain rice","plural":"round-grain rice","qty":350,"unit":"g","have":false},{"name":"chicken thigh","plural":"chicken thighs","qty":4,"unit":"","have":false},{"name":"chorizo","plural":"chorizo","qty":100,"unit":"g","have":false},{"name":"prawn","plural":"prawns","qty":8,"unit":"","have":false},{"name":"mussel","plural":"mussels","qty":500,"unit":"g","have":false},{"name":"pea","plural":"peas","qty":150,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":1,"unit":"","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chopped chicken and the chorizo in the oil in a large frying pan.","timer":null},{"text":"Add the onion, pepper and diced tomatoes, and cook for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the rice, the saffron, then 1 l of hot water with the stock cubes. Do not stir any more.","timer":null},{"text":"Cook for 15 minutes, then add the prawns, mussels and peas.","timer":{"label":"Cooking","min":15}},{"text":"Cover and cook for another 10 minutes, until the mussels open.","timer":{"label":"Cooking","min":10}}],"variant":"The classic","change":""},{"title":"Chicken paella","intro":"The family paella, with chicken and chorizo.","minutes":50,"calories":620,"difficulty":"Moyen","imageSearch":"chicken chorizo paella","veg":false,"oven":false,"cold":false,"missing":"","origin":"Spanish dish","serves":4,"items":[{"name":"round-grain rice","plural":"round-grain rice","qty":350,"unit":"g","have":false},{"name":"chicken thigh","plural":"chicken thighs","qty":6,"unit":"","have":false},{"name":"chorizo","plural":"chorizo","qty":100,"unit":"g","have":false},{"name":"pea","plural":"peas","qty":150,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":1,"unit":"","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken and chorizo in the oil.","timer":null},{"text":"Add the onion, pepper and tomatoes, and cook for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the rice, the saffron and 1 l of hot stock.","timer":null},{"text":"Cook for 20 minutes without stirring, adding the peas for the last 5 minutes.","timer":{"label":"Cooking","min":20}}],"kids":true,"variant":"With chicken","change":"No seafood, just chicken and chorizo."},{"title":"Vegetable paella","intro":"A colourful paella with sunny vegetables.","minutes":45,"calories":480,"difficulty":"Moyen","imageSearch":"vegetable paella","veg":true,"oven":false,"cold":false,"missing":"","origin":"Spanish dish","serves":4,"items":[{"name":"round-grain rice","plural":"round-grain rice","qty":350,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"green pepper","plural":"green peppers","qty":1,"unit":"","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"green bean","plural":"green beans","qty":150,"unit":"g","have":false},{"name":"pea","plural":"peas","qty":100,"unit":"g","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"saffron","plural":"saffron","qty":1,"unit":"","have":false},{"name":"vegetable stock cube","plural":"vegetable stock cubes","qty":2,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and peppers in the oil for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the courgette, beans and diced tomatoes for 5 minutes.","timer":{"label":"Cooking","min":5}},{"text":"Add the rice, the saffron and 1 l of hot stock.","timer":null},{"text":"Cook for 20 minutes without stirring, adding the peas at the end.","timer":{"label":"Cooking","min":20}}],"variant":"Vegetarian","change":"Vegetables replace the meat and seafood."}]$r$::jsonb, 'claude')
