insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:moussaka', 'Moussaka', array['en:greek moussaka', 'en:lamb moussaka']::text[], 'dish', $r$[{"title":"Moussaka","intro":"Layers of aubergine and lamb with tomato and cinnamon, under a golden béchamel.","minutes":100,"calories":640,"difficulty":"Moyen","imageSearch":"greek moussaka","veg":false,"oven":true,"cold":false,"missing":"","origin":"Greek dish","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"minced lamb","plural":"minced lamb","qty":500,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cinnamon","plural":"cinnamon","qty":0.5,"unit":"tsp","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":40,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Slice the aubergines, brush them with oil and roast them for 20 minutes in the oven at 200 °C.","timer":{"label":"Oven","min":20}},{"text":"Fry the onion, garlic and meat, add the tomatoes and cinnamon, and simmer for 20 minutes.","timer":{"label":"Simmer","min":20}},{"text":"Make a béchamel with the butter, flour and milk, then stir in the beaten egg.","timer":null},{"text":"Layer the aubergines and meat in a dish, finish with the béchamel and the Parmesan.","timer":null},{"text":"Bake for 40 minutes at 180 °C.","timer":{"label":"Oven","min":40}}],"variant":"The classic","change":""},{"title":"Beef moussaka","intro":"The family moussaka, made with beef.","minutes":100,"calories":620,"difficulty":"Moyen","imageSearch":"beef moussaka","veg":false,"oven":true,"cold":false,"missing":"","origin":"Greek dish","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cinnamon","plural":"cinnamon","qty":0.5,"unit":"tsp","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"grated emmental","plural":"grated emmental","qty":50,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Roast the oiled aubergine slices for 20 minutes at 200 °C.","timer":{"label":"Oven","min":20}},{"text":"Make the meat sauce with the onion, garlic, beef, tomatoes and cinnamon, for 20 minutes.","timer":{"label":"Simmer","min":20}},{"text":"Make the béchamel.","timer":null},{"text":"Assemble the moussaka, finish with the béchamel and the emmental, and bake for 40 minutes at 180 °C.","timer":{"label":"Oven","min":40}}],"variant":"With beef","change":"Minced beef replaces the lamb, milder and cheaper."},{"title":"Vegetarian lentil moussaka","intro":"A hearty moussaka with lentils and aubergines.","minutes":90,"calories":520,"difficulty":"Moyen","imageSearch":"lentil moussaka vegetarian","veg":true,"oven":true,"cold":false,"missing":"","origin":"Greek dish","serves":4,"items":[{"name":"aubergine","plural":"aubergines","qty":3,"unit":"","have":false},{"name":"green lentil","plural":"green lentils","qty":200,"unit":"g","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cinnamon","plural":"cinnamon","qty":0.5,"unit":"tsp","have":false},{"name":"butter","plural":"butter","qty":40,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":40,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":5,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Roast the oiled aubergines for 20 minutes at 200 °C.","timer":{"label":"Oven","min":20}},{"text":"Cook the lentils for 20 minutes, then mix them with the fried onion and garlic, the tomatoes and the cinnamon.","timer":{"label":"Cooking","min":20}},{"text":"Make the béchamel.","timer":null},{"text":"Assemble the moussaka, finish with the béchamel and the crumbled feta, and bake for 35 minutes.","timer":{"label":"Oven","min":35}}],"variant":"Vegetarian","change":"Lentils replace the meat."}]$r$::jsonb, 'claude')
