insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:falafel', 'Falafel', array['en:homemade falafel']::text[], 'dish', $r$[{"title":"Falafel","intro":"Chickpea and herb balls, crispy outside, soft inside, with a yoghurt sauce.","minutes":40,"calories":450,"difficulty":"Moyen","imageSearch":"falafel","veg":true,"oven":false,"cold":false,"missing":"","origin":"Lebanese dish","serves":4,"items":[{"name":"dried chickpea","plural":"dried chickpeas","qty":250,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"tsp","have":false},{"name":"flour","plural":"flour","qty":2,"unit":"tbsp","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"frying oil","plural":"frying oil","qty":50,"unit":"cl","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"The day before, soak the dried chickpeas in cold water.","timer":null},{"text":"Blend them, drained, with the onion, garlic, herbs, cumin, flour and salt.","timer":null},{"text":"Shape into small balls.","timer":null},{"text":"Deep-fry them for 4 minutes in hot oil, until golden.","timer":{"label":"Frying","min":4}},{"text":"Serve with the yoghurt mixed with the lemon juice.","timer":null}],"makes":{"n":20,"one":"falafel","many":"falafels"},"variant":"The classic","change":""},{"title":"Baked falafel","intro":"Lighter falafel, baked in the oven.","minutes":45,"calories":360,"difficulty":"Moyen","imageSearch":"baked falafel","veg":true,"oven":true,"cold":false,"missing":"","origin":"Lebanese dish","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":2,"unit":"tsp","have":false},{"name":"chickpea flour","plural":"chickpea flour","qty":3,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Blend the drained chickpeas with the onion, garlic, parsley, cumin, flour and salt.","timer":null},{"text":"Shape into slightly flattened balls, put them on a baking tray and brush them with oil.","timer":null},{"text":"Bake for 25 minutes, turning them halfway through.","timer":{"label":"Oven","min":25}}],"makes":{"n":20,"one":"falafel","many":"falafels"},"variant":"Oven-baked","change":"Baked with a drizzle of oil, with no frying."},{"title":"Falafel wrap","intro":"The street sandwich: falafel, salad and white sauce.","minutes":30,"calories":520,"difficulty":"Facile","imageSearch":"falafel wrap","veg":true,"oven":false,"cold":false,"missing":"","origin":"Lebanese dish","serves":4,"items":[{"name":"falafel","plural":"falafel","qty":16,"unit":"","have":false},{"name":"flatbread","plural":"flatbreads","qty":4,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":2,"unit":"","have":false},{"name":"cucumber","plural":"cucumbers","qty":0.5,"unit":"","have":false},{"name":"lettuce","plural":"lettuce","qty":4,"unit":"leaves","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":0.5,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Warm the falafel in the oven for 10 minutes.","timer":{"label":"Oven","min":10}},{"text":"Mix the yoghurt, the lemon juice, the grated garlic and the salt.","timer":null},{"text":"Fill the flatbreads with lettuce, tomato and cucumber, add the falafel and the sauce, and roll up.","timer":null}],"makes":{"n":4,"one":"wrap","many":"wraps"},"variant":"As a wrap","change":"The falafel is rolled in a flatbread with salad and a sauce."}]$r$::jsonb, 'claude')
