insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:houmou', 'Hummus', array['en:hummu', 'en:homemade hummu']::text[], 'dish', $r$[{"title":"Hummus","intro":"The creamy chickpea dip, with tahini, lemon and garlic.","minutes":10,"calories":220,"difficulty":"Facile","imageSearch":"hummus","veg":true,"oven":false,"cold":true,"missing":"","origin":"Lebanese dish","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"tahini","plural":"tahini","qty":3,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"cumin","plural":"cumin","qty":0.5,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Drain the chickpeas, keeping a little of their liquid.","timer":null},{"text":"Blend them with the tahini, the lemon juice, the garlic, the cumin, the salt and 3 tbsp of the liquid, until very smooth.","timer":null},{"text":"Serve with a drizzle of oil and a pinch of paprika.","timer":null}],"variant":"The classic","change":""},{"title":"Beetroot hummus","intro":"A bright pink hummus, mild and original.","minutes":10,"calories":200,"difficulty":"Facile","imageSearch":"beetroot hummus","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"cooked beetroot","plural":"cooked beetroots","qty":1,"unit":"","have":false},{"name":"tahini","plural":"tahini","qty":2,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Blend the drained chickpeas with the chopped beetroot, the tahini, the lemon juice, the garlic and the salt.","timer":null},{"text":"Add a little water if needed for a smooth texture.","timer":null},{"text":"Serve with a drizzle of olive oil.","timer":null}],"variant":"With beetroot","change":"A cooked beetroot colours and sweetens the hummus."},{"title":"Hummus without tahini","intro":"Hummus made with what is in the cupboard.","minutes":10,"calories":200,"difficulty":"Facile","imageSearch":"easy hummus","veg":true,"oven":false,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"chickpea","plural":"chickpeas","qty":400,"unit":"g","have":false},{"name":"greek yoghurt","plural":"greek yoghurts","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"cumin","plural":"cumin","qty":0.5,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Drain and rinse the chickpeas.","timer":null},{"text":"Blend them with the yoghurt, the lemon juice, the garlic, the cumin and the salt.","timer":null},{"text":"Drizzle in the oil while blending, until creamy.","timer":null}],"variant":"Without tahini","change":"The tahini is replaced by yoghurt and a little more oil."}]$r$::jsonb, 'claude')
