insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:shakshuka', 'Shakshuka', array['en:chakchouka', 'en:egg in tomato sauce', 'en:tunisian chakchouka']::text[], 'dish', $r$[{"title":"Shakshuka","intro":"Poached eggs in a tomato and pepper sauce with cumin and paprika.","minutes":30,"calories":320,"difficulty":"Facile","imageSearch":"shakshuka eggs tomato","veg":true,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":2,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and the pepper strips in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the garlic, spices and tomatoes, season with salt and simmer for 10 minutes.","timer":{"label":"Simmer","min":10}},{"text":"Make small wells and crack an egg into each one.","timer":null},{"text":"Cover and cook for 6 minutes, until the whites are set.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with coriander and serve with bread.","timer":null}],"variant":"The classic","change":""},{"title":"Green shakshuka","intro":"An all-green shakshuka with feta.","minutes":25,"calories":300,"difficulty":"Facile","imageSearch":"green shakshuka spinach","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"spinach","plural":"spinach","qty":300,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"leek","plural":"leeks","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":80,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Soften the leek and diced courgette in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the garlic, cumin and spinach until it wilts.","timer":null},{"text":"Crack the eggs over the vegetables, cover and cook for 6 minutes.","timer":{"label":"Cooking","min":6}},{"text":"Sprinkle with feta.","timer":null}],"variant":"Green","change":"Spinach, courgette and herbs replace the tomato."},{"title":"Shakshuka with merguez","intro":"A heartier shakshuka, with merguez.","minutes":30,"calories":460,"difficulty":"Facile","imageSearch":"shakshuka merguez","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"merguez","plural":"merguez","qty":4,"unit":"","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"red pepper","plural":"red peppers","qty":1,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"olive oil","plural":"olive oil","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the merguez cut into chunks for 5 minutes. Set aside.","timer":{"label":"Pan","min":5}},{"text":"Fry the onion and pepper for 8 minutes, add the cumin and tomatoes, and cook for 10 minutes.","timer":{"label":"Simmer","min":18}},{"text":"Put the merguez back, crack in the eggs and cook for 6 minutes with the lid on.","timer":{"label":"Cooking","min":6}}],"variant":"With merguez","change":"Grilled merguez are added to the sauce."}]$r$::jsonb, 'claude')
