insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:boulette de viande', 'Meatballs', array['en:meatball', 'en:meatball in tomato sauce', 'en:kofta', 'en:beef meatball']::text[], 'dish', $r$[{"title":"Beef meatballs in tomato sauce","intro":"Soft meatballs, simmered in a tomato and basil sauce.","minutes":40,"calories":520,"difficulty":"Facile","imageSearch":"meatballs tomato sauce","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":40,"unit":"g","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":800,"unit":"g","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the meat with the egg, breadcrumbs, Parmesan, half the chopped onion, salt and pepper. Shape into meatballs.","timer":null},{"text":"Brown them in the oil for 6 minutes. Set aside.","timer":{"label":"Pan","min":6}},{"text":"Fry the rest of the onion and the garlic, add the tomatoes and cook for 10 minutes.","timer":{"label":"Cooking","min":10}},{"text":"Put the meatballs back and simmer for 15 minutes. Add the basil.","timer":{"label":"Simmer","min":15}}],"kids":true,"makes":{"n":20,"one":"meatball","many":"meatballs"},"variant":"The classic","change":""},{"title":"Oriental kofta","intro":"Spicy oriental meatballs, flavoured with herbs.","minutes":35,"calories":500,"difficulty":"Facile","imageSearch":"kofta meatballs","veg":false,"oven":false,"cold":false,"missing":"","origin":"North African dish","serves":4,"items":[{"name":"minced beef","plural":"minced beef","qty":500,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"coriander","plural":"coriander","qty":null,"unit":"","have":false},{"name":"mint","plural":"mint","qty":null,"unit":"","have":false},{"name":"cumin","plural":"cumin","qty":1,"unit":"tsp","have":false},{"name":"paprika","plural":"paprika","qty":1,"unit":"tsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the meat with the grated onion, the chopped herbs, the spices and the salt. Shape into meatballs.","timer":null},{"text":"Brown them in the oil for 6 minutes.","timer":{"label":"Pan","min":6}},{"text":"Add the tomatoes and simmer for 15 minutes.","timer":{"label":"Simmer","min":15}}],"makes":{"n":16,"one":"kofta","many":"koftas"},"variant":"Kofta","change":"The meatballs are flavoured with cumin, coriander and mint."},{"title":"Chicken meatballs","intro":"Tender chicken meatballs, in a light cream sauce.","minutes":35,"calories":420,"difficulty":"Facile","imageSearch":"chicken meatballs","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"breadcrumb","plural":"breadcrumbs","qty":40,"unit":"g","have":false},{"name":"garlic","plural":"garlic","qty":1,"unit":"clove","have":false},{"name":"parsley","plural":"parsley","qty":null,"unit":"","have":false},{"name":"light cream","plural":"light cream","qty":20,"unit":"cl","have":false},{"name":"button mushroom","plural":"button mushrooms","qty":200,"unit":"g","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Blend the chicken with the egg, breadcrumbs, garlic, parsley, salt and pepper. Shape into meatballs.","timer":null},{"text":"Brown them in the oil for 8 minutes.","timer":{"label":"Pan","min":8}},{"text":"Add the sliced mushrooms for 5 minutes, then the cream, and simmer for 5 minutes.","timer":{"label":"Simmer","min":10}}],"kids":true,"makes":{"n":20,"one":"meatball","many":"meatballs"},"variant":"With chicken","change":"Minced chicken replaces the beef, for lighter meatballs."}]$r$::jsonb, 'claude')
