insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:poulet yassa', 'Chicken yassa', array['en:chicken yassa', 'en:yassa']::text[], 'dish', $r$[{"title":"Chicken yassa","intro":"The Senegalese dish: lemon-marinated chicken, simmered with lots of soft onions.","minutes":80,"calories":520,"difficulty":"Moyen","imageSearch":"chicken yassa","veg":false,"oven":false,"cold":false,"missing":"","origin":"Senegalese dish","serves":4,"items":[{"name":"chicken leg","plural":"chicken legs","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":6,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":4,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":2,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":3,"unit":"clove","have":false},{"name":"chicken stock cube","plural":"chicken stock cubes","qty":1,"unit":"","have":false},{"name":"olive oil","plural":"olive oil","qty":4,"unit":"tbsp","have":false},{"name":"chilli","plural":"chillies","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the juice of the lemons, the mustard, the garlic, the sliced onions, salt and pepper. Marinate the chicken in it for 30 minutes.","timer":{"label":"Marinate","min":30}},{"text":"Brown the drained chicken in the oil. Set aside.","timer":null},{"text":"Soften the onions from the marinade for 15 minutes.","timer":{"label":"Cooking","min":15}},{"text":"Put the chicken back with the rest of the marinade, the stock cube, the chilli and 20 cl of water. Simmer for 30 minutes. Serve with rice.","timer":{"label":"Simmer","min":30}}],"variant":"The classic","change":""},{"title":"Fish yassa","intro":"Fish yassa, zesty and tender.","minutes":50,"calories":420,"difficulty":"Moyen","imageSearch":"fish yassa","veg":false,"oven":false,"cold":false,"missing":"","origin":"Senegalese dish","serves":4,"items":[{"name":"cod fillet","plural":"cod fillets","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":5,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":3,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Marinate the fish for 20 minutes in the juice of the lemons with the garlic, salt and pepper.","timer":{"label":"Marinate","min":20}},{"text":"Soften the sliced onions in the oil for 15 minutes with the mustard.","timer":{"label":"Cooking","min":15}},{"text":"Lay the fish on the onions, pour over the marinade, cover and cook for 12 minutes.","timer":{"label":"Cooking","min":12}}],"variant":"With fish","change":"White fish replaces the chicken."},{"title":"Quick chicken yassa","intro":"Yassa in 40 minutes, for weeknights.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"quick chicken lemon onion","veg":false,"oven":false,"cold":false,"missing":"","origin":"Senegalese dish","serves":4,"items":[{"name":"chicken breast","plural":"chicken breasts","qty":4,"unit":"","have":false},{"name":"onion","plural":"onions","qty":4,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":3,"unit":"","have":false},{"name":"mustard","plural":"mustard","qty":1,"unit":"tbsp","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":3,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Cut the chicken into pieces and mix it with the juice of the lemons, the mustard and the garlic.","timer":null},{"text":"Soften the sliced onions in the oil for 12 minutes.","timer":{"label":"Cooking","min":12}},{"text":"Add the chicken and its marinade, and simmer for 15 minutes.","timer":{"label":"Simmer","min":15}}],"variant":"Quick","change":"With chicken breast and a short marinade."}]$r$::jsonb, 'claude')
