insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:mafe', 'Mafé', array['en:maffe', 'en:peanut stew', 'en:chicken peanut stew']::text[], 'dish', $r$[{"title":"Chicken mafé","intro":"Chicken simmered in a smooth peanut and tomato sauce.","minutes":70,"calories":620,"difficulty":"Moyen","imageSearch":"chicken peanut stew mafe","veg":false,"oven":false,"cold":false,"missing":"","origin":"West African dish","serves":4,"items":[{"name":"chicken leg","plural":"chicken legs","qty":4,"unit":"","have":false},{"name":"peanut butter","plural":"peanut butter","qty":4,"unit":"tbsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"tomato purée","plural":"tomato purée","qty":1,"unit":"tbsp","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"sweet potato","plural":"sweet potatoes","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the chicken in the oil with the onions.","timer":null},{"text":"Add the garlic, tomatoes, tomato purée and 50 cl of water.","timer":null},{"text":"Mix the peanut butter with a little of the sauce and stir it in.","timer":null},{"text":"Add the carrots and sweet potato in chunks, and simmer for 45 minutes. Serve with rice.","timer":{"label":"Simmer","min":45}}],"variant":"The classic","change":""},{"title":"Beef mafé","intro":"The original version, with slow-cooked beef.","minutes":120,"calories":680,"difficulty":"Moyen","imageSearch":"beef peanut stew","veg":false,"oven":false,"cold":false,"missing":"","origin":"West African dish","serves":4,"items":[{"name":"braising beef","plural":"braising beef","qty":800,"unit":"g","have":false},{"name":"peanut butter","plural":"peanut butter","qty":4,"unit":"tbsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"white cabbage","plural":"white cabbages","qty":0.25,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Brown the cubed beef in the oil with the onions.","timer":null},{"text":"Add the garlic, tomatoes, the peanut butter mixed with a little water and 80 cl of water.","timer":null},{"text":"Simmer for 1 hour 15 minutes, then add the carrots and cabbage, and cook for 30 minutes.","timer":{"label":"Simmer","min":105}}],"variant":"With beef","change":"Stewing beef replaces the chicken."},{"title":"Vegetable mafé","intro":"A creamy, comforting veggie mafé.","minutes":45,"calories":480,"difficulty":"Facile","imageSearch":"vegetable peanut stew","veg":true,"oven":false,"cold":false,"missing":"","origin":"West African dish","serves":4,"items":[{"name":"sweet potato","plural":"sweet potatoes","qty":2,"unit":"","have":false},{"name":"carrot","plural":"carrots","qty":2,"unit":"","have":false},{"name":"chickpea","plural":"chickpeas","qty":250,"unit":"g","have":false},{"name":"peanut butter","plural":"peanut butter","qty":3,"unit":"tbsp","have":false},{"name":"chopped tomato","plural":"chopped tomatoes","qty":400,"unit":"g","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"garlic","plural":"garlic","qty":2,"unit":"clove","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Fry the onion and garlic in the oil.","timer":null},{"text":"Add the tomatoes, the peanut butter mixed with a little water and 40 cl of water.","timer":null},{"text":"Add the chopped vegetables and simmer for 30 minutes.","timer":{"label":"Simmer","min":30}},{"text":"Add the chickpeas for 5 minutes.","timer":{"label":"Cooking","min":5}}],"variant":"Vegetarian","change":"Sweet potato, carrots and chickpeas replace the meat."}]$r$::jsonb, 'claude')
