insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:crepe', 'Crêpes', array['en:french pancake']::text[], 'dish', $r$[{"title":"Crêpes","intro":"The foolproof crêpe batter, thin and light, for a snack or Candlemas.","minutes":40,"calories":220,"difficulty":"Facile","imageSearch":"french crepes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Put the flour, sugar and a pinch of salt in a mixing bowl, and make a well in the middle.","timer":null},{"text":"Add the eggs, then the milk a little at a time, whisking to avoid lumps.","timer":null},{"text":"Add the melted butter and leave to rest for 30 min if you can.","timer":{"label":"Rest","min":30}},{"text":"Cook the crêpes in a hot, lightly buttered pan, 1 min on each side.","timer":null}],"kids":true,"dessert":true,"makes":{"n":15,"one":"crepe","many":"crepes"},"variant":"The classic","change":""},{"title":"Dairy-free crêpes","intro":"Just as thin, with no dairy.","minutes":40,"calories":200,"difficulty":"Facile","imageSearch":"dairy free crepes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"oat milk","plural":"oat milk","qty":50,"unit":"cl","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":2,"unit":"tbsp","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, sugar and salt, then add the eggs.","timer":null},{"text":"Pour in the oat milk a little at a time, whisking, then add the oil.","timer":null},{"text":"Leave to rest for 30 min.","timer":{"label":"Rest","min":30}},{"text":"Cook the crêpes in a hot, oiled pan.","timer":null}],"kids":true,"dessert":true,"makes":{"n":15,"one":"crepe","many":"crepes"},"variant":"Dairy-free","change":"Cow's milk is replaced by oat milk and the butter by oil."},{"title":"Buckwheat galettes with ham, egg and emmental","intro":"The classic Breton galettes: ham, egg and emmental.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"buckwheat galette ham egg cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"Breton speciality","serves":4,"items":[{"name":"buckwheat flour","plural":"buckwheat flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":5,"unit":"","have":false},{"name":"ham","plural":"ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, 1 egg, a pinch of salt and 60 cl of cold water. Leave to rest for 1 h.","timer":{"label":"Rest","min":60}},{"text":"Cook a galette in a buttered pan for 2 min.","timer":{"label":"Pan","min":2}},{"text":"Flip it, add the emmental and ham, and crack an egg into the middle.","timer":null},{"text":"Fold the edges into a square and cook until the white is set.","timer":{"label":"Pan","min":3}}],"kids":true,"makes":{"n":8,"one":"galette","many":"galettes"},"variant":"Savoury galettes","change":"Buckwheat flour, with ham, egg and cheese."}]$r$::jsonb, 'claude')
