insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gaufre', 'Waffles', array['en:waffle']::text[], 'dish', $r$[{"title":"Waffles","intro":"Waffles that are crisp outside and soft inside.","minutes":40,"calories":300,"difficulty":"Facile","imageSearch":"waffles","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":50,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, baking powder, sugars and salt.","timer":null},{"text":"Add the egg yolks, then the milk and melted butter.","timer":null},{"text":"Whisk the egg whites until stiff and fold them in gently.","timer":null},{"text":"Cook in the hot waffle iron for 3 to 4 min.","timer":{"label":"Waffle iron","min":4}}],"kids":true,"dessert":true,"makes":{"n":10,"one":"waffle","many":"waffles"},"variant":"The classic","change":""},{"title":"Liège waffles","intro":"Thick Belgian waffles with caramelised pearl sugar.","minutes":120,"calories":380,"difficulty":"Moyen","imageSearch":"liege waffles pearl sugar","veg":true,"oven":false,"cold":false,"missing":"","origin":"Belgian speciality","serves":4,"items":[{"name":"flour","plural":"flour","qty":400,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"warm milk","plural":"warm milk","qty":15,"unit":"cl","have":false},{"name":"soft butter","plural":"soft butter","qty":200,"unit":"g","have":false},{"name":"fresh yeast","plural":"fresh yeast","qty":10,"unit":"g","have":false},{"name":"pearl sugar","plural":"pearl sugar","qty":150,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Dissolve the yeast in the warm milk.","timer":null},{"text":"Mix the flour, eggs, milk and salt, then work in the soft butter.","timer":null},{"text":"Leave to rise for 1 h somewhere warm.","timer":{"label":"Rising","min":60}},{"text":"Add the pearl sugar, shape into balls and cook them for 4 min in the waffle iron.","timer":{"label":"Waffle iron","min":4}}],"dessert":true,"makes":{"n":14,"one":"waffle","many":"waffles"},"variant":"From Liège","change":"A yeast dough with pearl sugar that caramelises."},{"title":"Light waffles","intro":"Soft, lighter waffles.","minutes":35,"calories":220,"difficulty":"Facile","imageSearch":"light waffles","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"semi-skimmed milk","plural":"semi-skimmed milk","qty":30,"unit":"cl","have":false},{"name":"fromage blanc","plural":"fromage blanc","qty":100,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":20,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Mix the flour, baking powder and sugar.","timer":null},{"text":"Add the eggs, fromage blanc, milk and melted butter.","timer":null},{"text":"Cook for 4 min in the hot waffle iron.","timer":{"label":"Waffle iron","min":4}}],"kids":true,"dessert":true,"makes":{"n":8,"one":"waffle","many":"waffles"},"variant":"Lighter","change":"Less butter, and fromage blanc in the batter."}]$r$::jsonb, 'claude')
