insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pancake', 'Pancakes', array['en:american pancake']::text[], 'dish', $r$[{"title":"Pancakes","intro":"Thick, fluffy pancakes to serve with maple syrup.","minutes":25,"calories":280,"difficulty":"Facile","imageSearch":"fluffy pancakes","veg":true,"oven":false,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":40,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"maple syrup","plural":"maple syrup","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the flour, baking powder, sugar and a pinch of salt.","timer":null},{"text":"Add the eggs, milk and melted butter, and mix just enough.","timer":null},{"text":"Pour a small ladle of batter into a hot buttered pan.","timer":null},{"text":"Flip when bubbles appear, after 2 min, and cook for 1 min on the other side.","timer":{"label":"Pan","min":3}},{"text":"Serve with the maple syrup.","timer":null}],"kids":true,"dessert":true,"makes":{"n":16,"one":"pancake","many":"pancakes"},"variant":"The classic","change":""},{"title":"Banana pancakes","intro":"Soft banana pancakes.","minutes":25,"calories":270,"difficulty":"Facile","imageSearch":"banana pancakes","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":25,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"butter","plural":"butter","qty":10,"unit":"g","have":false}],"steps":[{"text":"Mash the bananas and mix them with the eggs and milk.","timer":null},{"text":"Add the flour and baking powder.","timer":null},{"text":"Cook small pancakes for 2 min on each side in a buttered pan.","timer":{"label":"Pan","min":4}}],"kids":true,"dessert":true,"makes":{"n":12,"one":"pancake","many":"pancakes"},"variant":"Banana","change":"A mashed banana replaces some of the sugar."},{"title":"Healthy oat pancakes","intro":"Wholesome, filling pancakes with no added sugar.","minutes":20,"calories":240,"difficulty":"Facile","imageSearch":"oat pancakes healthy","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"porridge oat","plural":"porridge oats","qty":150,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":1,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"blueberry","plural":"blueberries","qty":100,"unit":"g","have":false}],"steps":[{"text":"Blitz the porridge oats with the banana, eggs, milk and baking powder.","timer":null},{"text":"Add the blueberries.","timer":null},{"text":"Cook for 2 min on each side in a non-stick pan.","timer":{"label":"Pan","min":4}}],"kids":true,"dessert":true,"makes":{"n":10,"one":"pancake","many":"pancakes"},"variant":"Healthy","change":"The flour is replaced by blitzed porridge oats."}]$r$::jsonb, 'claude')
