insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:pain perdu', 'French toast', array['en:french toast']::text[], 'dish', $r$[{"title":"French toast","intro":"The no-waste dessert: stale bread soaked in sweet milk and eggs, then browned in butter.","minutes":15,"calories":320,"difficulty":"Facile","imageSearch":"french toast pain perdu","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"stale bread","plural":"stale bread","qty":8,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":25,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":40,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":null,"unit":"","have":false}],"steps":[{"text":"Mix the milk, eggs, sugars and a little cinnamon.","timer":null},{"text":"Soak the slices of bread on both sides.","timer":null},{"text":"Brown them in the butter for 2 min on each side.","timer":{"label":"Pan","min":4}},{"text":"Sprinkle with a little sugar and serve hot.","timer":null}],"kids":true,"dessert":true,"makes":{"n":8,"one":"slice","many":"slices"},"variant":"The classic","change":""},{"title":"Brioche French toast","intro":"An even more indulgent version, with caramelised brioche.","minutes":15,"calories":420,"difficulty":"Facile","imageSearch":"brioche french toast","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"brioche","plural":"brioche","qty":8,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":50,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false}],"steps":[{"text":"Mix the milk, eggs and half the sugar.","timer":null},{"text":"Quickly dip the slices of brioche.","timer":null},{"text":"Brown them in the butter, sprinkle with the rest of the sugar and let it caramelise for 1 min on each side.","timer":{"label":"Pan","min":5}}],"kids":true,"dessert":true,"makes":{"n":8,"one":"slice","many":"slices"},"variant":"Brioche","change":"Brioche replaces the bread, with a touch of caramel."},{"title":"Savoury French toast","intro":"French toast as an evening meal, topped with melted cheese.","minutes":20,"calories":420,"difficulty":"Facile","imageSearch":"savory french toast ham cheese","veg":false,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"stale bread","plural":"stale bread","qty":8,"unit":"slices","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"milk","plural":"milk","qty":20,"unit":"cl","have":false},{"name":"ham","plural":"ham","qty":4,"unit":"slices","have":false},{"name":"grated emmental","plural":"grated emmental","qty":80,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Beat the eggs with the milk, salt and pepper.","timer":null},{"text":"Soak the bread and brown it in the butter for 2 min on one side.","timer":{"label":"Pan","min":2}},{"text":"Flip it, add the ham and emmental, cover and cook for 3 min.","timer":{"label":"Pan","min":3}}],"kids":true,"makes":{"n":8,"one":"slice","many":"slices"},"variant":"Savoury","change":"A savoury version with cheese and ham."}]$r$::jsonb, 'claude')
