insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gateau au chocolat', 'Chocolate cake', array['en:chocolate cake', 'en:chocolate fondant', 'en:chocolate sponge']::text[], 'dish', $r$[{"title":"Chocolate cake","intro":"The cake that is gooey in the middle, everyone's favourite dessert.","minutes":40,"calories":420,"difficulty":"Facile","imageSearch":"chocolate cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":150,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"flour","plural":"flour","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate and butter together.","timer":null},{"text":"Whisk the eggs with the sugar, then add the chocolate and flour.","timer":null},{"text":"Pour into a buttered tin and bake for 22 min: the centre should still wobble.","timer":{"label":"Oven","min":22}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Lighter chocolate cake","intro":"The gooey cake, in a lighter version.","minutes":40,"calories":280,"difficulty":"Facile","imageSearch":"light chocolate cake applesauce","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"apple purée","plural":"apple purée","qty":150,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":50,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate and mix it with the apple purée.","timer":null},{"text":"Add the eggs beaten with the sugar, then the flour.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"dessert":true,"variant":"Lighter","change":"The butter is replaced by apple purée."},{"title":"Gluten-free chocolate cake","intro":"A gooey chocolate and almond cake, gluten-free.","minutes":40,"calories":460,"difficulty":"Facile","imageSearch":"flourless chocolate almond cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":120,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":4,"unit":"","have":false},{"name":"ground almonds","plural":"ground almonds","qty":80,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 170 °C.","timer":null},{"text":"Melt the chocolate and butter.","timer":null},{"text":"Whisk the eggs with the sugar, add the chocolate, then the ground almonds.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"dessert":true,"variant":"Gluten-free","change":"The flour is replaced by ground almonds."}]$r$::jsonb, 'claude')
