insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:brownie', 'Brownies', array['en:walnut brownie']::text[], 'dish', $r$[{"title":"Walnut brownies","intro":"A dense, fudgy brownie with crunchy walnuts.","minutes":35,"calories":450,"difficulty":"Facile","imageSearch":"chocolate brownie walnuts","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":150,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":150,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":80,"unit":"g","have":false},{"name":"walnut","plural":"walnuts","qty":80,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate and butter.","timer":null},{"text":"Whisk the eggs with the sugar, then add the chocolate, flour, a pinch of salt and the chopped walnuts.","timer":null},{"text":"Pour into a square tin and bake for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Leave to cool before cutting into squares.","timer":null}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Banana brownies","intro":"A soft, no-waste brownie made with very ripe bananas.","minutes":35,"calories":330,"difficulty":"Facile","imageSearch":"banana brownie","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"banana","plural":"bananas","qty":2,"unit":"","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":60,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"flour","plural":"flour","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate with the butter.","timer":null},{"text":"Mash the bananas and mix with the eggs, sugar, chocolate and flour.","timer":null},{"text":"Bake for 22 min.","timer":{"label":"Oven","min":22}}],"kids":true,"dessert":true,"variant":"Banana","change":"Banana replaces some of the butter and sugar."},{"title":"Gluten-free brownies","intro":"A fudgy almond brownie, gluten-free.","minutes":35,"calories":480,"difficulty":"Facile","imageSearch":"gluten free brownie","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":120,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"ground almonds","plural":"ground almonds","qty":80,"unit":"g","have":false},{"name":"hazelnut","plural":"hazelnuts","qty":50,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Melt the chocolate and butter.","timer":null},{"text":"Add the eggs beaten with the sugar, the ground almonds and the chopped hazelnuts.","timer":null},{"text":"Bake for 20 min.","timer":{"label":"Oven","min":20}}],"dessert":true,"variant":"Gluten-free","change":"The flour is replaced by ground almonds."}]$r$::jsonb, 'claude')
