insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cookie', 'Cookies', array['en:chocolate chip cookie']::text[], 'dish', $r$[{"title":"Chocolate chip cookies","intro":"Cookies that are crisp at the edges and soft in the middle.","minutes":25,"calories":220,"difficulty":"Facile","imageSearch":"chocolate chip cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":100,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":120,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":0.5,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the soft butter and sugar, then add the egg.","timer":null},{"text":"Add the flour, baking powder, a pinch of salt and the chocolate chips.","timer":null},{"text":"Shape into balls and place them well apart on a baking tray.","timer":null},{"text":"Bake for 10 min: they should stay soft in the middle.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":16,"one":"cookie","many":"cookies"},"variant":"The classic","change":""},{"title":"Oatmeal cookies","intro":"Rustic cookies with oats and raisins.","minutes":25,"calories":200,"difficulty":"Facile","imageSearch":"oatmeal raisin cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"porridge oat","plural":"porridge oats","qty":120,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":100,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":90,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":80,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"raisin","plural":"raisins","qty":60,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":0.5,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the butter and sugar, then add the egg.","timer":null},{"text":"Add the flour, oats, cinnamon and raisins.","timer":null},{"text":"Drop small heaps onto a baking tray and bake for 12 min.","timer":{"label":"Oven","min":12}}],"dessert":true,"makes":{"n":16,"one":"cookie","many":"cookies"},"variant":"Oaty","change":"Porridge oats and raisins replace some of the flour."},{"title":"Double chocolate cookies","intro":"Cocoa cookies with melting white chocolate.","minutes":25,"calories":240,"difficulty":"Facile","imageSearch":"double chocolate cookies","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":170,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":30,"unit":"g","have":false},{"name":"soft butter","plural":"soft butter","qty":100,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":110,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":1,"unit":"","have":false},{"name":"white chocolate","plural":"white chocolate","qty":100,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":0.5,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the butter and sugar, then the egg.","timer":null},{"text":"Add the flour, cocoa, baking powder and the white chocolate in pieces.","timer":null},{"text":"Shape into balls and bake for 10 min.","timer":{"label":"Oven","min":10}}],"kids":true,"dessert":true,"makes":{"n":16,"one":"cookie","many":"cookies"},"variant":"Double chocolate","change":"Cocoa in the dough and white chocolate chunks."}]$r$::jsonb, 'claude')
