insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:muffin', 'Muffins', array['en:blueberry muffin']::text[], 'dish', $r$[{"title":"Blueberry muffins","intro":"Well-risen, soft muffins full of blueberries.","minutes":35,"calories":280,"difficulty":"Facile","imageSearch":"blueberry muffins","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"flour","plural":"flour","qty":250,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"blueberry","plural":"blueberries","qty":150,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Mix the flour, sugar and baking powder in one bowl, and the eggs, milk and butter in another.","timer":null},{"text":"Pour the liquid onto the flour and barely mix, then add the blueberries.","timer":null},{"text":"Fill muffin cases three-quarters full and bake for 20 min.","timer":{"label":"Oven","min":20}}],"kids":true,"dessert":true,"makes":{"n":12,"one":"muffin","many":"muffins"},"variant":"The classic","change":""},{"title":"Chocolate muffins","intro":"All-chocolate muffins, just like from the bakery.","minutes":35,"calories":320,"difficulty":"Facile","imageSearch":"chocolate muffins","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":220,"unit":"g","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":30,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"chocolate chip","plural":"chocolate chips","qty":100,"unit":"g","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Mix the dry ingredients, then the liquids separately.","timer":null},{"text":"Combine the two without overmixing, and add the chocolate chips.","timer":null},{"text":"Fill the cases and bake for 20 min.","timer":{"label":"Oven","min":20}}],"kids":true,"dessert":true,"makes":{"n":12,"one":"muffin","many":"muffins"},"variant":"Chocolate","change":"Cocoa and chocolate chips replace the blueberries."},{"title":"Courgette and feta savoury muffins","intro":"Savoury muffins with courgette and feta.","minutes":35,"calories":220,"difficulty":"Facile","imageSearch":"savory zucchini feta muffins","veg":true,"oven":true,"cold":true,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"courgette","plural":"courgettes","qty":1,"unit":"","have":false},{"name":"feta","plural":"feta","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"milk","plural":"milk","qty":15,"unit":"cl","have":false},{"name":"olive oil","plural":"olive oil","qty":6,"unit":"tbsp","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 190 °C. Grate the courgette and squeeze out the water.","timer":null},{"text":"Mix the flour, baking powder, salt and pepper, then the eggs, milk and oil.","timer":null},{"text":"Add the courgette and the diced feta.","timer":null},{"text":"Fill the cases and bake for 22 min.","timer":{"label":"Oven","min":22}}],"makes":{"n":12,"one":"muffin","many":"muffins"},"variant":"Savoury","change":"A savoury version, for party snacks or the lunch box."}]$r$::jsonb, 'claude')
