insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:cake au citron', 'Lemon cake', array['en:lemon cake', 'en:lemon loaf', 'en:lemon drizzle cake']::text[], 'dish', $r$[{"title":"Lemon cake","intro":"A moist, fragrant cake topped with a lemon glaze.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"lemon loaf cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"melted butter","plural":"melted butter","qty":120,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false},{"name":"icing sugar","plural":"icing sugar","qty":80,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Whisk the eggs and sugar, then add the melted butter and the zest and juice of one lemon.","timer":null},{"text":"Add the flour and baking powder, and pour into a loaf tin.","timer":null},{"text":"Bake for 40 min.","timer":{"label":"Oven","min":40}},{"text":"Mix the icing sugar with the juice of the other lemon and pour over the cooled cake.","timer":null}],"dessert":true,"variant":"The classic","change":""},{"title":"Lemon and poppy seed cake","intro":"The lemon cake, with poppy seeds.","minutes":60,"calories":330,"difficulty":"Facile","imageSearch":"lemon poppy seed cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":160,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"melted butter","plural":"melted butter","qty":120,"unit":"g","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"poppy seed","plural":"poppy seeds","qty":2,"unit":"tbsp","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the eggs and sugar, then the butter, and the zest and juice of the lemons.","timer":null},{"text":"Add the flour, baking powder and poppy seeds.","timer":null},{"text":"Bake for 40 min in a loaf tin.","timer":{"label":"Oven","min":40}}],"dessert":true,"variant":"Poppy seed","change":"Poppy seeds add some crunch."},{"title":"Light lemon cake","intro":"The lemon cake, soft and lighter.","minutes":55,"calories":240,"difficulty":"Facile","imageSearch":"light lemon yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"flour","plural":"flour","qty":200,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"natural yogurt","plural":"natural yogurts","qty":1,"unit":"","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":4,"unit":"tbsp","have":false},{"name":"lemon","plural":"lemons","qty":2,"unit":"","have":false},{"name":"baking powder","plural":"baking powder","qty":2,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the eggs, sugar, yogurt, oil, and the zest and juice of the lemons.","timer":null},{"text":"Add the flour and baking powder.","timer":null},{"text":"Bake for 40 min.","timer":{"label":"Oven","min":40}}],"dessert":true,"variant":"Lighter","change":"The butter is replaced by yogurt."}]$r$::jsonb, 'claude')
