insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:gateau au yaourt', 'Yogurt cake', array['en:yogurt cake', 'en:french yogurt cake']::text[], 'dish', $r$[{"title":"Yogurt cake","intro":"The first cake everyone learns, soft and foolproof.","minutes":45,"calories":280,"difficulty":"Facile","imageSearch":"yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"natural yogurt","plural":"natural yogurts","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":210,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":6,"unit":"cl","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Pour the yogurt into a mixing bowl.","timer":null},{"text":"Add the eggs, sugar, flour, baking powder, vanilla sugar and oil, mixing as you go.","timer":null},{"text":"Pour into a buttered tin and bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Apple and yogurt cake","intro":"The yogurt cake, with soft apples.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"apple yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"natural yogurt","plural":"natural yogurts","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":210,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":6,"unit":"cl","have":false},{"name":"apple","plural":"apples","qty":2,"unit":"","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Make the yogurt cake batter.","timer":null},{"text":"Add the peeled apples in small pieces.","timer":null},{"text":"Bake for 40 min.","timer":{"label":"Oven","min":40}}],"kids":true,"dessert":true,"variant":"With apples","change":"Thin slices of apple are added to the batter."},{"title":"Marble yogurt cake","intro":"The yogurt cake, marbled with chocolate.","minutes":45,"calories":300,"difficulty":"Facile","imageSearch":"marble yogurt cake","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"natural yogurt","plural":"natural yogurts","qty":1,"unit":"","have":false},{"name":"flour","plural":"flour","qty":210,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":180,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sunflower oil","plural":"sunflower oil","qty":6,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false},{"name":"baking powder","plural":"baking powder","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Make the yogurt cake batter and divide it in two.","timer":null},{"text":"Add the cocoa to one half.","timer":null},{"text":"Pour the two batters into a tin, alternating them, and bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true,"variant":"Marbled","change":"Half the batter is flavoured with cocoa."}]$r$::jsonb, 'claude')
