insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tarte aux pomme', 'Apple tart', array['en:apple tart', 'en:french apple tart']::text[], 'dish', $r$[{"title":"Apple tart","intro":"Crisp pastry, homemade apple purée and golden slices of apple.","minutes":60,"calories":320,"difficulty":"Facile","imageSearch":"french apple tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"apple","plural":"apples","qty":6,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":30,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry out into a tin.","timer":null},{"text":"Make a quick purée with 3 diced apples, half the sugar and a little water, for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Spread the purée over the pastry and arrange the other 3 apples on top in thin slices.","timer":null},{"text":"Sprinkle with the rest of the sugar and dot with small pieces of butter.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Thin apple tart","intro":"A light, crisp tart, ready in 30 minutes.","minutes":30,"calories":280,"difficulty":"Facile","imageSearch":"thin apple tart puff pastry","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":1,"unit":"","have":false},{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":40,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Lay the pastry on a baking tray and prick it with a fork.","timer":null},{"text":"Cut the apples into very thin slices and arrange them in a rosette.","timer":null},{"text":"Sprinkle with sugar and dot with butter.","timer":null},{"text":"Bake for 25 min.","timer":{"label":"Oven","min":25}}],"dessert":true,"variant":"Thin tart","change":"Thin puff pastry, with no purée."},{"title":"Normandy apple tart","intro":"The Normandy apple tart, with its golden cream topping.","minutes":60,"calories":380,"difficulty":"Facile","imageSearch":"normandy apple tart cream","veg":true,"oven":true,"cold":false,"missing":"","origin":"Norman speciality","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":2,"unit":"","have":false},{"name":"crème fraîche","plural":"crème fraîche","qty":20,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C. Roll the pastry out into a tin.","timer":null},{"text":"Arrange the apples in thin wedges.","timer":null},{"text":"Bake for 15 min.","timer":{"label":"Oven","min":15}},{"text":"Beat the eggs, cream and sugars, pour over the apples and bake for another 25 min.","timer":{"label":"Oven","min":25}}],"dessert":true,"variant":"Normandy-style","change":"A cream and egg custard covers the apples."}]$r$::jsonb, 'claude')
