insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tarte tatin', 'Tarte tatin', array['en:upside down apple tart', 'en:tatin']::text[], 'dish', $r$[{"title":"Tarte tatin","intro":"The upside-down tart: caramelised apples under crisp pastry.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"shortcrust pastry","plural":"shortcrust pastries","qty":1,"unit":"","have":false},{"name":"apple","plural":"apples","qty":7,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":120,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":60,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Make an amber caramel with the sugar in a pan that can go on the hob, then add the butter.","timer":{"label":"Caramel","min":6}},{"text":"Pack the apple wedges tightly into the caramel and cook for 10 min.","timer":{"label":"Cooking","min":10}},{"text":"Cover with the pastry, tucking in the edges, and bake for 30 min.","timer":{"label":"Oven","min":30}},{"text":"Leave to cool for 10 min, then turn out onto a plate.","timer":{"label":"Rest","min":10}}],"dessert":true,"variant":"The classic","change":""},{"title":"Pear tarte tatin","intro":"The tatin with a twist, made with caramelised pears.","minutes":60,"calories":370,"difficulty":"Moyen","imageSearch":"pear tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":1,"unit":"","have":false},{"name":"pear","plural":"pears","qty":6,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":100,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 190 °C.","timer":null},{"text":"Make a caramel with the sugar, then add the butter.","timer":{"label":"Caramel","min":6}},{"text":"Arrange the pear wedges in the caramel and cover with the pastry.","timer":null},{"text":"Bake for 30 min, then turn out.","timer":{"label":"Oven","min":30}}],"dessert":true,"variant":"Pear","change":"Pears replace the apples."},{"title":"Tomato tarte tatin","intro":"A sweet and savoury tatin made with tomatoes.","minutes":50,"calories":320,"difficulty":"Facile","imageSearch":"tomato tarte tatin","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"puff pastry","plural":"puff pastries","qty":1,"unit":"","have":false},{"name":"tomato","plural":"tomatoes","qty":6,"unit":"","have":false},{"name":"onion","plural":"onions","qty":1,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":1,"unit":"tbsp","have":false},{"name":"olive oil","plural":"olive oil","qty":2,"unit":"tbsp","have":false},{"name":"grated parmesan","plural":"grated parmesan","qty":30,"unit":"g","have":false},{"name":"thyme","plural":"thyme","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 200 °C.","timer":null},{"text":"Caramelise the sliced onion with the oil and sugar in a pan that can go on the hob, for 5 min.","timer":{"label":"Cooking","min":5}},{"text":"Arrange the halved tomatoes skin-side down, and add the thyme, parmesan and salt.","timer":null},{"text":"Cover with the pastry and bake for 30 min, then turn out.","timer":{"label":"Oven","min":30}}],"variant":"Savoury","change":"A savoury version, with slow-roasted tomatoes and parmesan."}]$r$::jsonb, 'claude')
