insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tarte au citron', 'Lemon tart', array['en:lemon tart', 'en:lemon meringue pie']::text[], 'dish', $r$[{"title":"Lemon meringue tart","intro":"A tangy lemon curd under a light, golden meringue.","minutes":80,"calories":380,"difficulty":"Moyen","imageSearch":"lemon meringue tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet shortcrust pastry","plural":"sweet shortcrust pastries","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":200,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":80,"unit":"g","have":false},{"name":"cornflour","plural":"cornflour","qty":1,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Blind-bake the pastry for 20 min.","timer":{"label":"Oven","min":20}},{"text":"Heat the lemon juice and zest with 100 g of sugar, the yolks, the cornflour and the butter, stirring until thick.","timer":{"label":"Curd","min":5}},{"text":"Pour onto the pastry.","timer":null},{"text":"Whisk the whites until stiff with the rest of the sugar and spread over the curd.","timer":null},{"text":"Brown for 5 min under the oven grill.","timer":{"label":"Grill","min":5}}],"dessert":true,"variant":"The classic","change":""},{"title":"Lemon tart","intro":"The simple lemon tart, tangy and melting.","minutes":60,"calories":340,"difficulty":"Facile","imageSearch":"lemon tart","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"sweet shortcrust pastry","plural":"sweet shortcrust pastries","qty":1,"unit":"","have":false},{"name":"lemon","plural":"lemons","qty":4,"unit":"","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":150,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":100,"unit":"g","have":false}],"steps":[{"text":"Blind-bake the pastry for 20 min at 180 °C.","timer":{"label":"Oven","min":20}},{"text":"Thicken the lemon juice and zest with the sugar and eggs, stirring over a low heat.","timer":{"label":"Curd","min":5}},{"text":"Take off the heat and stir in the butter in pieces.","timer":null},{"text":"Pour onto the pastry and leave to set for 2 h in the fridge.","timer":{"label":"Chill","min":120}}],"dessert":true,"variant":"No meringue","change":"No meringue: just the lemon curd."},{"title":"Key lime pie","intro":"A fresh lime tart, key lime pie style.","minutes":40,"calories":400,"difficulty":"Facile","imageSearch":"key lime pie","veg":true,"oven":true,"cold":false,"missing":"","origin":"American dish","serves":4,"items":[{"name":"digestive biscuit","plural":"digestive biscuits","qty":200,"unit":"g","have":false},{"name":"melted butter","plural":"melted butter","qty":80,"unit":"g","have":false},{"name":"lime","plural":"limes","qty":4,"unit":"","have":false},{"name":"condensed milk","plural":"condensed milk","qty":400,"unit":"g","have":false},{"name":"egg yolk","plural":"egg yolks","qty":3,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 170 °C.","timer":null},{"text":"Crush the biscuits, mix them with the melted butter and press into a tin.","timer":null},{"text":"Mix the condensed milk, yolks, and the juice and zest of the limes, and pour onto the base.","timer":null},{"text":"Bake for 15 min, then leave to set for 3 h in the fridge.","timer":{"label":"Oven","min":15}}],"dessert":true,"variant":"Lime","change":"Lime replaces lemon, with a biscuit base."}]$r$::jsonb, 'claude')
