insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:clafouti', 'Clafoutis', array['en:cherry clafouti']::text[], 'dish', $r$[{"title":"Cherry clafoutis","intro":"The dessert from the Limousin: cherries in a soft baked custard.","minutes":50,"calories":280,"difficulty":"Facile","imageSearch":"cherry clafoutis","veg":true,"oven":true,"cold":false,"missing":"","origin":"Limousin speciality","serves":4,"items":[{"name":"cherry","plural":"cherries","qty":500,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":80,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false},{"name":"vanilla sugar","plural":"vanilla sugar","qty":1,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Butter a dish and spread the cherries in it.","timer":null},{"text":"Whisk the eggs with the sugars, then add the flour and the milk.","timer":null},{"text":"Pour over the cherries.","timer":null},{"text":"Bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Apricot clafoutis","intro":"The summer clafoutis, with apricots and almonds.","minutes":50,"calories":300,"difficulty":"Facile","imageSearch":"apricot clafoutis","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apricot","plural":"apricots","qty":600,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":50,"unit":"g","have":false},{"name":"ground almonds","plural":"ground almonds","qty":40,"unit":"g","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"butter","plural":"butter","qty":20,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Arrange the halved apricots in a buttered dish.","timer":null},{"text":"Mix the eggs, sugar, flour, ground almonds and milk.","timer":null},{"text":"Pour over and bake for 35 min.","timer":{"label":"Oven","min":35}}],"kids":true,"dessert":true,"variant":"Apricot","change":"Apricots replace the cherries, with ground almonds."},{"title":"Savoury clafoutis","intro":"An evening clafoutis with cherry tomatoes and goat's cheese.","minutes":45,"calories":320,"difficulty":"Facile","imageSearch":"savory clafoutis tomato goat cheese","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"cherry tomato","plural":"cherry tomatoes","qty":300,"unit":"g","have":false},{"name":"soft goat's cheese","plural":"soft goat's cheeses","qty":100,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"flour","plural":"flour","qty":60,"unit":"g","have":false},{"name":"milk","plural":"milk","qty":30,"unit":"cl","have":false},{"name":"basil","plural":"basil","qty":null,"unit":"","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false},{"name":"pepper","plural":"pepper","qty":null,"unit":"","have":false}],"steps":[{"text":"Preheat the oven to 180 °C. Put the tomatoes in an oiled dish.","timer":null},{"text":"Whisk the eggs, flour and milk, then add the crumbled goat's cheese, basil, salt and pepper.","timer":null},{"text":"Pour over and bake for 30 min.","timer":{"label":"Oven","min":30}}],"variant":"Savoury","change":"A savoury version with cherry tomatoes and goat's cheese."}]$r$::jsonb, 'claude')
