insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:crumble', 'Crumble', array['en:apple crumble']::text[], 'dish', $r$[{"title":"Apple crumble","intro":"Soft apples under a crunchy, buttery topping.","minutes":45,"calories":340,"difficulty":"Facile","imageSearch":"apple crumble","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":6,"unit":"","have":false},{"name":"flour","plural":"flour","qty":120,"unit":"g","have":false},{"name":"cold butter","plural":"cold butter","qty":100,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Cut the apples into pieces and put them in a dish with the cinnamon and 20 g of sugar.","timer":null},{"text":"Rub the flour, the rest of the sugar and the diced butter together with your fingertips.","timer":null},{"text":"Spread over the apples and bake for 30 min.","timer":{"label":"Oven","min":30}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Apple and berry crumble","intro":"A tangy crumble with apples and mixed berries.","minutes":45,"calories":330,"difficulty":"Facile","imageSearch":"apple berry crumble","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":3,"unit":"","have":false},{"name":"mixed berries","plural":"mixed berries","qty":300,"unit":"g","have":false},{"name":"flour","plural":"flour","qty":120,"unit":"g","have":false},{"name":"cold butter","plural":"cold butter","qty":100,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":100,"unit":"g","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Mix the diced apples and mixed berries in a dish.","timer":null},{"text":"Rub together the flour, sugar and butter, and spread over the fruit.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true,"variant":"With berries","change":"Mixed berries are added to the apples."},{"title":"Healthy oat crumble","intro":"A crunchy, lighter crumble made with porridge oats.","minutes":45,"calories":260,"difficulty":"Facile","imageSearch":"oat crumble healthy","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"apple","plural":"apples","qty":4,"unit":"","have":false},{"name":"pear","plural":"pears","qty":2,"unit":"","have":false},{"name":"porridge oat","plural":"porridge oats","qty":80,"unit":"g","have":false},{"name":"ground almonds","plural":"ground almonds","qty":40,"unit":"g","have":false},{"name":"butter","plural":"butter","qty":50,"unit":"g","have":false},{"name":"honey","plural":"honey","qty":2,"unit":"tbsp","have":false},{"name":"cinnamon","plural":"cinnamon","qty":1,"unit":"tsp","have":false}],"steps":[{"text":"Preheat the oven to 180 °C.","timer":null},{"text":"Put the chopped fruit in a dish with the cinnamon.","timer":null},{"text":"Mix the oats, ground almonds, melted butter and honey, and spread over the fruit.","timer":null},{"text":"Bake for 30 min.","timer":{"label":"Oven","min":30}}],"dessert":true,"variant":"Healthy","change":"Porridge oats, and less butter and sugar."}]$r$::jsonb, 'claude')
