insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:mousse au chocolat', 'Chocolate mousse', array['en:chocolate mousse']::text[], 'dish', $r$[{"title":"Chocolate mousse","intro":"The airy dark chocolate mousse, with just eggs and chocolate.","minutes":20,"calories":300,"difficulty":"Facile","imageSearch":"chocolate mousse","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":6,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":30,"unit":"g","have":false},{"name":"salt","plural":"salt","qty":null,"unit":"","have":false}],"steps":[{"text":"Melt the chocolate in a bowl over simmering water and leave to cool slightly.","timer":null},{"text":"Separate the whites from the yolks, and stir the yolks into the chocolate.","timer":null},{"text":"Whisk the whites until stiff with a pinch of salt, then add the sugar.","timer":null},{"text":"Gently fold the whites into the chocolate.","timer":null},{"text":"Chill for at least 3 h.","timer":{"label":"Chill","min":180}}],"kids":true,"dessert":true,"variant":"The classic","change":""},{"title":"Milk chocolate mousse","intro":"A sweet, indulgent mousse that kids love.","minutes":20,"calories":320,"difficulty":"Facile","imageSearch":"milk chocolate mousse","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"milk chocolate","plural":"milk chocolate","qty":200,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":5,"unit":"","have":false},{"name":"double cream","plural":"double cream","qty":10,"unit":"cl","have":false}],"steps":[{"text":"Melt the chocolate with the cream.","timer":null},{"text":"Add the egg yolks.","timer":null},{"text":"Whisk the whites until stiff and fold them in.","timer":null},{"text":"Chill for 3 h.","timer":{"label":"Chill","min":180}}],"kids":true,"dessert":true,"variant":"Milk chocolate","change":"Milk chocolate makes it sweeter."},{"title":"Vegan chocolate mousse","intro":"A light chocolate mousse with no eggs.","minutes":20,"calories":220,"difficulty":"Facile","imageSearch":"vegan aquafaba chocolate mousse","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"dark chocolate","plural":"dark chocolate","qty":150,"unit":"g","have":false},{"name":"chickpea water","plural":"chickpea water","qty":15,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":20,"unit":"g","have":false}],"steps":[{"text":"Melt the chocolate and leave to cool slightly.","timer":null},{"text":"Whisk the chickpea water until stiff, then add the sugar.","timer":null},{"text":"Gently fold in the chocolate.","timer":null},{"text":"Chill for 3 h.","timer":{"label":"Chill","min":180}}],"dessert":true,"variant":"Vegan","change":"Chickpea water replaces the egg whites."}]$r$::jsonb, 'claude')
