insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:tiramisu', 'Tiramisu', array['en:coffee tiramisu']::text[], 'dish', $r$[{"title":"Tiramisu","intro":"Coffee-soaked biscuits, a mascarpone cream and a dusting of cocoa.","minutes":30,"calories":450,"difficulty":"Facile","imageSearch":"tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"Italian dessert","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"sponge finger","plural":"sponge fingers","qty":20,"unit":"","have":false},{"name":"strong coffee","plural":"strong coffee","qty":30,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the yolks with the sugar, then add the mascarpone.","timer":null},{"text":"Whisk the whites until stiff and fold them in.","timer":null},{"text":"Quickly dip the sponge fingers in the cold coffee and line a dish with them.","timer":null},{"text":"Alternate cream and sponge fingers, finishing with cream.","timer":null},{"text":"Chill for 6 h, then dust with cocoa.","timer":{"label":"Chill","min":360}}],"dessert":true,"variant":"The classic","change":""},{"title":"Strawberry tiramisu","intro":"The spring tiramisu, with strawberries.","minutes":30,"calories":400,"difficulty":"Facile","imageSearch":"strawberry tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"egg","plural":"eggs","qty":3,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"sponge finger","plural":"sponge fingers","qty":20,"unit":"","have":false},{"name":"strawberry","plural":"strawberries","qty":400,"unit":"g","have":false},{"name":"orange juice","plural":"orange juice","qty":20,"unit":"cl","have":false}],"steps":[{"text":"Make the mascarpone cream as for the classic tiramisu.","timer":null},{"text":"Dip the sponge fingers in the orange juice.","timer":null},{"text":"Alternate sponge fingers, chopped strawberries and cream.","timer":null},{"text":"Chill for 4 h.","timer":{"label":"Chill","min":240}}],"kids":true,"dessert":true,"variant":"Strawberry","change":"Strawberries replace the coffee and cocoa."},{"title":"Whipped cream tiramisu","intro":"A tiramisu with no raw eggs, ideal for pregnant women.","minutes":25,"calories":460,"difficulty":"Facile","imageSearch":"eggless tiramisu","veg":true,"oven":false,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"mascarpone","plural":"mascarpone","qty":250,"unit":"g","have":false},{"name":"double cream","plural":"double cream","qty":20,"unit":"cl","have":false},{"name":"sugar","plural":"sugar","qty":60,"unit":"g","have":false},{"name":"sponge finger","plural":"sponge fingers","qty":20,"unit":"","have":false},{"name":"strong coffee","plural":"strong coffee","qty":30,"unit":"cl","have":false},{"name":"cocoa powder","plural":"cocoa powder","qty":2,"unit":"tbsp","have":false}],"steps":[{"text":"Whisk the very cold cream with the mascarpone and sugar until firm.","timer":null},{"text":"Dip the sponge fingers in the coffee and alternate them with the cream.","timer":null},{"text":"Chill for 6 h, then dust with cocoa.","timer":{"label":"Chill","min":360}}],"dessert":true,"variant":"No raw eggs","change":"The cream is made with whipped cream."}]$r$::jsonb, 'claude')
