insert into public.recipe_catalog (key, query, aliases, kind, recipes, source) values ('en:creme brulee', 'Crème brûlée', array[]::text[], 'dish', $r$[{"title":"Crème brûlée","intro":"A silky vanilla custard under a thin layer of caramelised sugar.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"creme brulee","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"double cream","plural":"double cream","qty":50,"unit":"cl","have":false},{"name":"egg yolk","plural":"egg yolks","qty":5,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"vanilla pod","plural":"vanilla pods","qty":1,"unit":"","have":false},{"name":"brown sugar","plural":"brown sugar","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 100 °C.","timer":null},{"text":"Heat the cream with the split vanilla pod.","timer":null},{"text":"Whisk the yolks and sugar, then pour in the hot cream, stirring.","timer":null},{"text":"Divide between ramekins and bake for 1 h.","timer":{"label":"Oven","min":60}},{"text":"Leave to cool in the fridge for 3 h, sprinkle with brown sugar and caramelise with a blowtorch or under the grill.","timer":{"label":"Chill","min":180}}],"dessert":true,"variant":"The classic","change":""},{"title":"Coffee crème brûlée","intro":"The crème brûlée, with coffee.","minutes":70,"calories":380,"difficulty":"Moyen","imageSearch":"coffee creme brulee","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"double cream","plural":"double cream","qty":50,"unit":"cl","have":false},{"name":"egg yolk","plural":"egg yolks","qty":5,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":80,"unit":"g","have":false},{"name":"instant coffee","plural":"instant coffee","qty":2,"unit":"tsp","have":false},{"name":"brown sugar","plural":"brown sugar","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 100 °C.","timer":null},{"text":"Heat the cream with the coffee.","timer":null},{"text":"Mix with the beaten yolks and the sugar, and pour into ramekins.","timer":null},{"text":"Bake for 1 h, leave to cool and caramelise the top.","timer":{"label":"Oven","min":60}}],"dessert":true,"variant":"Coffee","change":"Coffee flavours the custard."},{"title":"Pistachio crème brûlée","intro":"A green, indulgent crème brûlée made with pistachio.","minutes":70,"calories":420,"difficulty":"Moyen","imageSearch":"pistachio creme brulee","veg":true,"oven":true,"cold":false,"missing":"","origin":"","serves":4,"items":[{"name":"double cream","plural":"double cream","qty":50,"unit":"cl","have":false},{"name":"egg yolk","plural":"egg yolks","qty":5,"unit":"","have":false},{"name":"sugar","plural":"sugar","qty":70,"unit":"g","have":false},{"name":"pistachio paste","plural":"pistachio paste","qty":40,"unit":"g","have":false},{"name":"brown sugar","plural":"brown sugar","qty":4,"unit":"tbsp","have":false}],"steps":[{"text":"Preheat the oven to 100 °C.","timer":null},{"text":"Heat the cream and add the pistachio paste.","timer":null},{"text":"Mix with the yolks and sugar, and pour into ramekins.","timer":null},{"text":"Bake for 1 h, leave to cool and caramelise.","timer":{"label":"Oven","min":60}}],"dessert":true,"variant":"Pistachio","change":"Pistachio paste flavours the custard."}]$r$::jsonb, 'claude')
